
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

import { LockCardComponent } from '@components/ui/lock-card/lock-card.component';
import { ContractService, LockDetails } from '@services/contract.service';
import { formatTokenAmount, timestampToNumber } from '@utils/formatters';
import { ethers } from 'ethers';
import { RouterModule } from '@angular/router'; // Added RouterModule import
import { IconComponent } from '@components/ui/icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-locks',
    standalone: true,
    imports: [CommonModule, RouterModule, IconComponent, LockCardComponent, TranslateModule],
    templateUrl: './locks.component.html'
})
export class LocksComponent implements OnInit, OnDestroy {
    locks: any[] = []; // All mapped locks
    displayedLocks: any[] = []; // Locks for current page
    isLoading = true;
    totalLocksCount = 0;

    // Pagination & Filter state
    currentPage = 1;
    pageSize = 12;
    statusFilter = 'All'; // 'All' | 'Unlockable' | 'Locked'
    hasVestingFilter = false;
    hasPriceFilter = false;
    selectedTokens: string[] = []; // Array of selected token addresses
    availableTokens: { address: string, symbol: string }[] = [];
    isTokenDropdownOpen = false;

    constructor(private contractService: ContractService, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[LocksComponent] initialized');
        this.loadLocks();

        // Listen for account changes and reload locks
        let previousAccount: string | null = null;
        this.contractService.account$.subscribe(address => {
            if (address) {
                const normalizedAddress = address.toLowerCase();
                if (previousAccount && previousAccount.toLowerCase() !== normalizedAddress) {
                    this.logger.debug('🔄 Locks: Account changed, reloading locks...');
                    this.loadLocks();
                }
                previousAccount = address;
            }
        });
    }

    async loadLocks() {
        this.isLoading = true;
        try {
            this.logger.debug('🔍 [Locks] Starting lock load...');

            // Get all lock IDs
            const lockIds = await this.contractService.getAllLocks();
            this.totalLocksCount = lockIds.length;
            this.logger.debug('📋 [Locks] getAllLocks returned:', lockIds.length, 'IDs:', lockIds);

            if (lockIds.length === 0) {
                this.logger.warn('⚠️ [Locks] No lock IDs returned from getAllLocks()');
                this.locks = [];
                this.displayedLocks = [];
                this.isLoading = false;
                return;
            }

            // Fetch details for each lock in batches
            this.logger.debug('🔄 [Locks] Fetching details for', lockIds.length, 'locks...');
            const batchSize = 50;
            const validDetails: LockDetails[] = [];
            const mappedLocks: any[] = [];

            for (let i = 0; i < lockIds.length; i += batchSize) {
                const batchIds = lockIds.slice(i, i + batchSize);
                const detailsPromises = batchIds.map(lockId => this.contractService.getLockDetails(lockId));
                const details = await Promise.all(detailsPromises);

                const batchValid = details.filter((l): l is LockDetails => l !== null);
                validDetails.push(...batchValid);

                const batchMapped = batchValid.map((detail, index) => {
                    return this.mapLockData(detail, batchIds[index]);
                });
                mappedLocks.push(...batchMapped);
            }

            this.locks = mappedLocks;
            this.logger.debug('🎯 [Locks] Final locks array:', this.locks.length);

            // Extract unique tokens for the multi-select filter
            const tokenMap = new Map<string, string>();
            this.locks.forEach(l => tokenMap.set(l.tokenAddress, l.tokenSymbol));
            this.availableTokens = Array.from(tokenMap.entries()).map(([address, symbol]) => ({ address, symbol }))
                .sort((a, b) => a.symbol.localeCompare(b.symbol));

            // Enrich with current prices (async)
            await this.enrichWithCurrentPrices(validDetails);

            // Apply filters & pagination
            this.applyFilters();
        } catch (e) {
            this.logger.error('❌ [Locks] Failed to load locks:', e);
        } finally {
            this.isLoading = false;
        }
    }

    applyFilters() {
        let filtered = this.locks;

        // Status Filter
        if (this.statusFilter !== 'All') {
            filtered = filtered.filter(lock => lock.status === this.statusFilter);
        }

        // Vesting Filter
        if (this.hasVestingFilter) {
            filtered = filtered.filter(lock => lock.vesting?.isEnabled);
        }

        // Price Filter
        if (this.hasPriceFilter) {
            filtered = filtered.filter(lock => lock.hasPrice);
        }

        // Token Filter
        if (this.selectedTokens.length > 0) {
            filtered = filtered.filter(lock => this.selectedTokens.includes(lock.tokenAddress));
        }

        // Pagination
        const startIndex = (this.currentPage - 1) * this.pageSize;
        const endIndex = startIndex + this.pageSize;
        this.displayedLocks = filtered.slice(startIndex, endIndex);
    }

    get totalPages(): number {
        // Compute dynamically based on current filtered length
        let filtered = this.locks;
        if (this.statusFilter !== 'All') {
            filtered = filtered.filter(lock => lock.status === this.statusFilter);
        }
        if (this.hasVestingFilter) {
            filtered = filtered.filter(lock => lock.vesting?.isEnabled);
        }
        if (this.hasPriceFilter) {
            filtered = filtered.filter(lock => lock.hasPrice);
        }
        if (this.selectedTokens.length > 0) {
            filtered = filtered.filter(lock => this.selectedTokens.includes(lock.tokenAddress));
        }
        return Math.max(1, Math.ceil(filtered.length / this.pageSize));
    }

    changePage(page: number) {
        if (page >= 1 && page <= this.totalPages) {
            this.currentPage = page;
            this.applyFilters();
        }
    }

    toggleVestingFilter() {
        this.hasVestingFilter = !this.hasVestingFilter;
        this.currentPage = 1;
        this.applyFilters();
    }

    togglePriceFilter() {
        this.hasPriceFilter = !this.hasPriceFilter;
        this.currentPage = 1;
        this.applyFilters();
    }

    toggleToken(address: string) {
        const index = this.selectedTokens.indexOf(address);
        if (index === -1) {
            this.selectedTokens.push(address);
        } else {
            this.selectedTokens.splice(index, 1);
        }
        this.currentPage = 1;
        this.applyFilters();
    }

    toggleTokenDropdown() {
        this.isTokenDropdownOpen = !this.isTokenDropdownOpen;
    }

    closeTokenDropdown() {
        this.isTokenDropdownOpen = false;
    }

    onStatusFilterChanged(status: string) {
        this.statusFilter = status;
        this.currentPage = 1;
        this.applyFilters();
    }

    /**
     * Fetch current token prices from PriceCalculator and update valueUSD
     */
    async enrichWithCurrentPrices(validDetails: LockDetails[]) {
        for (let i = 0; i < validDetails.length; i++) {
            const detail = validDetails[i];
            const lock: any = this.locks[i]; // Cast to any since mapLockData returns any

            // Check if this lock has pricing info
            const pricing = detail.lockData.pricing || detail.lockData[1];
            if (!pricing) continue;

            const pairAddress = pricing.uniswapPair || pricing.pairAddress || pricing[0];
            if (!pairAddress || pairAddress === '0x0000000000000000000000000000000000000000') continue;

            try {
                const ethUsdPairAddress = pricing.ethUsdPairAddress || pricing[1];
                const isEthPair = pricing.isEthPair ?? pricing[2];
                const stablecoinPosition = pricing.stablecoinPosition ?? pricing[3];

                const currentPriceUSD1e18 = await this.contractService.getTokenPriceUSD(
                    detail.tokenAddress,
                    pairAddress,
                    ethUsdPairAddress || null,
                    isEthPair,
                    stablecoinPosition
                );

                if (currentPriceUSD1e18 > 0n) {
                    const currentPriceUSD = Number(ethers.formatUnits(currentPriceUSD1e18, 18));
                    const numAmount = parseFloat(lock.amount.replace(/,/g, ''));
                    lock.valueUSD = numAmount * currentPriceUSD;
                    lock.currentPriceUSD = currentPriceUSD; // Add current price info to lock

                    // Also enrich vesting USD amount if applicable
                    if (lock.vesting && lock.vesting.isEnabled && lock.vesting.amountTokens) {
                        const numVestingAmount = parseFloat(lock.vesting.amountTokens.replace(/,/g, ''));
                        lock.vesting.valueUSD = numVestingAmount * currentPriceUSD;
                    }
                }
            } catch (e) {
                this.logger.warn(`Failed to fetch current price for ${lock.tokenSymbol}:`, e);
                // Keep the fallback target price valueUSD
            }
        }

        // After enriching, re-apply filters so displayedLocks get the updated valueUSD
        this.applyFilters();
    }

    mapLockData(detail: LockDetails, lockId: number): any {
        // Map contract data to UI format expected by LockCard
        // Access named properties AND array indices for compatibility
        const basic = detail.lockData.basic || detail.lockData[0];
        const totalAmount = basic?.totalAmount ?? basic?.[1];
        const unlockTime = basic?.unlockTime ?? basic?.[3];
        const lockStartTime = basic?.lockStartTime ?? basic?.[4];
        
        const pricing = detail.lockData.pricing || detail.lockData[1];
        const targetPriceUSD1e18 = pricing?.targetPriceUSD1e18 ?? pricing?.[4];

        // Handle null/undefined values
        if (totalAmount === null || totalAmount === undefined || unlockTime === null || unlockTime === undefined) {
            this.logger.warn('Invalid lock data:', { totalAmount, unlockTime, detail });
            return {
                lockId: lockId, // 🆕 Include lockId
                tokenSymbol: detail.tokenInfo.symbol,
                tokenAddress: detail.tokenAddress,
                amount: '0',
                unlockDate: new Date(),
                timeProgressPercent: 0,
                priceProgressPercent: 0,
                hasPrice: false,
                timeOk: false,
                priceOk: false,
                status: 'Invalid'
            };
        }

        // Use utility functions for safe conversion
        const unlockTimestamp = timestampToNumber(unlockTime);
        const unlockDate = new Date(unlockTimestamp * 1000);

        // Calculate time progress CLIENT-SIDE (for testnet compatibility)
        const now = Date.now();
        const creationTimestamp = lockStartTime ? timestampToNumber(lockStartTime) * 1000 : 0;
        const unlockTimeMs = unlockTimestamp * 1000;

        let timeProgressPercent = 0;
        if (creationTimestamp > 0) {
            const totalDuration = unlockTimeMs - creationTimestamp;
            const elapsed = now - creationTimestamp;
            timeProgressPercent = totalDuration > 0 ? Math.min(Math.max((elapsed / totalDuration) * 100, 0), 100) : 0;
        } else {
            // No creation time, show 0% until unlock passes
            timeProgressPercent = now >= unlockTimeMs ? 100 : 0;
        }

        // Check time status based on client time
        const timeOk = now >= unlockTimeMs;

        // Get status from contract for price info
        const status = detail.status || { timeOk: false, priceOk: false, timeProgressPercent: 0, priceProgressPercent: 0 };
        const priceProgressPercent = Number(status.priceProgressPercent || 0);

        // Check if lock has price target
        const hasPrice = targetPriceUSD1e18 && targetPriceUSD1e18 > 0n;

        // Price status from contract
        const priceOk = hasPrice ? (status.priceOk || false) : false;
        const isUnlockable = hasPrice ? (timeOk || priceOk) : timeOk;

        // Calculate USD value
        const tokenSymbol = detail.tokenInfo.symbol.toUpperCase();
        const isUSDToken = tokenSymbol.includes('USD') || tokenSymbol === 'DAI' || tokenSymbol === 'USDT' || tokenSymbol === 'USDC';
        const formattedAmount = formatTokenAmount(totalAmount, Number(detail.tokenInfo.decimals));
        const numAmount = parseFloat(formattedAmount.replace(/,/g, ''));

        let valueUSD: number | null = null;
        if (isUSDToken) {
            // USD stablecoin: value = amount (1:1 peg)
            valueUSD = numAmount;
        } else if (hasPrice && targetPriceUSD1e18) {
            // Token with price lock: use target price as estimate  
            const targetPriceUSD = Number(ethers.formatUnits(targetPriceUSD1e18, 18));
            valueUSD = numAmount * targetPriceUSD;
        }

        // Map vesting details
        let vestingMapped = null;
        if (detail.vesting && detail.vesting.enabled) {
            const vestingAmountTokens = detail.vesting.amountTokens ?
                formatTokenAmount(detail.vesting.amountTokens, Number(detail.tokenInfo.decimals)) : '0';

            let vestingValueUSD: number | null = null;
            if (detail.vesting.amountUSD && detail.vesting.amountUSD > 0n) {
                vestingValueUSD = Number(ethers.formatUnits(detail.vesting.amountUSD, 18));
            }

            vestingMapped = {
                isEnabled: true,
                amountTokens: vestingAmountTokens,
                valueUSD: vestingValueUSD
            };
        }

        return {
            lockId: lockId, // 🆕 Include lockId for routing and identification
            tokenSymbol: detail.tokenInfo.symbol,
            tokenAddress: detail.tokenAddress,
            amount: formattedAmount,
            valueUSD: valueUSD,
            unlockDate: unlockDate,
            timeProgressPercent: timeProgressPercent,
            priceProgressPercent: priceProgressPercent,
            hasPrice: hasPrice,
            priceDirection: hasPrice ? Number(pricing?.priceDirection ?? pricing?.[8]) : null,
            timeOk: timeOk,
            priceOk: priceOk,
            status: isUnlockable ? 'Unlockable' : 'Locked',
            // Add pricing info for displaying current price
            pricing: hasPrice ? pricing : null,
            vesting: vestingMapped
        };
    }

    ngOnDestroy(): void {
        this.logger.debug('[LocksComponent] destroyed');
    }
}
