import { Component, OnInit, OnDestroy, DestroyRef, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { filter } from 'rxjs/operators';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ContractService } from '@services/contract.service';
import { ToastService } from '@services/toast.service';

import { ConfirmModalService } from '@services/confirm-modal.service';
import { ActivityTrackerService } from '@core/services/activity-tracker.service';
import { QrCodeComponent } from '@components/ui/qr-code/qr-code.component';
import { QrScannerComponent } from '@components/ui/qr-scanner/qr-scanner.component';
import { IconComponent } from '@components/ui/icon/icon.component';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { OfflineWorkflowComponent } from '@components/ui/offline-workflow/offline-workflow.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { ethers } from 'ethers';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-change-owner',
    standalone: true,
    imports: [CommonModule, FormsModule, QrCodeComponent, QrScannerComponent, IconComponent, TranslateModule, OfflineWorkflowComponent, ContactInputComponent],
    templateUrl: './change-owner.component.html'
})
export class ChangeOwnerComponent implements OnInit, OnDestroy {
    private destroyRef = inject(DestroyRef);

    // ─── Change Owner ─────────────────────────────────────────────────────────

    /** Current contract owner address */
    currentOwner = '';
    ownerChangeNonce = 0;

    /** New owner address typed by user */
    batchNewOwner = '';
    executingBatch = false;

    offlineSigningRequest: any = null;
    offlineSigningRequestQr: string | null = null;
    offlineCollectedSignatures: Array<{ signer: string; signature: string }> = [];
    offlineSignerAddress = '';
    offlineSignatureInput = '';
    offlineResponseMode: 'scan' | 'paste' = 'paste';
    offlineResponseJson = '';
    generatingRequest = false;

    /** Cached threshold — starts at 0 to avoid confusing UI before data is ready */
    approvalsThreshold = 0;



    // ─── Rescue Token ─────────────────────────────────────────────────────────

    /** ERC20 address typed by user — validated before any on-chain call */
    rescueToken = '';
    rescueRecipient = '';
    rescueAmount = '';
    tokenInfo: any = null;
    tokenBalance = '0';
    /** True when the token has an active lock — rescue must be blocked */
    isTokenLocked = false;

    constructor(
        private readonly contractService: ContractService,
        private readonly toastService: ToastService,
        private readonly confirmModalService: ConfirmModalService,
        private readonly activityTracker: ActivityTrackerService,
        private readonly translate: TranslateService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[ChangeOwnerComponent] initialized');

        this.contractService.currentLocker$
            .pipe(
                filter(address => !!address),
                takeUntilDestroyed(this.destroyRef)
            )
            .subscribe((lockerAddress) => {
                this.logger.debug('[ChangeOwnerComponent] locker changed to', lockerAddress);
                this.loadOwnerInfo();
                this.loadThreshold();
                if (this.rescueToken) {
                    this.loadTokenInfo();
                }
            });

        this.initializeRescueRecipient();
    }

    // ─── Change Owner helpers ──────────────────────────────────────────────────

    /** Loads the contract's global approvals threshold and caches it locally. */
    async loadThreshold() {
        try {
            const locker = this.contractService.getLockerContract();
            const threshold = await locker['approvalsThreshold']();
            this.approvalsThreshold = Number(threshold);
        } catch (e) {
            // Fail silently — displayed as 0 until data loads
        }
    }

    async loadOwnerInfo() {
        try {
            const locker = this.contractService.getLockerContract();
            this.currentOwner = await locker['owner']();
            this.ownerChangeNonce = Number(await locker['ownerChangeNonce']());
        } catch (e) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.LOAD_INFO_FAILED'));
        }
    }

    // Clears the current QR and signatures when the address changes so the user
    // must regenerate — prevents stale QRs from being shared for the wrong address.
    onNewOwnerChange() {
        this.offlineSigningRequest = null;
        this.offlineSigningRequestQr = null;
        this.offlineCollectedSignatures = [];
    }

    async generateOfflineSigningRequest() {
        if (!ethers.isAddress(this.batchNewOwner)) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.INVALID_ADDRESS'));
            return;
        }
        try {
            this.generatingRequest = true;
            const locker = this.contractService.getLockerContract();
            const lockerAddress = await locker.getAddress();
            await this.loadThreshold();

            this.offlineSigningRequest = {
                version: '2.0',
                type: 'REQUEST',
                operation: 'APPROVE_CHANGE_OWNER',
                chainId: 1337,
                contractAddress: lockerAddress,
                data: {
                    newOwner: this.batchNewOwner,
                    nonce: this.ownerChangeNonce
                },
                timestamp: Date.now()
            };

            this.offlineSigningRequestQr = JSON.stringify(this.offlineSigningRequest);
            this.toastService.success(this.translate.instant('OWNER.SUCCESS.REQ_GENERATED'));

        } catch (e: any) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.REQ_FAILED') + e.message);
        } finally {
            this.generatingRequest = false;
        }
    } handleOfflineResponseScan(data: string) {
        try {
            this.processOfflineResponse(data);
        } catch (e: any) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.INVALID_QR_CODE') + ' ' + e.message);
        }
    } private processOfflineResponse(jsonData: string) {
        const parsed = JSON.parse(jsonData);
        const responses = Array.isArray(parsed) ? parsed : [parsed];
        let addedCount = 0;

        for (const response of responses) {
            if (!response.version || response.type !== 'RESPONSE' || !response.signer || !response.signature) {
                continue;
            }
            if (response.operation !== 'APPROVE_CHANGE_OWNER') {
                continue;
            }
            const alreadyAdded = this.offlineCollectedSignatures.find(
                s => s.signer.toLowerCase() === response.signer.toLowerCase()
            );
            if (alreadyAdded) {
                continue;
            }
            this.offlineCollectedSignatures.push({
                signer: response.signer,
                signature: response.signature
            });
            addedCount++;
        }

        if (!addedCount) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.NO_VALID_SIGS'));
            return;
        }

        this.toastService.success(
            this.translate.instant('OWNER.SUCCESS.SIGS_ADDED', {
                count: addedCount,
                total: this.offlineCollectedSignatures.length,
                threshold: this.approvalsThreshold
            })
        );
    }

    async executeWithOfflineSignatures() {
        if (this.offlineCollectedSignatures.length < this.approvalsThreshold) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.NEED_MORE_SIGS', { threshold: this.approvalsThreshold }));
            return;
        }

        try {
            this.executingBatch = true;
            const locker = this.contractService.getLockerContract();
            const signers: string[] = this.offlineCollectedSignatures.map(s => s.signer);
            const signatures: string[] = this.offlineCollectedSignatures.map(s => s.signature);

            const tx = await locker['proposeNewOwnerWithSignatures'](this.batchNewOwner, signers, signatures);
            await tx.wait();

            this.toastService.success(this.translate.instant('OWNER.SUCCESS.CHANGED'));
            this.resetOfflineMode();
            this.batchNewOwner = '';
            await this.loadOwnerInfo();

        } catch (e: any) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.EXECUTE_FAILED') + (e.message || 'Unknown error'));
        } finally {
            this.executingBatch = false;
        }
    }

    resetOfflineMode() {
        this.offlineSigningRequest = null;
        this.offlineCollectedSignatures = [];
        this.offlineSignerAddress = '';
        this.offlineSignatureInput = '';
    }

    // ─── Rescue Token ──────────────────────────────────────────────────────────

    /** Pre-fills recipient with the connected wallet address. */
    async initializeRescueRecipient() {
        const account = this.contractService.account$.value;
        if (account) {
            this.rescueRecipient = account;
        }
    }



    /** Triggers token info fetch when the user types a new address. */
    onRescueTokenChange() {
        this.tokenInfo = null;
        this.tokenBalance = '0';
        this.isTokenLocked = false;
        this.loadTokenInfo();
    }

    /** Fetches token metadata, the contract balance, and checks if token is locked. */
    async loadTokenInfo() {
        if (!this.rescueToken || !ethers.isAddress(this.rescueToken)) {
            this.tokenInfo = null;
            this.isTokenLocked = false;
            return;
        }

        // First: resolve token metadata — bail out entirely if this fails (not an ERC20)
        try {
            this.tokenInfo = await this.contractService.getTokenInfo(this.rescueToken);
        } catch {
            this.tokenInfo = null;
            this.isTokenLocked = false;
            return;
        }

        // Second: fetch contract balance + lock status independently
        // If this fails we keep tokenInfo but reset isTokenLocked to safe default
        try {
            const locker = this.contractService.getLockerContract();
            const lockerAddress = await locker.getAddress();
            const token = this.contractService.getERC20Contract(this.rescueToken);
            const balance = await token['balanceOf'](lockerAddress);
            this.tokenBalance = ethers.formatUnits(balance, this.tokenInfo.decimals);

            // We check if the token is in the list of currently locked tokens
            // getLockedTokenAddresses returns actual ERC20 contract addresses (lowercase)
            const lockedTokenAddresses = await this.contractService.getLockedTokenAddresses();
            this.isTokenLocked = lockedTokenAddresses.includes(this.rescueToken.toLowerCase());
        } catch {
            this.isTokenLocked = false;
        }
    }

    setMaxRescue() {
        this.rescueAmount = this.tokenBalance;
    }

    useMyAddressForRescue() {
        const account = this.contractService.account$.value;
        if (account) {
            this.rescueRecipient = account;
            this.toastService.success(this.translate.instant('OWNER.SUCCESS.USING_WALLET_ADDR'));
        } else {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.NO_WALLET_ADDR'));
        }
    }

    /** Validates inputs, checks the token is not locked, confirms with modal, then calls executeRescue. */
    async executeRescue() {
        if (!ethers.isAddress(this.rescueToken)) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.INVALID_TOKEN'));
            return;
        }
        if (!ethers.isAddress(this.rescueRecipient)) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.INVALID_ADDRESS'));
            return;
        }
        if (!this.rescueAmount || Number(this.rescueAmount) <= 0) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.INVALID_AMOUNT'));
            return;
        }

        try {
            const locker = this.contractService.getLockerContract();
            const lock = await locker['locks'](this.rescueToken);

            // lock[0] = lock.basic.token — zero address means no lock exists
            const lockToken = lock.basic?.token || lock[0];
            const isLocked = lockToken && lockToken !== ethers.ZeroAddress;
            if (isLocked) {
                this.toastService.warning(this.translate.instant('OWNER.WARNINGS.TOKEN_LOCKED'));
                return;
            }

            const confirmed = await this.confirmModalService.confirm(
                this.translate.instant('OWNER.CONFIRM_RESCUE', {
                    amount: this.rescueAmount,
                    token: this.tokenInfo?.symbol || 'tokens',
                    recipient: this.rescueRecipient
                })
            );
            if (!confirmed) {
                return;
            }

            const token = this.contractService.getERC20Contract(this.rescueToken);
            const decimals = await token['decimals']();
            const amountWei = ethers.parseUnits(this.rescueAmount, decimals);
            const account = this.contractService.account$.value;

            await this.activityTracker.trackTransaction(
                'RESCUE_TOKEN',
                account!,
                {
                    token: this.rescueToken,
                    tokenSymbol: this.tokenInfo?.symbol,
                    amount: this.rescueAmount,
                    recipient: this.rescueRecipient
                },
                locker['executeRescue'](this.rescueToken, this.rescueRecipient, amountWei),
                locker
            );

            this.toastService.success(this.translate.instant('OWNER.SUCCESS.RESCUED'));
            this.rescueAmount = '';
            this.loadTokenInfo();
        } catch (e: any) {
            this.toastService.error(this.translate.instant('OWNER.ERRORS.RESCUE_FAILED') + e.message);
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[ChangeOwnerComponent] destroyed');
    }
}
