import { Injectable } from '@angular/core';
import { LoggerService } from "@services/logger.service";

/**
 * EncryptionService
 * Provides AES-GCM encryption/decryption using Web Crypto API
 * with PBKDF2 key derivation for secure mnemonic storage
 */
@Injectable({
    providedIn: 'root'
})
export class EncryptionService {
    private readonly PBKDF2_ITERATIONS = 100000;
    private readonly KEY_LENGTH = 256;

    constructor(private logger: LoggerService) { }

    /**
     * Encrypt data with password using AES-GCM
     * @param data - Plain text data to encrypt
     * @param password - User password
     * @returns Base64-encoded encrypted payload with IV and salt
     */
    async encrypt(data: string, password: string): Promise<string> {
        try {
            // Generate random salt and IV
            const salt = crypto.getRandomValues(new Uint8Array(16));
            const iv = crypto.getRandomValues(new Uint8Array(12));

            // Derive key from password
            const key = await this.deriveKey(password, salt);

            // Encrypt data
            const encoder = new TextEncoder();
            const dataBuffer = encoder.encode(data);

            const encryptedBuffer = await crypto.subtle.encrypt(
                {
                    name: 'AES-GCM',
                    iv: iv
                },
                key,
                dataBuffer
            );

            // Combine salt + iv + encrypted data
            const encryptedArray = new Uint8Array(encryptedBuffer);
            const combined = new Uint8Array(salt.length + iv.length + encryptedArray.length);
            combined.set(salt, 0);
            combined.set(iv, salt.length);
            combined.set(encryptedArray, salt.length + iv.length);

            // Return as base64
            return this.arrayBufferToBase64(combined);
        } catch (error) {
            this.logger.error('Encryption failed:', error);
            throw new Error('Failed to encrypt data');
        }
    }

    /**
     * Decrypt data with password
     * @param encryptedData - Base64-encoded encrypted payload
     * @param password - User password
     * @returns Decrypted plain text
     */
    async decrypt(encryptedData: string, password: string): Promise<string> {
        try {
            // Decode base64
            const combined = this.base64ToArrayBuffer(encryptedData);

            // Extract salt, iv, and encrypted data
            const salt = combined.slice(0, 16);
            const iv = combined.slice(16, 28);
            const encrypted = combined.slice(28);

            // Derive key from password
            const key = await this.deriveKey(password, salt);

            // Decrypt data
            const decryptedBuffer = await crypto.subtle.decrypt(
                {
                    name: 'AES-GCM',
                    iv: iv
                },
                key,
                encrypted
            );

            // Convert to string
            const decoder = new TextDecoder();
            return decoder.decode(decryptedBuffer);
        } catch (error) {
            this.logger.error('Decryption failed:', error);
            throw new Error('Failed to decrypt data - wrong password or corrupted data');
        }
    }

    /**
     * Derive encryption key from password using PBKDF2
     * @param password - User password
     * @param salt - Salt for key derivation
     * @returns CryptoKey for AES-GCM
     */
    private async deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
        const encoder = new TextEncoder();
        const passwordBuffer = encoder.encode(password);

        // Import password as key material
        const keyMaterial = await crypto.subtle.importKey(
            'raw',
            passwordBuffer,
            'PBKDF2',
            false,
            ['deriveBits', 'deriveKey']
        );

        // Derive key using PBKDF2
        return await crypto.subtle.deriveKey(
            {
                name: 'PBKDF2',
                salt: salt,
                iterations: this.PBKDF2_ITERATIONS,
                hash: 'SHA-256'
            },
            keyMaterial,
            {
                name: 'AES-GCM',
                length: this.KEY_LENGTH
            },
            false,
            ['encrypt', 'decrypt']
        );
    }

    /**
     * Convert ArrayBuffer to Base64 string
     */
    private arrayBufferToBase64(buffer: Uint8Array): string {
        let binary = '';
        const bytes = new Uint8Array(buffer);
        for (let i = 0; i < bytes.byteLength; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return btoa(binary);
    }

    /**
     * Convert Base64 string to ArrayBuffer
     */
    private base64ToArrayBuffer(base64: string): Uint8Array {
        const binary = atob(base64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
            bytes[i] = binary.charCodeAt(i);
        }
        return bytes;
    }

    /**
     * Hash a password using SHA-256 for verification purposes
     * @param password - Password to hash
     * @returns Base64-encoded hash
     */
    async hashPassword(password: string): Promise<string> {
        const encoder = new TextEncoder();
        const data = encoder.encode(password);
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        return this.arrayBufferToBase64(new Uint8Array(hashBuffer));
    }
}
