import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { ethers } from 'ethers';
import { ContractService } from './contract.service';
import { TransactionInterceptorService, TransactionMode } from './transaction-interceptor.service';
import { TransactionPreviewService } from './transaction-preview.service';
import { ActivityTrackerService } from '@core/services/activity-tracker.service';
import { ToastService } from './toast.service';
import { LoggerService } from "@services/logger.service";

export interface CreateLockParams {
    tokenAddress: string;
    tokenSymbol: string;
    tokenDecimals: number;
    amount: string;
    durationSeconds: number;
    enablePriceTarget: boolean;
    pairAddr: string;
    ethPairAddr: string;
    targetPriceWei: string;
    targetPriceFormatted: string;
    isEthPair: boolean;
    stablecoinPos: number;
    priceDirection: number;
    enableVesting: boolean;
    vestingUSDPerPeriod: string;
    vestingPeriodSeconds: string;
    vestingIsStablecoin: boolean;
    mustUseStablecoinForVesting: boolean;
    currentPriceFormatted: string;
    fromAddress?: string;
}

@Injectable({
    providedIn: 'root'
})
export class LockService {
    constructor(
        private contractService: ContractService,
        private txInterceptor: TransactionInterceptorService,
        private transactionPreviewService: TransactionPreviewService,
        private activityTracker: ActivityTrackerService,
        private toastService: ToastService,
        private router: Router, private logger: LoggerService
    ) { }

    async createLock(
        params: CreateLockParams,
        onAllowanceChecked?: () => void,
        onApprovalDone?: () => void,
        forceMode?: TransactionMode
    ): Promise<boolean> {
        try {
            const amountWei = ethers.parseUnits(params.amount.toString(), params.tokenDecimals);
            const locker = this.contractService.getLockerContract();
            const lockerAddress = await locker.getAddress();
            const token = this.contractService.getERC20Contract(params.tokenAddress);
            const account = params.fromAddress || this.contractService.account$.value;

            const allowance = await token['allowance'](account, lockerAddress);
            const signer = locker.runner as ethers.Signer;

            // Prepare Request Objects
            const approveData = token.interface.encodeFunctionData('approve', [lockerAddress, ethers.MaxUint256]);
            const approveReq = {
                to: params.tokenAddress,
                data: approveData,
                forceMode: forceMode,
                suggestedOfflineSender: params.fromAddress,
                metadata: {
                    operation: 'Approve Token',
                    contract: params.tokenSymbol,
                    function: 'approve',
                    args: { spender: lockerAddress, amount: 'MaxUint256' }
                }
            };

            const vestingUSDWei = params.enableVesting ? ethers.parseEther(params.vestingUSDPerPeriod) : 0n;
            const vestingPeriodBn = params.enableVesting ? BigInt(parseInt(params.vestingPeriodSeconds) || 0) : 0n;
            const vestingIsStable = params.enableVesting ? (params.mustUseStablecoinForVesting || params.vestingIsStablecoin) : false;

            const dataToEncode = {
                token: params.tokenAddress,
                amount: amountWei.toString(),
                lockDuration: params.durationSeconds,
                pair: params.pairAddr,
                ethUsdPair: params.ethPairAddr,
                targetPriceUSD1e18: params.targetPriceWei.toString(),
                isEthPair: params.enablePriceTarget ? params.isEthPair : false,
                stablecoinPosition: params.enablePriceTarget ? params.stablecoinPos : 0,
                priceDirection: params.enablePriceTarget ? params.priceDirection : 0,
                vestingUSDPerPeriod: vestingUSDWei.toString(),
                vestingPeriodSeconds: vestingPeriodBn.toString(),
                vestingIsStablecoin: vestingIsStable
            };

            const createLockData = locker.interface.encodeFunctionData('createLock', [dataToEncode]);
            const createLockReq = {
                to: lockerAddress,
                data: createLockData,
                suggestedOfflineSender: params.fromAddress,
                forceMode: forceMode,
                metadata: {
                    operation: 'Create Lock',
                    contract: 'Locker',
                    function: 'createLock',
                    args: { token: params.tokenSymbol, amount: params.amount }
                }
            };

            // BATCH OFFLINE LOGIC
            // If offline, bundle and execute instantly bypassing UI previews
            if (forceMode === TransactionMode.OFFLINE) {
                const reqs = [];
                if (allowance < amountWei) reqs.push(approveReq);
                reqs.push(createLockReq);

                const receipt = await this.txInterceptor.executeTransaction(reqs, signer);
                if (receipt) {
                    await this.activityTracker.trackTransaction(
                        'CREATE_LOCK',
                        account!,
                        {
                            token: params.tokenAddress,
                            tokenSymbol: params.tokenSymbol,
                            amount: params.amount,
                            durationSeconds: params.durationSeconds,
                            targetPrice: params.targetPriceFormatted || undefined,
                            pairAddress: params.pairAddr !== ethers.ZeroAddress ? params.pairAddr : undefined
                        },
                        Promise.resolve(receipt),
                        locker
                    );
                    this.toastService.success("Lock Created Successfully!");
                    this.router.navigate(['/locks']);
                    return true;
                }
                return false;
            }

            // Fallback for DIRECT execution sequential flow (keeps Transaction Preview popups active)
            if (allowance < amountWei) {
                onAllowanceChecked?.();

                await new Promise<void>((resolve, reject) => {
                    this.transactionPreviewService.show({
                        action: 'Approve Token',
                        token: params.tokenSymbol,
                        tokenAddress: params.tokenAddress,
                        spender: lockerAddress,
                        amount: 'Unlimited (MaxUint256)'
                    }, async () => {
                        try {
                            const receipt = await this.txInterceptor.executeTransaction(approveReq, signer);

                            if (receipt) {
                                if (typeof receipt.wait === 'function') {
                                    await receipt.wait();
                                }
                                onApprovalDone?.();
                                resolve();
                            } else {
                                this.toastService.info('Approval sent for offline signing.');
                                onApprovalDone?.();
                                reject(new Error('Offline signing required'));
                            }
                        } catch (e: any) {
                            onApprovalDone?.();
                            reject(e);
                        }
                    }, () => {
                        onApprovalDone?.();
                        reject(new Error('User cancelled approval'));
                    });
                });

                await new Promise(resolve => setTimeout(resolve, 300));
            }

            // Create Lock Preview
            return new Promise<boolean>((resolve, reject) => {
                const previewData: any = {
                    action: 'Create Lock',
                    token: params.tokenSymbol,
                    tokenAddress: params.tokenAddress,
                    amount: params.amount,
                    amountWei: amountWei.toString(),
                    durationSeconds: params.durationSeconds,
                    unlockDate: new Date(Date.now() + params.durationSeconds * 1000).toISOString()
                };

                if (params.enablePriceTarget && params.targetPriceWei !== '0' && params.pairAddr !== ethers.ZeroAddress) {
                    previewData.priceTarget = {
                        enabled: true,
                        targetPrice: params.targetPriceFormatted + ' USD',
                        targetPriceWei: params.targetPriceWei,
                        uniswapPair: params.pairAddr,
                        ethUsdPair: params.ethPairAddr === ethers.ZeroAddress ? 'None (Direct)' : params.ethPairAddr,
                        isEthPair: params.isEthPair,
                        stablecoinPosition: params.stablecoinPos,
                        currentPrice: params.currentPriceFormatted
                    };
                }

                this.transactionPreviewService.show(previewData, async () => {
                    try {
                        const receipt = await this.txInterceptor.executeTransaction(createLockReq, signer);

                        if (receipt) {
                            await this.activityTracker.trackTransaction(
                                'CREATE_LOCK',
                                account!,
                                {
                                    token: params.tokenAddress,
                                    tokenSymbol: params.tokenSymbol,
                                    amount: params.amount,
                                    durationSeconds: params.durationSeconds,
                                    targetPrice: params.targetPriceFormatted || undefined,
                                    pairAddress: params.pairAddr !== ethers.ZeroAddress ? params.pairAddr : undefined
                                },
                                Promise.resolve(receipt),
                                locker
                            );
                            this.toastService.success("Lock Created Successfully!");
                            this.router.navigate(['/locks']);
                            resolve(true);
                        } else {
                            resolve(false);
                        }
                    } catch (e: any) {
                        reject(e);
                    }
                }, () => {
                    reject(new Error('User cancelled transaction'));
                });
            });
        } catch (e: any) {
            if (e.message !== 'Offline signing required' && e.message !== 'User cancelled transaction' && e.message !== 'User cancelled approval') {
                this.toastService.error("Error: " + e.message);
            }
            return false;
        }
    }

    async executeUnlock(
        lockId: number,
        amount: string,
        tokenDecimals: number,
        tokenAddress: string,
        tokenSymbol: string,
        recipient: string,
        fromAddress?: string
    ): Promise<boolean> {
        try {
            const locker = this.contractService.getLockerContract();
            const amountWei = ethers.parseUnits(amount.toString(), tokenDecimals);
            const account = this.contractService.account$.value;
            const lockerAddress = await locker.getAddress();

            const data = locker.interface.encodeFunctionData('executeUnlock', [
                lockId,
                recipient,
                amountWei,
                100 // slippage
            ]);

            const signer = locker.runner as any;
            const receipt = await this.txInterceptor.executeTransaction({
                to: lockerAddress,
                data: data,
                suggestedOfflineSender: fromAddress,
                metadata: {
                    operation: 'Unlock Tokens',
                    contract: 'LockerContract',
                    function: 'executeUnlock',
                    args: { lockId, recipient, amount, slippage: '100%' }
                }
            }, signer);

            if (receipt === null) {
                this.toastService.info('Transaction sent for offline signing');
                return false;
            }

            await this.activityTracker.trackTransaction(
                'UNLOCK',
                account!,
                { lockId, token: tokenAddress, tokenSymbol, amount, recipient },
                Promise.resolve(receipt),
                locker
            );

            this.toastService.success("Unlocked successfully!");
            return true;
        } catch (e: any) {
            this.toastService.error("Error: " + e.message);
            return false;
        }
    }

    async executeVestingUnlock(
        lockId: number,
        tokenAddress: string,
        tokenSymbol: string,
        amountAvailable: string,
        signerAddress: string,
        signature: string,
        recipient: string,
        fromAddress?: string
    ): Promise<boolean> {
        try {
            const locker = this.contractService.getLockerContract();
            const lockerAddress = await locker.getAddress();
            const lockerSigner = locker.runner as any;
            const account = this.contractService.account$.value;

            const calldata = locker.interface.encodeFunctionData('unlockVestedWithSignatures', [
                lockId,
                recipient,
                signerAddress,
                signature
            ]);

            const txResult = await this.txInterceptor.executeTransaction(
                {
                    to: lockerAddress,
                    data: calldata,
                    suggestedOfflineSender: fromAddress,
                    metadata: {
                        operation: 'Vesting Unlock',
                        contract: 'LockerContract',
                        function: 'unlockVestedWithSignatures',
                        args: { lockId, recipient, signer: signerAddress }
                    }
                },
                lockerSigner
            );

            if (txResult) {
                await this.activityTracker.trackTransaction(
                    'VESTING_UNLOCK',
                    account!,
                    { token: tokenAddress, tokenSymbol, amount: amountAvailable, recipient, signers: [signerAddress] },
                    Promise.resolve(txResult),
                    locker
                );
                this.toastService.success('✅ Vested tokens unlocked successfully!');
                return true;
            } else {
                this.toastService.info('📱 Transaction sent for offline signing');
                return false;
            }
        } catch (e: any) {
            this.logger.error('Failed to execute vesting unlock', e);
            const reason = e?.reason ?? e?.message ?? '';

            if (reason.includes('USE_REGULAR_UNLOCK')) {
                this.toastService.error('⏰ Lock already unlockable — use the standard unlock instead of vesting unlock.');
            } else if (reason.includes('VESTING_NOT_AVAILABLE')) {
                this.toastService.error('⏳ No vested amount available yet. Wait for the next vesting period.');
            } else if (reason.includes('Not a signer')) {
                this.toastService.error('❌ Signer is not authorized. Re-verify signers.');
            } else if (reason.includes('INV_SIG')) {
                this.toastService.error('❌ Invalid or replayed signature.');
            } else {
                this.toastService.error('Error executing vesting unlock: ' + reason);
            }
            return false;
        }
    }

    async addToLock(
        lockId: number,
        amount: string,
        tokenDecimals: number,
        tokenAddress: string,
        tokenSymbol: string,
        fromAddress?: string,
        forceMode?: TransactionMode
    ): Promise<boolean> {
        try {
            const locker = this.contractService.getLockerContract();
            const lockerAddress = await locker.getAddress();
            const token = this.contractService.getERC20Contract(tokenAddress);
            const account = fromAddress || this.contractService.account$.value;
            const signer = locker.runner as any;

            const amountWei = ethers.parseUnits(amount.toString(), tokenDecimals);
            const allowance = await token['allowance'](account, lockerAddress);

            const reqs = [];

            if (allowance < amountWei) {
                const approvalData = token.interface.encodeFunctionData('approve', [lockerAddress, ethers.MaxUint256]);
                reqs.push({
                    to: tokenAddress,
                    data: approvalData,
                    forceMode: forceMode,
                    suggestedOfflineSender: fromAddress,
                    metadata: {
                        operation: 'Approve Token',
                        contract: tokenSymbol,
                        function: 'approve',
                        args: { spender: 'LockerContract', amount: 'Unlimited' }
                    }
                });
            }

            const data = locker.interface.encodeFunctionData('addToLock', [lockId, amountWei]);
            reqs.push({
                to: lockerAddress,
                data: data,
                forceMode: forceMode,
                suggestedOfflineSender: fromAddress,
                metadata: {
                    operation: 'Add to Lock',
                    contract: 'LockerContract',
                    function: 'addToLock',
                    args: { lockId, token: tokenAddress, tokenSymbol, amount }
                }
            });

            const receipt = await this.txInterceptor.executeTransaction(reqs, signer);

            if (receipt === null) {
                this.toastService.info('Transaction cancelled or sent for offline signing');
                return false;
            }

            await this.activityTracker.trackTransaction(
                'ADD_TO_LOCK',
                account!,
                { lockId, token: tokenAddress, tokenSymbol, amount },
                Promise.resolve(receipt),
                locker
            );

            this.toastService.success("Added to lock successfully!");
            return true;
        } catch (e: any) {
            this.logger.error(e);
            this.toastService.error("Error: " + e.message);
            return false;
        }
    }
}
