import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ContractService } from '@services/contract.service';
import { ConfigService } from '@services/config.service';
import { ToastService } from '@services/toast.service';
import { ConfirmModalService } from '@services/confirm-modal.service';
import { getPairs, getEthUsdPairs, PairConfig } from '@core/token-config';
import { ethers } from 'ethers';
import { LoggerService } from "@services/logger.service";

interface PairOption {
    name: string;
    address: string;
}

@Component({
    selector: 'app-test-utils',
    standalone: true,
    imports: [CommonModule, FormsModule],
    templateUrl: './test-utils.component.html'
})
export class TestUtilsComponent implements OnInit, OnDestroy {
    selectedPair = '';
    customPairAddress = '';
    reserve0 = '1000000';
    reserve1 = '500';
    wei0 = '';
    wei1 = '';
    currentReserves: any = null;
    pricePreview = '';
    error = '';
    loading = false;
    executing = false;
    stablecoinPos = 2; // 0=None(ETH), 1=Token0, 2=Token1
    ethPriceUSD = 2000;
    currentTokenAddress = '';

    pairs: PairOption[] = [];
    availablePairs: PairConfig[] = []; // Full pair configs from token-config


    constructor(
        private contractService: ContractService,
        public configService: ConfigService,
        private toastService: ToastService,
        private confirmModalService: ConfirmModalService, 
        private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[TestUtilsComponent] initialized');
        // Load full pair configs for stablecoin position lookup
        this.availablePairs = getPairs(this.configService.mode);
        this.loadPairs();
        this.fetchEthPrice();
    }

    async fetchEthPrice() {
        try {
            const wethConfig = getEthUsdPairs(this.configService.mode)[0];
            if (wethConfig) {
                const wethAddr = this.configService.contracts['WETH'];
                const price = await this.contractService.getTokenPriceUSD(
                    wethAddr,
                    wethConfig.address,
                    null,
                    false,
                    wethConfig.stablecoinPosition
                );
                
                if (price > 0n) {
                    this.ethPriceUSD = parseFloat(ethers.formatUnits(price, 18));
                    this.logger.debug('Fetched ETH Price for utils: $', this.ethPriceUSD);
                }
            }
        } catch(e) {
            this.logger.error('Failed to fetch eth price for utils', e);
        }
    }

    loadPairs() {
        const contracts = this.configService.contracts as any; // Cast to access test-only properties

        // Use the centrally defined pair configurations rather than hardcoding.
        // availablePairs is already populated via getPairs(this.configService.mode)
        this.pairs = this.availablePairs.map(config => {
            return {
                name: `${config.name} (${config.version === 'V2' ? 'V2' : 'V3'})`,
                address: config.address
            }
        });

        // Push some Mocks if they exist for tests 
        if (contracts['MockPair1']) {
            this.pairs.push({ name: 'Mock Pair 1', address: contracts['MockPair1'] });
        }
        if (contracts['MockPair2']) {
            this.pairs.push({ name: 'Mock Pair 2', address: contracts['MockPair2'] });
        }

        this.pairs = this.pairs.filter(p => p.address);
    }

    onPairChange() {
        if (this.selectedPair && this.selectedPair !== 'custom') {
            // Auto-fill stablecoin position from pair config
            const pairConfig = this.availablePairs.find(p => p.address.toLowerCase() === this.selectedPair.toLowerCase());
            if (pairConfig) {
                this.stablecoinPos = pairConfig.stablecoinPosition;
                this.currentTokenAddress = pairConfig.tokenAddress;
                this.logger.debug(`Auto-filled stablecoinPos: ${this.stablecoinPos} for pair ${pairConfig.name}`);
            }
            this.loadPairInfo();
        }
    }

    async loadPairInfo() {
        this.loading = true;
        this.error = '';
        try {
            const pairAddress = this.selectedPair === 'custom' ? this.customPairAddress : this.selectedPair;
            if (!ethers.isAddress(pairAddress)) {
                throw new Error('Invalid pair address');
            }

            // Detect if V3 based on pair name
            const isV3 = this.pairs.find(p => p.address === pairAddress)?.name.includes('V3') || false;

            // Use the locker contract's provider
            const locker = this.contractService.getLockerContract();
            const provider = locker.runner?.provider || locker.runner;

            if (isV3) {
                // V3 pair: use slot0() and liquidity
                const v3PairAbi = [
                    'function slot0() external view returns (uint160 sqrtPriceX96, int24 tick, uint16 observationIndex, uint16 observationCardinality, uint16 observationCardinalityNext, uint8 feeProtocol, bool unlocked)',
                    'function liquidity() external view returns (uint128)',
                    'function token0() external view returns (address)',
                    'function token1() external view returns (address)'
                ];
                const pair = new ethers.Contract(pairAddress, v3PairAbi, provider);

                
                const [slot0Result, , token0, token1] = await Promise.all([
                    pair['slot0'](),
                    pair['liquidity'](),
                    pair['token0'](),
                    pair['token1']()
                ]);

                const sqrtPriceX96 = slot0Result[0];

                // Get decimals
                const token0Contract = new ethers.Contract(token0, ['function decimals() external view returns (uint8)'], provider);
                const token1Contract = new ethers.Contract(token1, ['function decimals() external view returns (uint8)'], provider);
                const [decimals0, decimals1] = await Promise.all([
                    token0Contract['decimals'](),
                    token1Contract['decimals']()
                ]);

                // Calculate price from sqrtPriceX96 exactly like PriceCalculator.sol
                const sqrtPriceX96Big = BigInt(sqrtPriceX96);
                const priceX192 = sqrtPriceX96Big * sqrtPriceX96Big;
                const Q192 = BigInt(2) ** BigInt(192);
                
                const n0 = priceX192 * (BigInt(10) ** BigInt(decimals0));
                const oneE18 = BigInt(10) ** BigInt(18);
                const q = (n0 * oneE18) / Q192;
                const truePrice1e18 = q / (BigInt(10) ** BigInt(decimals1));

                // Calcul humain
                const reserve0Human = '1000000';
                const reserve0Wei18 = ethers.parseUnits(reserve0Human, 18);
                const reserve1Wei18 = (reserve0Wei18 * truePrice1e18) / oneE18;
                const reserve1Human = ethers.formatUnits(reserve1Wei18, 18);

                this.currentReserves = {
                    reserve0: reserve0Human,
                    reserve1: reserve1Human,
                    token0,
                    token1,
                    isV3: true,
                    decimals0: Number(decimals0),
                    decimals1: Number(decimals1)
                };


                this.reserve0 = parseFloat(this.currentReserves.reserve0).toString();
                this.reserve1 = parseFloat(this.currentReserves.reserve1).toString();

            } else {
                // V2 pair: use getReserves()
                const v2PairAbi = [
                    'function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast)',
                    'function token0() external view returns (address)',
                    'function token1() external view returns (address)'
                ];
                const pair = new ethers.Contract(pairAddress, v2PairAbi, provider);

                
                const [reserve0, reserve1] = await pair['getReserves']();
                const token0 = await pair['token0']();
                const token1 = await pair['token1']();
                
                // Get decimals
                const token0Contract = new ethers.Contract(token0, ['function decimals() external view returns (uint8)'], provider);
                const token1Contract = new ethers.Contract(token1, ['function decimals() external view returns (uint8)'], provider);
                const [decimals0, decimals1] = await Promise.all([
                    token0Contract['decimals'](),
                    token1Contract['decimals']()
                ]);

                this.currentReserves = {
                    reserve0: ethers.formatUnits(reserve0, decimals0),
                    reserve1: ethers.formatUnits(reserve1, decimals1),
                    token0,
                    token1,
                    isV3: false,
                    decimals0: Number(decimals0),
                    decimals1: Number(decimals1)
                };


                this.reserve0 = parseFloat(this.currentReserves.reserve0).toString();
                this.reserve1 = parseFloat(this.currentReserves.reserve1).toString();
            }

            this.updateWei();
        } catch (e: any) {
            this.error = e.message || 'Failed to load pair info';
        } finally {
            this.loading = false;
        }
    }

    setPreset(priceUSD: number) {
        const tokenAmount = 1000000;
        const usdcAmount = tokenAmount * priceUSD;

        if (this.stablecoinPos === 1) {
            this.reserve0 = usdcAmount.toString();
            this.reserve1 = tokenAmount.toString();
        } else if (this.stablecoinPos === 2) {
            this.reserve0 = tokenAmount.toString();
            this.reserve1 = usdcAmount.toString();
        } else {
            // ETH pair
            const ethEquivalent = priceUSD / (this.ethPriceUSD || 2000);
            let token0IsWeth = false;
            if (this.currentReserves) {
                token0IsWeth = (this.currentReserves.token0?.toLowerCase() === this.configService.contracts['WETH']?.toLowerCase());
            } else if (this.pairs.find(p => p.address === this.selectedPair)?.name.startsWith('WETH/')) {
                token0IsWeth = true;
            }
            if (token0IsWeth) {
                this.reserve0 = (tokenAmount * ethEquivalent).toString();
                this.reserve1 = tokenAmount.toString();
            } else {
                this.reserve0 = tokenAmount.toString();
                this.reserve1 = (tokenAmount * ethEquivalent).toString();
            }
        }
        this.updateWei();
    }

    updateWei() {

        try {
            const dec0 = this.currentReserves?.decimals0 || 18;
            const dec1 = this.currentReserves?.decimals1 || 18;
            const wei0 = ethers.parseUnits(this.reserve0 || '0', dec0);
            const wei1 = ethers.parseUnits(this.reserve1 || '0', dec1);
            this.wei0 = wei0.toString();
            this.wei1 = wei1.toString();


            // Calculate price based on stablecoin position
            const r0 = parseFloat(this.reserve0 || '0');
            const r1 = parseFloat(this.reserve1 || '0');
            if (r0 > 0 && r1 > 0) {
                let usdPrice = 0;
                
                if (this.stablecoinPos === 1) {
                    usdPrice = r0 / r1;
                } else if (this.stablecoinPos === 2) {
                    usdPrice = r1 / r0;
                } else {
                    let ethPrice = this.ethPriceUSD || 2000;
                    if (this.currentReserves) {
                        let token0IsWeth = false;
                        if (this.currentReserves.token0) {
                            token0IsWeth = (this.currentReserves.token0.toLowerCase() === this.configService.contracts['WETH']?.toLowerCase());
                        }
                        if (token0IsWeth) {
                            usdPrice = (r0 / r1) * ethPrice;
                        } else {
                            usdPrice = (r1 / r0) * ethPrice;
                        }
                    } else if (this.pairs.find(p => p.address === this.selectedPair)?.name.startsWith('WETH/')) {
                        usdPrice = (r0 / r1) * ethPrice;
                    } else {
                        usdPrice = (r1 / r0) * ethPrice;
                    }
                }
                
                if (usdPrice > 0) {
                    this.pricePreview = `$${usdPrice.toFixed(6)} par token`;
                }
            } else {
                this.pricePreview = '';
            }
        } catch (e) {
            this.wei0 = '';
            this.wei1 = '';
            this.pricePreview = '';
        }
    }

    async executeSetReserves() {
        this.logger.debug('🔵 [SET RESERVES] Starting set reserves process...', {
            selectedPair: this.selectedPair,
            reserve0: this.reserve0,
            reserve1: this.reserve1
        });

        if (!await this.confirmModalService.confirm('Modifier les réserves de cette paire ?')) {
            this.logger.debug('❌ [SET RESERVES] User cancelled');
            return;
        }

        this.executing = true;
        this.error = '';

        try {
            const pairAddress = this.selectedPair === 'custom' ? this.customPairAddress : this.selectedPair;
            if (!ethers.isAddress(pairAddress)) {
                this.logger.debug('❌ [SET RESERVES] Invalid pair address');
                throw new Error('Invalid pair address');
            }

            this.logger.debug('✅ [SET RESERVES] Address valid:', pairAddress);

            const dec0 = this.currentReserves?.decimals0 || 18;
            const dec1 = this.currentReserves?.decimals1 || 18;

            const reserve0WeiRaw = ethers.parseUnits(this.reserve0, dec0);
            const reserve1WeiRaw = ethers.parseUnits(this.reserve1, dec1);

            this.logger.debug('✅ [SET RESERVES] Wei amounts calculated:', {
                reserve0WeiRaw: reserve0WeiRaw.toString(),
                reserve1WeiRaw: reserve1WeiRaw.toString()
            });

            // Check if V3 or V2 based on name
            const isV3 = this.pairs.find(p => p.address === pairAddress)?.name.includes('V3') || false;
            this.logger.debug(`🔵 [SET RESERVES] Pair type: ${isV3 ? 'V3' : 'V2'}`);

            const pairAbi = isV3
                ? ['function setPriceForToken(address token, uint256 priceInOtherToken1e18) external']
                : ['function setReserves(uint112 reserve0, uint112 reserve1) external'];

            const locker = this.contractService.getLockerContract();
            const signer = locker.runner;
            const pair = new ethers.Contract(pairAddress, pairAbi, signer);

            if (isV3) {
                this.logger.debug('🔵 [SET RESERVES] V3 mode: getting token0...');
                // Pour Mock V3, on veut priceInOtherToken1e18 (prix de token0 en token1 en 1e18)
                // C'est human_price * 1e18
                // reserve1(human)/reserve0(human) = reserve1(wei 18) / reserve0(wei 18)
                const reserve0Wei18 = ethers.parseUnits(this.reserve0, 18);
                const reserve1Wei18 = ethers.parseUnits(this.reserve1, 18);
                
                const token0Abi = ['function token0() external view returns (address)'];
                const token0Contract = new ethers.Contract(pairAddress, token0Abi, signer);
                const token0 = await token0Contract['token0']();

                const price = (reserve1Wei18 * ethers.parseUnits('1', 18)) / reserve0Wei18;
                this.logger.debug('✅ [SET RESERVES] Price calculated:', price.toString());

                await this.contractService.executeTransaction(
                    'SET PRICE FOR TOKEN (V3)',
                    () => pair['setPriceForToken'](token0, price),
                    { token0, price: price.toString() }
                );
            } else {
                this.logger.debug('🔵 [SET RESERVES] V2 mode: setting reserves directly...');
                await this.contractService.executeTransaction(
                    'SET RESERVES (V2)',
                    () => pair['setReserves'](reserve0WeiRaw, reserve1WeiRaw),
                    { reserve0: reserve0WeiRaw.toString(), reserve1: reserve1WeiRaw.toString() }
                );
            }

            this.logger.debug('✅ [SET RESERVES] Success!');
            this.toastService.success('✅ Réserves modifiées avec succès !');
            this.loadPairInfo();
        } catch (e: any) {
            this.logger.error('❌ [SET RESERVES] Error:', e);
            this.error = e.message || 'Failed to set reserves';
            this.toastService.error('❌ Erreur: ' + this.error);
        } finally {
            this.logger.debug('🔵 [SET RESERVES] Process completed');
            this.executing = false;
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[TestUtilsComponent] destroyed');
    }
}
