import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ContractService } from '@services/contract.service';
import { BlockchainConfigService } from '@services/blockchain-config.service';
import { NetworkSelectorModalComponent } from '../network-selector-modal/network-selector-modal.component';
import { IconComponent } from '../../components/ui/icon/icon.component';
import { Subscription } from 'rxjs';
import { TranslateModule } from '@ngx-translate/core';

@Component({
    selector: 'app-unsupported-network-modal',
    standalone: true,
    imports: [CommonModule, IconComponent, NetworkSelectorModalComponent, TranslateModule],
    templateUrl: './unsupported-network-modal.component.html'
})
export class UnsupportedNetworkModalComponent implements OnInit, OnDestroy {
    isVisible = false;
    isNetworkSelectorOpen = false;
    private subscriptions = new Subscription();

    constructor(
        private contractService: ContractService,
        private blockchainConfigService: BlockchainConfigService
    ) { }

    async ngOnInit() {
        await this.blockchainConfigService.loadConfig();

        this.subscriptions.add(
            this.contractService.chainId$.subscribe(chainId => {
                if (chainId) {
                    const id = Number(chainId);
                    // Check if chain is deployed (i.e. if it has a lockerContract)
                    // The user requested to block if "contract registery" is not deployed.
                    // We interpret this as requiring a valid lockerContract address. 
                    this.isVisible = !this.blockchainConfigService.isChainDeployed(id);
                } else {
                    this.isVisible = false; // Not connected
                }
            })
        );
    }

    ngOnDestroy() {
        this.subscriptions.unsubscribe();
    }

    openNetworkSelector() {
        this.isNetworkSelectorOpen = true;
    }

    closeNetworkSelector() {
        this.isNetworkSelectorOpen = false;
    }
}
