import { TranslateModule } from '@ngx-translate/core';
import { Component, Input, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { QrCodeComponent } from '../qr-code/qr-code.component';
import { ToastService } from '@services/toast.service';
import { IconComponent } from '../icon/icon.component';
import { LoggerService } from "@services/logger.service";
import { ContactService } from '@services/contact.service';
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-address-qr-button',
    standalone: true,
    imports: [CommonModule, QrCodeComponent, IconComponent, TranslateModule],
    templateUrl: './address-qr-button.component.html',
    styleUrls: ['./address-qr-button.component.css']
})
export class AddressQrButtonComponent implements OnInit, OnDestroy {
    @Input() address = '';
    @Input() size: 'small' | 'medium' | 'large' = 'small';

    showQr = false;
    contactName = '';
    private contactsSub!: Subscription;

    constructor(
        private toastService: ToastService,
        private logger: LoggerService,
        private contactService: ContactService
    ) { }

    get addressJson(): string {
        return JSON.stringify({ address: this.address });
    }

    get buttonClass(): string {
        const base = 'qr-button';
        const sizes = {
            small: 'px-2 py-1 text-sm',
            medium: 'px-3 py-2 text-base',
            large: 'px-4 py-3 text-lg'
        };
        return `${base} ${sizes[this.size]}`;
    }

    openQr() {
        if (this.address) {
            this.showQr = true;
        }
    }

    closeQr() {
        this.showQr = false;
    }

    async copyJson() {
        try {
            await navigator.clipboard.writeText(this.addressJson);
            this.toastService.success('JSON copied to clipboard!');
        } catch (e) {
            this.logger.error('Failed to copy', e);
            this.toastService.error('Failed to copy JSON');
        }
    }

    async copyAddress() {
        try {
            await navigator.clipboard.writeText(this.address);
            this.toastService.success('Address copied!');
        } catch (e) {
            this.logger.error('Failed to copy', e);
            this.toastService.error('Failed to copy address');
        }
    }

    ngOnInit(): void {
        this.logger.debug('[AddressQrButtonComponent] initialized');
        this.contactsSub = this.contactService.contacts$.subscribe(contacts => {
            const found = contacts.find(c => c.address.toLowerCase() === this.address.toLowerCase());
            if (found && found.label) {
                this.contactName = found.label;
            } else {
                this.contactName = '';
            }
        });
    }

    ngOnDestroy(): void {
        this.logger.debug('[AddressQrButtonComponent] destroyed');
        if (this.contactsSub) {
            this.contactsSub.unsubscribe();
        }
    }
}
