import { TranslateModule, TranslateService } from '@ngx-translate/core';

import { Component, Input, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { formatPercent } from '@utils/formatters';
import { IconComponent } from '../icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-lock-card',
    standalone: true,
    imports: [CommonModule, RouterLink, IconComponent, TranslateModule],
    templateUrl: './lock-card.component.html'
})
export class LockCardComponent implements OnInit, OnDestroy {
    @Input() lock: any;

    constructor(private translate: TranslateService, private logger: LoggerService) { }

    // Expose Math for template
    Math = Math;
    formatPercent = formatPercent;

    formatTimeRemaining(unlockDate: Date): string {
        if (!unlockDate) {
            return this.translate.instant('UI_COMPONENTS.LOCK_CARD.NA');
        }
        const now = Date.now();
        const unlockTime = unlockDate.getTime();

        if (unlockTime <= now) {
            return this.translate.instant('UI_COMPONENTS.LOCK_CARD.UNLOCKED');
        }

        const diffMs = unlockTime - now;
        let remainingSeconds = Math.floor(diffMs / 1000);

        const years = Math.floor(remainingSeconds / (365 * 24 * 60 * 60));
        remainingSeconds -= years * 365 * 24 * 60 * 60;

        const months = Math.floor(remainingSeconds / (30 * 24 * 60 * 60));
        remainingSeconds -= months * 30 * 24 * 60 * 60;

        const days = Math.floor(remainingSeconds / (24 * 60 * 60));
        remainingSeconds -= days * 24 * 60 * 60;

        const hours = Math.floor(remainingSeconds / (60 * 60));
        remainingSeconds -= hours * 60 * 60;

        const minutes = Math.floor(remainingSeconds / 60);
        remainingSeconds -= minutes * 60;

        const parts: string[] = [];
        if (years > 0) parts.push(`${years}Y`);
        if (months > 0) parts.push(`${months}M`);
        if (days > 0) parts.push(`${days}D`);
        if (hours > 0) parts.push(`${hours}H`);
        if (minutes > 0) parts.push(`${minutes}m`);
        if (parts.length === 0 && remainingSeconds > 0) parts.push(`${remainingSeconds}s`);

        return parts.join(' ');
    }

    ngOnInit(): void {
        this.logger.debug('[LockCardComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[LockCardComponent] destroyed');
    }
}
