import { TranslateModule } from '@ngx-translate/core';

import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { ContractService } from '@services/contract.service';
import { ConfigService } from '@services/config.service';
import { BlockchainConfigService, ChainConfig } from '@services/blockchain-config.service';
import { IconComponent } from '../../ui/icon/icon.component';
import { LanguageSelectorComponent } from '../../ui/language-selector/language-selector.component';
import { NetworkSelectorModalComponent } from '../../../modals/network-selector-modal/network-selector-modal.component';
import { LoggerService } from "@services/logger.service";
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-header',
    standalone: true,
    imports: [CommonModule, RouterModule, IconComponent, TranslateModule, LanguageSelectorComponent, NetworkSelectorModalComponent],
    templateUrl: './header.component.html'
})
export class HeaderComponent implements OnInit, OnDestroy {
    account$ = this.contractService.account$;
    contractError$ = this.contractService.contractError$;
    title = 'Overview'; // This could be dynamic based on Route

    get currentMode() {
        return this.configService.mode;
    }

    get contractAddress() {
        const addr = this.configService.contracts.LockerContract;
        return addr ? `${addr.slice(0, 6)}...${addr.slice(-4)}` : '';
    }

    isNetworkModalOpen = false;
    currentChainConfig?: ChainConfig;
    currentChainId: number | null = null;
    private subscriptions = new Subscription();

    constructor(
        public contractService: ContractService,
        public configService: ConfigService,
        private blockchainConfigService: BlockchainConfigService,
        private logger: LoggerService
    ) { }

    async ngOnInit() {
        this.logger.debug('[HeaderComponent] initialized');
        await this.blockchainConfigService.loadConfig();

        this.subscriptions.add(
            this.contractService.chainId$.subscribe(chainId => {
                this.currentChainId = chainId ? Number(chainId) : null;
                if (this.currentChainId) {
                    this.currentChainConfig = this.blockchainConfigService.getChainConfig(this.currentChainId);
                }
            })
        );
    }

    ngOnDestroy(): void {
        this.logger.debug('[HeaderComponent] destroyed');
        this.subscriptions.unsubscribe();
    }

    getNetworkIconPath(chainId: number | null): string {
        if (!chainId) return 'assets/logo/eth.svg';
        const mapping: Record<number, string> = {
            1: 'eth.svg',
            56: 'bnb.svg',
            137: 'matic.svg',
            42161: 'arb.svg',
            10: 'op.svg',
            8453: 'base.svg',
            43114: 'avax.svg',
            59144: 'linea.svg',
            324: 'zksync.svg',
            31337: 'eth.svg',
            1337: 'eth.svg'
        };
        const fileName = mapping[chainId] || 'eth.svg';
        return `assets/logo/${fileName}`;
    }

    connect() {
        this.contractService.connectWallet();
    }

    disconnect() {
        this.contractService.disconnect();
    }

    openNetworkModal() {
        this.isNetworkModalOpen = true;
    }

    closeNetworkModal() {
        this.isNetworkModalOpen = false;
    }
}
