import { Component, EventEmitter, Input, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ContractService } from '@services/contract.service';
import { QrScannerComponent } from '@components/ui/qr-scanner/qr-scanner.component';
import { ethers } from 'ethers';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-sender-address-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, QrScannerComponent],
    templateUrl: './sender-address-modal.component.html',
    styleUrls: ['./sender-address-modal.component.scss']
})
export class SenderAddressModalComponent implements OnInit, OnDestroy {
    @Input() isOpen = false;
    @Input() suggestedAddress: string | null = null;
    @Output() confirmed = new EventEmitter<{ address: string; nonce: number }>();
    @Output() cancelled = new EventEmitter<void>();

    connectedAccount: string | null = null;
    selectedAddress: string = '';
    customAddress = '';
    nonce: number | null = null;
    isCustomValid = false;
    isValid = false;
    loading = false;
    showScanner = false;

    constructor(private contractService: ContractService, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[SenderAddressModalComponent] initialized');
        // Get connected account if available
        this.contractService.account$.subscribe((account: string | null) => {
            this.connectedAccount = account;
            this.initializeSelection();
        });
    }

    ngOnChanges() {
        if (this.isOpen) {
            this.initializeSelection();
        }
    }

    private initializeSelection() {
        if (!this.selectedAddress && this.isOpen) {
            if (this.suggestedAddress && (!this.connectedAccount || this.suggestedAddress.toLowerCase() !== this.connectedAccount.toLowerCase())) {
                // If a suggested address is provided and it's different from the connected wallet (or none connected), use it as custom
                this.selectedAddress = 'custom';
                this.customAddress = this.suggestedAddress;
                this.validateCustomAddress();
            } else if (this.connectedAccount) {
                // Otherwise default to connected account
                this.selectedAddress = this.connectedAccount;
                this.fetchNonce(this.connectedAccount);
            }
        }
    }

    onAddressChange() {
        if (this.selectedAddress === 'custom') {
            this.nonce = null;
            this.isValid = false;
        } else {
            this.fetchNonce(this.selectedAddress);
        }
    }

    validateCustomAddress() {
        this.isCustomValid = ethers.isAddress(this.customAddress);
        if (this.isCustomValid) {
            this.fetchNonce(this.customAddress);
        } else {
            this.nonce = null;
            this.isValid = false;
        }
    }

    async fetchNonce(address: string) {
        if (!ethers.isAddress(address)) {
            this.nonce = null;
            this.isValid = false;
            return;
        }

        this.loading = true;
        try {
            // Access provider directly from service (it's a public property)
            const provider = (this.contractService as any).provider;
            if (!provider) {
                throw new Error('Provider not available');
            }
            this.nonce = await provider.getTransactionCount(address);
            this.isValid = true;
        } catch (e) {
            this.logger.error('Failed to fetch nonce', e);
            this.nonce = null;
            this.isValid = false;
        } finally {
            this.loading = false;
        }
    }

    confirm() {
        if (!this.isValid || this.nonce === null) return;

        const finalAddress = this.selectedAddress === 'custom' ? this.customAddress : this.selectedAddress;
        this.confirmed.emit({ address: finalAddress, nonce: this.nonce });

        // Reset
        this.reset();
    }

    cancel() {
        this.cancelled.emit();
        this.reset();
    }

    private reset() {
        this.customAddress = '';
        this.nonce = null;
        this.isCustomValid = false;
        this.isValid = false;
        this.showScanner = false;
        this.selectedAddress = '';
        this.initializeSelection();
    }

    toggleScanner() {
        this.showScanner = !this.showScanner;
    }

    onQrScanned(data: string) {
        this.showScanner = false;

        try {
            // Try to parse as JSON first (wallet format: { "address": "0x..." })
            const parsed = JSON.parse(data);
            if (parsed.address && ethers.isAddress(parsed.address)) {
                this.customAddress = parsed.address;
                this.validateCustomAddress();
                return;
            }
        } catch (e) {
            // Not JSON, try as plain address
        }

        // Try as plain address
        if (ethers.isAddress(data)) {
            this.customAddress = data;
            this.validateCustomAddress();
        } else {
            this.logger.error('Invalid QR code data:', data);
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[SenderAddressModalComponent] destroyed');
    }
}
