import { Component, OnInit, OnDestroy } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { TransactionPreviewModalComponent } from '@modals/transaction-preview-modal/transaction-preview-modal.component';
import { ToastContainerComponent } from '@components/ui/toast-container/toast-container.component';
import { ConfirmModalComponent } from '@modals/confirm-modal/confirm-modal.component';
import { TxModeModalComponent } from '@modals/tx-mode-modal/tx-mode-modal.component';
import { TxSenderModalComponent } from '@modals/tx-sender-modal/tx-sender-modal.component';
import { UnsupportedNetworkModalComponent } from '@modals/unsupported-network-modal/unsupported-network-modal.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-root',
    standalone: true,
    imports: [RouterOutlet, TransactionPreviewModalComponent, ToastContainerComponent, ConfirmModalComponent, TxModeModalComponent, TxSenderModalComponent, UnsupportedNetworkModalComponent],
    templateUrl: './app.component.html',
    styleUrl: './app.component.css'
})
export class AppComponent implements OnInit, OnDestroy {
    title = 'locker-contrat';

    constructor(private translate: TranslateService, private logger: LoggerService) {
        this.translate.addLangs(['en', 'fr']);
        this.translate.setDefaultLang('en');

        // Check if there is a saved language in localStorage
        const savedLang = localStorage.getItem('language');
        if (savedLang) {
            this.translate.use(savedLang);
        } else {
            // Use browser language if available and supported
            const browserLang = this.translate.getBrowserLang();
            this.translate.use(browserLang && browserLang.match(/en|fr/) ? browserLang : 'en');
        }
    }

    ngOnInit(): void {
        this.logger.debug('[AppComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[AppComponent] destroyed');
    }
}
