    // ===== TABLET BATCH MODE METHODS =====

    async startTabletBatchUnlock() {
        if (!this.lock || !this.unlockAmount || !this.recipient) {
            this.toastService.warning('Please fill amount and recipient');
            return;
        }

        try {
            const locker = this.contractService.getLockerContract();
            const chainId = this.contractService.chainId$.value;
            if (!chainId) throw new Error('Chain ID not available');
            const lockerAddress = await locker.getAddress();

            // Get current unlock nonce from contract
            // 🆕 unlockNonce now indexed by lockId
            const unlockNonce = await locker['unlockNonce'](this.lockId);
            this.progressiveUnlockNonce = unlockNonce.toString();

            // Prepare payload
            const payload: ApproveUnlockPayload = {
                lockId: this.lockId.toString(),
                token: this.tokenAddress,
                recipient: this.recipient,
                amount: ethers.parseUnits(this.unlockAmount, Number(this.lock.tokenInfo.decimals)).toString(),
                unlockNonce: this.progressiveUnlockNonce
            };

            // Create REQUEST
            const request = this.opsService.createRequest(
                OfflineOpType.APPROVE_UNLOCK,
                Number(chainId),
                lockerAddress,
                payload
            );

            this.tabletBatchRequestQr = this.opsService.serializeRequest(request);
            this.showTabletBatchQr = true;

            // Get threshold
            try {
                this.progressiveThreshold = Number(await locker['approvalsThreshold']());
            } catch (thresholdError: any) {
                if (thresholdError.code === 'BAD_DATA') {
                    this.progressiveThreshold = 3; // Default when no signers exist
                } else {
                    throw thresholdError;
                }
            }

            this.logger.debug('Tablet batch unlock QR generated', {
                threshold: this.progressiveThreshold,
                collected: this.tabletBatchSignatures.length
            });
        } catch (e: any) {
            this.logger.error('Failed to start tablet batch unlock', e);
            this.toastService.error('Error: ' + e.message);
        }
    }

    async handleBatchSignatureScan(qrData: string) {
        try {
            let responses: OfflineResponse[] = [];
            try {
                const parsed = JSON.parse(qrData);
                if (parsed.type === 'BATCH_RESPONSE') {
                    responses = parsed.s.map((sigData: any) => ({
                        version: parsed.v || parsed.version || '2.0',
                        type: 'RESPONSE',
                        operation: parsed.op || parsed.operation,
                        signer: sigData[0],
                        signature: sigData[1],
                        timestamp: parsed.t || parsed.timestamp || Date.now()
                    }));
                } else if (Array.isArray(parsed)) {
                    responses = parsed;
                } else {
                    responses = [parsed];
                }
            } catch (e) {
                responses = [this.opsService.parseResponse(qrData)];
            }

            for (const response of responses) {
                if (!this.opsService.isValidResponse(response)) continue;
                if (response.operation !== OfflineOpType.APPROVE_UNLOCK) continue;

                const alreadyCollected = this.tabletBatchSignatures.some(
                    sig => sig.signer.toLowerCase() === response.signer.toLowerCase()
                );
                if (alreadyCollected) continue;

                const isValidSigner = await this.verifyOfflineSignature(response);
                if (!isValidSigner) continue;

                this.tabletBatchSignatures.push({
                    signer: response.signer,
                    signature: response.signature,
                    timestamp: new Date()
                });
            }

            this.toastService.success(`✅ ${responses.length} signature(s) traitée(s)! (${this.tabletBatchSignatures.length}/${this.progressiveThreshold})`);
            this.scanningBatchSignature = false;
        } catch (e: any) {
            this.logger.error('Failed to process batch signature', e);
            this.toastService.error('Error: ' + e.message);
            this.scanningBatchSignature = false;
        }
    }

    removeCollectedSignature(index: number) {
        if (index >= 0 && index < this.tabletBatchSignatures.length) {
            const removed = this.tabletBatchSignatures.splice(index, 1)[0];
            this.logger.debug('Removed signature:', removed.signer);
        }
    }

    async executeTabletBatchUnlock() {
        if (!this.lock || this.tabletBatchSignatures.length === 0) {
            this.toastService.warning('Aucune signature collectée');
            return;
        }

        if (this.tabletBatchSignatures.length < this.progressiveThreshold) {
            const confirm = await this.confirmModalService.confirm(
                `⚠️ Vous avez ${this.tabletBatchSignatures.length} signature(s) mais le threshold est ${this.progressiveThreshold}.\n\n` +
                'La transaction peut échouer. Continuer quand même?'
            );
            if (!confirm) return;
        }

        this.executing = true;
        try {
            const locker = this.contractService.getLockerContract();
            const amountWei = ethers.parseUnits(this.unlockAmount, Number(this.lock.tokenInfo.decimals));

            const signers = this.tabletBatchSignatures.map(s => s.signer);
            const signatures = this.tabletBatchSignatures.map(s => s.signature);


            this.logger.debug('Executing tablet batch unlock:', {
                signers,
                signatureCount: signatures.length,
                threshold: this.progressiveThreshold
            });

            const account = this.contractService.account$.value;

            // Track activity
            const txHash = await this.activityTracker.trackTransaction(
                'UNLOCK',
                account!,
                {
                    token: this.tokenAddress,
                    tokenSymbol: this.lock!.tokenInfo.symbol,
                    amount: this.unlockAmount,
                    recipient: this.recipient,
                    signers: signers
                },
                locker['executeUnlockWithSignatures'](
                    this.lockId,
                    this.recipient,
                    amountWei,
                    signers,
                    signatures
                ),
                locker
            );

            this.logger.debug('Tablet batch unlock transaction sent:', txHash);

            this.toastService.success('✅ Unlock batch exécuté avec succès !');
            await this.loadLock();

            // Reset fields
            this.resetUnlockFields();

            // Check if lock is completely empty and redirect to locks page
            if (this.lock && this.lock.lockData.basic?.availableAmount === 0n && this.lock.lockData.basic?.totalAmount === 0n) {
                this.router.navigate(['/locks']);
            }

        } catch (e: any) {
            this.logger.error('Failed to execute tablet batch unlock', e);
            this.toastService.error('Error: ' + e.message);
        } finally {
            this.executing = false;
        }
    }

    resetTabletBatchState() {
        this.tabletBatchSignatures = [];
        this.showTabletBatchQr = false;
        this.tabletBatchRequestQr = null;
        this.scanningBatchSignature = false;
        this.pastedSignatureJson = '';
    }

    async cancelTabletBatchUnlock() {
        if (this.tabletBatchSignatures.length > 0) {
            const confirmCancel = await this.confirmModalService.confirm(
                `⚠️ Vous avez ${this.tabletBatchSignatures.length} signature(s) collectée(s).\n\n` +
                'Voulez-vous vraiment annuler?'
            );
            if (!confirmCancel) return;
        }
        this.resetTabletBatchState();
    }

