import { TranslateModule } from '@ngx-translate/core';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { ConfigService } from '@services/config.service';
import { APP_MODES } from '@core/constants';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-config',
    standalone: true,
    imports: [CommonModule, FormsModule, RouterLink, TranslateModule],
    templateUrl: './config.component.html'
})
export class ConfigComponent implements OnInit, OnDestroy {
    rpcUrl = '';
    error = '';
    success = '';
    prodMode = APP_MODES.PROD;

    constructor(
        public configService: ConfigService,
        private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[ConfigComponent] initialized');
        this.rpcUrl = this.configService.rpcUrl;
    }

    saveRpcUrl() {
        this.error = '';
        this.success = '';

        try {
            this.configService.updateRpcUrl(this.rpcUrl);
            this.success = 'RPC URL sauvegardée avec succès';

            // Reload page to reinitialize provider with new RPC
            setTimeout(() => {
                window.location.reload();
            }, 1500);
        } catch (e: any) {
            this.error = e.message || 'URL invalide';
        }
    }

    resetRpcUrl() {
        this.configService.resetRpcUrl();
        this.rpcUrl = this.configService.rpcUrl;
        this.success = 'RPC URL réinitialisée';

        setTimeout(() => {
            window.location.reload();
        }, 1500);
    }

    ngOnDestroy(): void {
        this.logger.debug('[ConfigComponent] destroyed');
    }
}
