import { Component, ChangeDetectionStrategy, EventEmitter, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '@components/ui/icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-paste-signature-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent],
    templateUrl: './paste-signature-modal.component.html',
    styleUrls: ['./paste-signature-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class PasteSignatureModalComponent implements OnInit, OnDestroy {
    @Output() close = new EventEmitter<void>();
    @Output() loadSignature = new EventEmitter<string>();

    pasteBatchSignatureJson = '';

    onCancel() {
        this.pasteBatchSignatureJson = '';
        this.close.emit();
    }

    onLoad() {
        if (this.pasteBatchSignatureJson.trim()) {
            this.loadSignature.emit(this.pasteBatchSignatureJson.trim());
        }
    }

    constructor(private logger: LoggerService) {
    }

    ngOnInit(): void {
        this.logger.debug('[PasteSignatureModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[PasteSignatureModalComponent] destroyed');
    }
}
