import { Component, ChangeDetectionStrategy, EventEmitter, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '@components/ui/icon/icon.component';
import { QrScannerComponent } from '@components/ui/qr-scanner/qr-scanner.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-import-addresses-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, QrScannerComponent],
    templateUrl: './import-addresses-modal.component.html',
    styleUrls: ['./import-addresses-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class ImportAddressesModalComponent implements OnInit, OnDestroy {
    @Output() close = new EventEmitter<void>();
    @Output() importSuccess = new EventEmitter<string>();

    importAddressMode: 'SCAN' | 'PASTE' = 'SCAN';
    pastedAddressesJson = '';

    onScanSuccess(data: string) {
        this.importSuccess.emit(data);
    }

    onImport() {
        if (this.pastedAddressesJson.trim()) {
            this.importSuccess.emit(this.pastedAddressesJson.trim());
        }
    }

    onCancel() {
        this.pastedAddressesJson = '';
        this.close.emit();
    }

    constructor(private logger: LoggerService) {
    }

    ngOnInit(): void {
        this.logger.debug('[ImportAddressesModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[ImportAddressesModalComponent] destroyed');
    }
}
