import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ethers } from 'ethers';
import { ContractService } from '@services/contract.service';
import { ConfigService } from '@services/config.service';

import { LoggerService } from "@services/logger.service";

interface PairOption {
    label: string;
    pairAddress: string;
    tokenAddress: string;
    ethUsdPairAddress?: string;
    isEthPair: boolean;
    stablecoinPosition: number;
}

@Component({
    selector: 'app-price-checker',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule],
    templateUrl: './price-checker.component.html',
    styleUrls: ['./price-checker.component.css']
})
export class PriceCheckerComponent implements OnInit, OnDestroy {
    // Form inputs
    selectedPairKey = '';
    availablePairs: PairOption[] = [];

    // Custom pair inputs
    customTokenAddress = '';
    customPairAddress = '';
    customEthUsdPairAddress = '';
    customIsEthPair = false;
    customStablecoinPosition = 0;

    // State
    loading = false;
    result: any = null;
    error: string | null = null;

    constructor(
        private contractService: ContractService,
        public configService: ConfigService,
        private translate: TranslateService,
        private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[PriceCheckerComponent] initialized');
        this.loadAvailablePairs();
    }

    loadAvailablePairs() {
        this.availablePairs = [];

        // Import pair configs from token-config
        const { getPairs, getEthUsdPairs } = require('../../core/token-config');
        const pairConfigs = getPairs(this.configService.mode);
        const ethUsdPairs = getEthUsdPairs(this.configService.mode);

        // Get ETH/USD pair address
        const ethUsdPair = ethUsdPairs.length > 0 ? ethUsdPairs[0].address : null;

        // Convert PairConfig to PairOption format
        pairConfigs.forEach((pairConfig: any) => {
            const isEthPair = pairConfig.stablecoinPosition === 0;

            this.availablePairs.push({
                label: `${pairConfig.name} (${pairConfig.version})`,
                pairAddress: pairConfig.address,
                tokenAddress: pairConfig.tokenAddress,
                ethUsdPairAddress: isEthPair ? ethUsdPair : undefined,
                isEthPair: isEthPair,
                stablecoinPosition: pairConfig.stablecoinPosition
            });
        });
    }

    get selectedPair(): PairOption | undefined {
        return this.availablePairs.find((_, index) => index.toString() === this.selectedPairKey);
    }

    get isCustomMode(): boolean {
        return this.selectedPairKey === 'custom';
    }

    async getPrice() {
        this.loading = true;
        this.error = null;
        this.result = null;

        try {
            let tokenAddress: string;
            let pairAddress: string;
            let ethUsdPairAddress: string | null;
            let isEthPair: boolean;
            let stablecoinPosition: number;
            let pairLabel: string;

            if (this.isCustomMode) {
                // Validate custom inputs
                if (!this.customTokenAddress || !ethers.isAddress(this.customTokenAddress)) {
                    throw new Error(this.translate.instant('PRICE_CHECKER.ERRORS.INVALID_TOKEN'));
                }
                if (!this.customPairAddress || !ethers.isAddress(this.customPairAddress)) {
                    throw new Error(this.translate.instant('PRICE_CHECKER.ERRORS.INVALID_PAIR'));
                }
                if (this.customEthUsdPairAddress && !ethers.isAddress(this.customEthUsdPairAddress)) {
                    throw new Error(this.translate.instant('PRICE_CHECKER.ERRORS.INVALID_ETH_PAIR'));
                }

                tokenAddress = this.customTokenAddress;
                pairAddress = this.customPairAddress;
                ethUsdPairAddress = this.customEthUsdPairAddress || null;
                isEthPair = this.customIsEthPair;
                stablecoinPosition = this.customStablecoinPosition;
                pairLabel = 'Custom Pair';
            } else {
                const pair = this.selectedPair;
                if (!pair) {
                    throw new Error(this.translate.instant('PRICE_CHECKER.ERRORS.SELECT_PAIR'));
                }

                tokenAddress = pair.tokenAddress;
                pairAddress = pair.pairAddress;
                ethUsdPairAddress = pair.ethUsdPairAddress || null;
                isEthPair = pair.isEthPair;
                stablecoinPosition = pair.stablecoinPosition;
                pairLabel = pair.label;
            }

            // Fetch pair info
            const pairInfo = await this.contractService.getPairInfo(pairAddress);

            // Fetch price
            const priceUSD1e18 = await this.contractService.getTokenPriceUSD(
                tokenAddress,
                pairAddress,
                ethUsdPairAddress,
                isEthPair,
                stablecoinPosition
            );

            if (priceUSD1e18 === 0n) {
                throw new Error(this.translate.instant('PRICE_CHECKER.ERRORS.PRICE_ZERO'));
            }

            const priceUSD = Number(ethers.formatUnits(priceUSD1e18, 18));

            this.result = {
                priceUSD: priceUSD.toFixed(6),
                priceUSD1e18: priceUSD1e18.toString(),
                pairLabel,
                tokenAddress,
                pairAddress,
                ethUsdPairAddress: ethUsdPairAddress || 'N/A',
                isEthPair,
                stablecoinPosition,
                pairInfo
            };
        } catch (e: any) {
            this.error = e.message || this.translate.instant('PRICE_CHECKER.ERRORS.FETCH_FAILED');
            this.logger.error('Price fetch error:', e);
        } finally {
            this.loading = false;
        }
    }

    clearForm() {
        this.selectedPairKey = '';
        this.customTokenAddress = '';
        this.customPairAddress = '';
        this.customEthUsdPairAddress = '';
        this.customIsEthPair = false;
        this.customStablecoinPosition = 0;
        this.result = null;
        this.error = null;
    }

    onPairChange() {
        // Auto-fetch price when a pair is selected (but not Custom)
        if (this.selectedPairKey && this.selectedPairKey !== 'custom' && this.selectedPairKey !== '') {
            this.getPrice();
        }
    }

    formatReserve(reserve: any, decimals: number): string {
        if (!reserve) return '0';
        const formatted = ethers.formatUnits(reserve, decimals);
        const num = parseFloat(formatted);
        return num.toLocaleString(undefined, { maximumFractionDigits: 4 });
    }

    ngOnDestroy(): void {
        this.logger.debug('[PriceCheckerComponent] destroyed');
    }
}
