
import { Routes } from '@angular/router';
import { ShellComponent } from '@components/layout/shell/shell.component';
import { DashboardComponent } from '@pages/dashboard/dashboard.component';
import { LocksComponent } from '@pages/locks/locks.component';
import { CreateLockComponent } from '@pages/locks/create-lock/create-lock.component';
import { LockDetailComponent } from '@pages/locks/lock-detail/lock-detail.component';
import { SignersComponent } from '@pages/signers/signers.component';
import { ConfigComponent } from '@pages/config/config.component';
import { TestUtilsComponent } from '@pages/test-utils/test-utils.component';
import { PriceCheckerComponent } from '@pages/price-checker/price-checker.component';
import { TestModeGuard } from './guards/test-mode.guard';
import { adminGuard } from './guards/admin.guard';
import { ChangeOwnerComponent } from '@pages/change-owner/change-owner.component';
import { WelcomeComponent } from '@pages/welcome/welcome.component';

export const routes: Routes = [
    {
        path: '',
        component: ShellComponent,
        children: [
            { path: '', redirectTo: 'dashboard', pathMatch: 'full' },
            { path: 'dashboard', component: DashboardComponent, canActivate: [adminGuard] },
            { path: 'welcome', component: WelcomeComponent },
            { path: 'locks', component: LocksComponent, canActivate: [adminGuard] },
            { path: 'locks/create', component: CreateLockComponent, canActivate: [adminGuard] },
            { path: 'locks/:lockId', component: LockDetailComponent, canActivate: [adminGuard] }, // 🆕 Changed from :address
            { path: 'price-checker', component: PriceCheckerComponent, canActivate: [adminGuard] },
            { path: 'config', component: ConfigComponent, canActivate: [adminGuard] },
            { path: 'test-utils', component: TestUtilsComponent, canActivate: [TestModeGuard, adminGuard] },
            { path: 'signers', component: SignersComponent, canActivate: [adminGuard] },
            { path: 'activities', loadComponent: () => import('./pages/activities/activities.component').then(m => m.ActivitiesComponent), canActivate: [adminGuard] },
            { path: 'owner', component: ChangeOwnerComponent, canActivate: [adminGuard] },
            { path: 'change-owner', redirectTo: 'owner', pathMatch: 'full' },
            { path: 'locker-registry', loadComponent: () => import('./pages/locker-registry/locker-registry.component').then(m => m.LockerRegistryComponent) },
            { path: 'locker-manager', loadComponent: () => import('./pages/locker-manager/locker-manager.component').then(m => m.LockerManagerComponent), canActivate: [adminGuard] },
            { path: 'transfer', loadComponent: () => import('./pages/transfer/transfer.component').then(m => m.TransferComponent), canActivate: [adminGuard] },
            { path: 'tx-broadcast', loadComponent: () => import('./pages/tx-broadcast/tx-broadcast.component').then(m => m.TxBroadcastComponent), canActivate: [adminGuard] },
            { path: 'contacts', loadComponent: () => import('./pages/contacts/contacts.component').then(m => m.ContactsComponent), canActivate: [adminGuard] },
            { path: 'registry-admin', loadComponent: () => import('./pages/registry-admin/registry-admin.component').then(m => m.RegistryAdminComponent), canActivate: [adminGuard] }
        ]
    }
];
