import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { ethers } from 'ethers';
import { EncryptionService } from './encryption.service';

import { LoggerService } from "@services/logger.service";

export interface StoredWallet {
    address: string;
    name: string;
    type: 'mnemonic' | 'privateKey';
    // Encrypted secrets (always stored, never in clear)
    encryptedMnemonic?: string;
    encryptedPrivateKey?: string;
}

@Injectable({
    providedIn: 'root'
})
export class WalletManagerService {
    private walletsSubject = new BehaviorSubject<StoredWallet[]>([]);
    public wallets$ = this.walletsSubject.asObservable();

    needsMigration = false;

    constructor(
        private encryptionService: EncryptionService,
        private logger: LoggerService
    ) {
        this.loadWallets();
    }

    /**
     * Load wallets from localStorage
     */
    private loadWallets(): void {
        const stored = localStorage.getItem('stored_wallets');
        if (stored) {
            try {
                const wallets = JSON.parse(stored);

                // Check if migration is needed (old format has clear mnemonic/privateKey)
                if (wallets.length > 0) {
                    const firstWallet = wallets[0];
                    if (firstWallet.mnemonic || firstWallet.privateKey) {
                        this.needsMigration = true;
                        return;
                    }
                }

                this.walletsSubject.next(wallets);
            } catch (e) {
                this.logger.error('Error loading wallets:', e);
            }
        }
    }

    get wallets(): StoredWallet[] {
        return this.walletsSubject.value;
    }

    /**
     * Check if migration from unencrypted wallets is needed
     */
    requiresMigration(): boolean {
        return this.needsMigration;
    }

    /**
     * Migrate unencrypted wallets to encrypted format
     */
    async migrateWallets(password: string): Promise<void> {
        const stored = localStorage.getItem('stored_wallets');
        if (!stored) return;

        const oldWallets = JSON.parse(stored);
        const newWallets: StoredWallet[] = [];

        for (const wallet of oldWallets) {
            const newWallet: StoredWallet = {
                address: wallet.address,
                name: wallet.name,
                type: wallet.type
            };

            if (wallet.mnemonic) {
                newWallet.encryptedMnemonic = await this.encryptionService.encrypt(wallet.mnemonic, password);
            }

            if (wallet.privateKey) {
                newWallet.encryptedPrivateKey = await this.encryptionService.encrypt(wallet.privateKey, password);
            }

            newWallets.push(newWallet);
        }

        localStorage.setItem('stored_wallets', JSON.stringify(newWallets));
        this.walletsSubject.next(newWallets);
        this.needsMigration = false;
    }

    /**
     * Generate suffix from wallet address (first 4 + last 4 chars)
     */
    private generateSuffixFromAddress(address: string): string {
        // Remove 0x prefix if present
        const addr = address.startsWith('0x') ? address.slice(2) : address;
        // Take first 4 and last 4 characters
        const first4 = addr.slice(0, 4);
        const last4 = addr.slice(-4);
        return `${first4}...${last4}`;
    }

    /**
     * Add wallet from mnemonic phrase
     */
    async addWalletFromMnemonic(mnemonic: string, name: string, password: string): Promise<string> {
        // Validate mnemonic
        if (!this.isValidMnemonic(mnemonic)) {
            throw new Error('Invalid mnemonic phrase');
        }

        // Create HD wallet from mnemonic
        const hdNode = ethers.HDNodeWallet.fromPhrase(mnemonic);
        const address = hdNode.address;

        // Check if wallet already exists
        if (this.wallets.find(w => w.address.toLowerCase() === address.toLowerCase())) {
            throw new Error('Wallet already exists');
        }

        // Check for duplicate name
        if (this.wallets.find(w => w.name.toLowerCase() === name.toLowerCase())) {
            throw new Error(`A wallet with the name "${name}" already exists. Please choose a different name.`);
        }

        // Encrypt mnemonic
        const encryptedMnemonic = await this.encryptionService.encrypt(mnemonic, password);

        const wallet: StoredWallet = {
            address,
            name: name || `Wallet-${this.generateSuffixFromAddress(address)}`,
            type: 'mnemonic',
            encryptedMnemonic
        };

        const updatedWallets = [...this.wallets, wallet];
        this.walletsSubject.next(updatedWallets);
        this.saveWallets();

        return address;
    }

    /**
     * Add wallet from private key
     */
    async addWalletFromPrivateKey(privateKey: string, name: string, password: string): Promise<string> {
        // Validate private key
        if (!this.isValidPrivateKey(privateKey)) {
            throw new Error('Invalid private key');
        }

        // Normalize private key (add 0x if missing)
        const normalizedKey = privateKey.startsWith('0x') ? privateKey : `0x${privateKey}`;

        // Create wallet from private key
        const wallet = new ethers.Wallet(normalizedKey);
        const address = wallet.address;

        // Check if wallet already exists
        if (this.wallets.find(w => w.address.toLowerCase() === address.toLowerCase())) {
            throw new Error('Wallet already exists');
        }

        // Check for duplicate name
        if (this.wallets.find(w => w.name.toLowerCase() === name.toLowerCase())) {
            throw new Error(`A wallet with the name "${name}" already exists. Please choose a different name.`);
        }

        // Encrypt private key
        const encryptedPrivateKey = await this.encryptionService.encrypt(normalizedKey, password);

        const storedWallet: StoredWallet = {
            address,
            name: name || `Wallet-${this.generateSuffixFromAddress(address)}`,
            type: 'privateKey',
            encryptedPrivateKey
        };

        const updatedWallets = [...this.wallets, storedWallet];
        this.walletsSubject.next(updatedWallets);
        this.saveWallets();

        return address;
    }

    /**
     * Remove wallet by address
     */
    removeWallet(address: string): void {
        const updatedWallets = this.wallets.filter(w => w.address.toLowerCase() !== address.toLowerCase());
        this.walletsSubject.next(updatedWallets);
        this.saveWallets();
    }

    /**
     * Rename a wallet
     */
    renameWallet(address: string, newName: string): void {
        // Check for duplicate name
        const duplicateName = this.wallets.some(w =>
            w.address.toLowerCase() !== address.toLowerCase() && w.name.toLowerCase() === newName.toLowerCase()
        );
        if (duplicateName) {
            throw new Error(`A wallet with the name "${newName}" already exists. Please choose a different name.`);
        }

        const updatedWallets = this.wallets.map(w =>
            w.address.toLowerCase() === address.toLowerCase() ? { ...w, name: newName } : w
        );
        this.walletsSubject.next(updatedWallets);
        this.saveWallets();
    }

    /**
     * Get all wallets
     */
    getAllWallets(): StoredWallet[] {
        return [...this.wallets];
    }

    /**
     * Get wallet by address
     */
    getWallet(address: string): StoredWallet | null {
        return this.wallets.find(w => w.address.toLowerCase() === address.toLowerCase()) || null;
    }

    /**
     * Get decrypted mnemonic
     */
    async getDecryptedMnemonic(wallet: StoredWallet, password: string): Promise<string> {
        if (!wallet.encryptedMnemonic) {
            throw new Error('No mnemonic available for this wallet');
        }
        return await this.encryptionService.decrypt(wallet.encryptedMnemonic, password);
    }

    /**
     * Get decrypted private key
     */
    async getDecryptedPrivateKey(wallet: StoredWallet, password: string): Promise<string> {
        if (wallet.type === 'mnemonic' && wallet.encryptedMnemonic) {
            const mnemonic = await this.encryptionService.decrypt(wallet.encryptedMnemonic, password);
            const hdNode = ethers.HDNodeWallet.fromPhrase(mnemonic);
            return hdNode.privateKey;
        } else if (wallet.type === 'privateKey' && wallet.encryptedPrivateKey) {
            return await this.encryptionService.decrypt(wallet.encryptedPrivateKey, password);
        }
        throw new Error('No private key available for this wallet');
    }

    /**
     * Get wallet's signer for signing operations (requires password)
     */
    async getWalletSigner(address: string, password: string): Promise<ethers.Wallet | ethers.HDNodeWallet> {
        const wallet = this.getWallet(address);
        if (!wallet) {
            throw new Error('Wallet not found');
        }

        // Create signer from decrypted secrets
        if (wallet.type === 'mnemonic' && wallet.encryptedMnemonic) {
            const mnemonic = await this.encryptionService.decrypt(wallet.encryptedMnemonic, password);
            return ethers.HDNodeWallet.fromPhrase(mnemonic);
        } else if (wallet.type === 'privateKey' && wallet.encryptedPrivateKey) {
            const privateKey = await this.encryptionService.decrypt(wallet.encryptedPrivateKey, password);
            return new ethers.Wallet(privateKey);
        }

        throw new Error('Cannot create signer - encrypted data not available');
    }

    /**
     * Sign EIP-712 typed data with a wallet (requires password)
     */
    async signTypedData(address: string, password: string, domain: any, types: any, value: any): Promise<string> {
        const signer = await this.getWalletSigner(address, password);
        return await signer.signTypedData(domain, types, value);
    }

    /**
     * Update password - re-encrypt all wallets
     */
    async updatePassword(oldPassword: string, newPassword: string): Promise<void> {
        const reencryptedWallets: StoredWallet[] = [];

        for (const wallet of this.wallets) {
            const newWallet: StoredWallet = {
                address: wallet.address,
                name: wallet.name,
                type: wallet.type
            };

            if (wallet.encryptedMnemonic) {
                const mnemonic = await this.encryptionService.decrypt(wallet.encryptedMnemonic, oldPassword);
                newWallet.encryptedMnemonic = await this.encryptionService.encrypt(mnemonic, newPassword);
            }

            if (wallet.encryptedPrivateKey) {
                const privateKey = await this.encryptionService.decrypt(wallet.encryptedPrivateKey, oldPassword);
                newWallet.encryptedPrivateKey = await this.encryptionService.encrypt(privateKey, newPassword);
            }

            reencryptedWallets.push(newWallet);
        }

        this.walletsSubject.next(reencryptedWallets);
        this.saveWallets();
    }

    /**
     * Validate mnemonic phrase
     */
    private isValidMnemonic(mnemonic: string): boolean {
        try {
            ethers.Mnemonic.fromPhrase(mnemonic);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Validate private key
     */
    private isValidPrivateKey(privateKey: string): boolean {
        try {
            const normalized = privateKey.startsWith('0x') ? privateKey : `0x${privateKey}`;
            new ethers.Wallet(normalized);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Save wallets to localStorage
     */
    private saveWallets(): void {
        try {
            localStorage.setItem('stored_wallets', JSON.stringify(this.wallets));
        } catch (e) {
            this.logger.error('Failed to save wallets:', e);
        }
    }

    /**
     * Clear all wallets (useful for cleanup)
     */
    clearAll(): void {
        this.walletsSubject.next([]);
        localStorage.removeItem('stored_wallets');
    }
}
