import { Injectable } from '@angular/core';
import { Contract, ethers } from 'ethers';
import { ActivityService } from './activity.service';
import {
    ActivityType,
    ActivityDetails,
    ErrorInfo,
    ParsedEvent,
    generateActivityId
} from '../models/activity.model';
import { LoggerService } from "@services/logger.service";

/**
 * Helper service to track activities with complete transaction data
 */
@Injectable({
    providedIn: 'root'
})
export class ActivityTrackerService {

    // Map of custom error selectors to names
    private errorMap: Record<string, string> = {
        '0x30cd7471': 'NotOwner',
        '0x82b42900': 'NotSigner',
        '0x09bde339': 'Invalid',
        '0x8baa579f': 'TransferFailed',
    };

    constructor(private activityService: ActivityService, private logger: LoggerService) { }

    /**
     * Track a transaction with complete data capture
     */
    async trackTransaction(
        type: ActivityType,
        address: string,
        details: ActivityDetails,
        txPromise: Promise<any>,
        contract?: Contract
    ): Promise<string> {
        const activityId = generateActivityId();

        // Get chainId from transaction promise
        let chainId: number | undefined;
        let network: string | undefined;

        try {
            const tx = await txPromise;
            chainId = tx.chainId;
            // Map chainId to network name
            if (chainId !== undefined) {
                network = this.getNetworkName(chainId);
            }
        } catch (e) {
            // Will be caught and handled below
        }

        // Reset promise (we need to re-await it later)
        const txPromiseAgain = txPromise;

        // Create initial activity record
        await this.activityService.addActivity({
            id: activityId,
            timestamp: Date.now(),
            type,
            status: 'pending',
            address,
            details,
            chainId,
            network
        });

        this.logger.debug(`📝 Activity ${activityId} created (${type}) - status: pending - network: ${network}`);

        try {
            // Execute transaction
            const tx = await txPromiseAgain;

            // Capture transaction response (with null checks for optional fields)
            const txResponse = {
                hash: tx.hash,
                to: tx.to || undefined,
                from: tx.from,
                nonce: tx.nonce,
                gasLimit: tx.gasLimit?.toString() || '0',
                gasPrice: tx.gasPrice?.toString() || undefined,
                data: tx.data || '0x',
                value: tx.value?.toString() || '0',
                chainId: tx.chainId,
                type: tx.type || 0,
                maxFeePerGas: tx.maxFeePerGas?.toString() || undefined,
                maxPriorityFeePerGas: tx.maxPriorityFeePerGas?.toString() || undefined
            };

            // Wait for confirmation
            const receipt = await tx.wait();

            // Parse events from logs
            const parsedEvents = contract ? this.parseEvents(receipt.logs, contract) : [];

            // Calculate gas cost (with null checks)
            const gasUsed = receipt.gasUsed?.toString() || '0';
            const gasPrice = receipt.effectiveGasPrice?.toString() || receipt.gasPrice?.toString() || '0';
            const gasCost = ethers.formatEther(
                BigInt(gasUsed) * BigInt(gasPrice)
            );

            // Capture full receipt (with null checks)
            const txReceipt = {
                to: receipt.to || undefined,
                from: receipt.from,
                contractAddress: receipt.contractAddress || undefined,
                transactionIndex: receipt.index,
                gasUsed,
                logsBloom: receipt.logsBloom || '',
                blockHash: receipt.blockHash || '',
                transactionHash: receipt.hash,
                logs: receipt.logs || [],
                blockNumber: receipt.blockNumber,
                confirmations: receipt.confirmations,
                cumulativeGasUsed: receipt.cumulativeGasUsed?.toString() || '0',
                effectiveGasPrice: gasPrice,
                status: receipt.status,
                type: receipt.type
            };

            // Update with success + all data (serialize to remove functions/circular refs)
            await this.activityService.updateActivityStatus(
                activityId,
                'success',
                tx.hash,
                undefined,
                {
                    txResponse: JSON.parse(JSON.stringify(txResponse)),
                    txReceipt: JSON.parse(JSON.stringify(txReceipt)),
                    blockNumber: receipt.blockNumber,
                    gasUsed,
                    gasPrice,
                    gasCost,
                    events: JSON.parse(JSON.stringify(parsedEvents))
                }
            );

            this.logger.debug(`✅ Activity ${activityId} updated to SUCCESS:`, tx.hash);
            return tx.hash;

        } catch (e: any) {
            // Capture complete error information
            const errorInfo: ErrorInfo = {
                message: e.message || 'Unknown error',
                code: e.code,
                reason: e.reason,
                data: e.data,
                method: e.method,
                transaction: e.transaction,
                stack: e.stack,
                shortMessage: e.shortMessage,
                info: e.info
            };

            // Try to decode contract custom error
            if (e.data) {
                try {
                    const selector = e.data.slice(0, 10);
                    errorInfo.contractError = {
                        selector,
                        name: this.decodeErrorName(selector),
                        args: this.decodeErrorArgs()
                    };
                } catch (decodeError) {
                    this.logger.error('Failed to decode error:', decodeError);
                }
            }

            await this.activityService.updateActivityStatus(
                activityId,
                'failed',
                undefined,
                errorInfo
            );

            throw e; // Re-throw to let caller handle
        }
    }

    /**
     * Parse events from transaction logs
     */
    private parseEvents(logs: any[], contract: Contract): ParsedEvent[] {
        return logs
            .map(log => {
                try {
                    const parsed = contract.interface.parseLog(log);
                    if (parsed) {
                        // Extract arguments - ethers v6 provides both indexed and named access
                        const args: Record<string, any> = {};

                        // Try to get event fragment to know parameter names
                        const eventFragment = contract.interface.getEvent(parsed.name);

                        if (eventFragment) {
                            // Use parameter names from fragment
                            eventFragment.inputs.forEach((input, index) => {
                                const value = parsed.args[index];
                                // Convert BigInt to string, keep other types
                                args[input.name || `param${index}`] =
                                    typeof value === 'bigint' ? value.toString() : value;
                            });
                        } else {
                            // Fallback: extract all non-numeric keys
                            Object.entries(parsed.args)
                                .filter(([k]) => isNaN(Number(k)))
                                .forEach(([key, value]) => {
                                    args[key] = typeof value === 'bigint' ? value.toString() : value;
                                });
                        }

                        return {
                            name: parsed.name,
                            signature: parsed.signature,
                            args,
                            logIndex: log.index
                        };
                    }
                } catch (e) {
                    this.logger.warn('Failed to parse event log:', e);
                    return null;
                }
                return null;
            })
            .filter((e): e is ParsedEvent => e !== null);
    }

    /**
     * Decode error selector to name
     */
    private decodeErrorName(selector: string): string | undefined {
        return this.errorMap[selector];
    }

    /**
     * Decode error arguments (if error has parameters)
     * Simplified version - ethers v6 doesn't expose .errors easily
     */
    private decodeErrorArgs(): any[] | undefined {
        try {
            // In ethers v6, we can try to decode using known error fragments
            // For now, return undefined as we primarily rely on the error name
            return undefined;
        } catch (e) {
            return undefined;
        }
    }

    /**
     * Map chainId to network name
     */
    private getNetworkName(chainId: number): string {
        switch (chainId) {
            case 1:
                return 'Mainnet';
            case 11155111:
                return 'Sepolia';
            default:
                return `Chain ${chainId}`;
        }
    }
}
