import { Component, OnInit, OnDestroy, DestroyRef, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { filter } from 'rxjs/operators';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ContractService } from '@services/contract.service';
import { OpsService, OfflineOpType, OfflineResponse } from '@services/ops.service';
import { ToastService } from '@services/toast.service';
import { ConfirmModalService } from '@services/confirm-modal.service';

import { QrCodeComponent } from '@components/ui/qr-code/qr-code.component';
import { QrScannerComponent } from '@components/ui/qr-scanner/qr-scanner.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { PasswordModalComponent } from '@modals/password-modal/password-modal.component';
import { IconComponent } from '@components/ui/icon/icon.component';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ScanSignatureModalComponent } from '@modals/scan-signature-modal/scan-signature-modal.component';
import { ImportAddressesModalComponent } from '@modals/import-addresses-modal/import-addresses-modal.component';
import { PasteSignatureModalComponent } from '@modals/paste-signature-modal/paste-signature-modal.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-signers',
    standalone: true,
    imports: [
        CommonModule,
        RouterLink,
        FormsModule,
        QrCodeComponent,
        QrScannerComponent,
        ContactInputComponent,
        PasswordModalComponent,
        ScanSignatureModalComponent,
        ImportAddressesModalComponent,
        PasteSignatureModalComponent,
        IconComponent,
        TranslateModule
    ],
    templateUrl: './signers.component.html'
})
export class SignersComponent implements OnInit, OnDestroy {
    private destroyRef = inject(DestroyRef);

    // ─── Current state ────────────────────────────────────────────────────────
    signers: string[] = [];
    threshold = 0;
    loading = true;

    // ─── Batch update form ────────────────────────────────────────────────────
    showBatchUpdate = false;
    selectedToRemove: string[] = [];
    newSignersToAdd: string[] = [''];

    // ─── Offline QR flow ──────────────────────────────────────────────────────
    showBatchOfflineQr = false;
    batchOfflineRequestQr = '';
    batchOfflineCollectedSignatures: OfflineResponse[] = [];
    scanningBatchSignature = false;
    showPasteBatchSignatureModal = false;
    executing = false;
    /** Toggle between QR image and raw JSON views */
    qrViewMode: 'QR' | 'JSON' = 'QR';

    // ─── Password modal ───────────────────────────────────────────────────────
    showPasswordModal = false;
    passwordModalTitle = '';
    passwordModalSubtitle = '';
    pendingPasswordAction: ((password: string) => Promise<void>) | null = null;

    // ─── Import addresses modal ────────────────────────────────────────────────
    showImportAddressesModal = false;

    constructor(
        private contractService: ContractService,
        private opsService: OpsService,
        private toastService: ToastService,
        private confirmModalService: ConfirmModalService,
        private translate: TranslateService, private logger: LoggerService
    ) { }

    // ─── Lifecycle ────────────────────────────────────────────────────────────

    ngOnInit() {
        this.logger.debug('[SignersComponent] initialized');

        // Reload when the locker changes (fixes the bug where the default locker is loaded first)
        this.contractService.currentLocker$
            .pipe(
                filter(address => !!address),
                takeUntilDestroyed(this.destroyRef)
            )
            .subscribe((lockerAddress) => {
                this.logger.debug('[SignersComponent] locker changed to', lockerAddress);
                this.loadSigners();
            });

        // Reload signers when the connected account changes
        let previousAccount: string | null = null;
        this.contractService.account$
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe(address => {
                if (address) {
                    const normalised = address.toLowerCase();
                    if (previousAccount && previousAccount.toLowerCase() !== normalised) {
                        this.loadSigners();
                    }
                    previousAccount = address;
                }
            });
    }

    // ─── Data loading ─────────────────────────────────────────────────────────

    async loadSigners() {
        this.loading = true;
        try {
            this.signers = await this.contractService.getSigners();
            const locker = this.contractService.getLockerContract();
            try {
                this.threshold = Number(await locker['approvalsThreshold']());
            } catch (err: any) {
                // Contract may revert with BAD_DATA when no signers are present yet
                this.threshold = err.code === 'BAD_DATA' ? 0 : (() => { throw err; })();
            }
        } catch (e: any) {
            if (e.code !== 'BAD_DATA') {
                this.logger.error('Failed to load signers', e);
            }
        } finally {
            this.loading = false;
        }
    }

    // ─── Signature counters (used in template) ────────────────────────────────

    getValidSignaturesCount(): number {
        return this.batchOfflineCollectedSignatures.filter(s => s.isValid !== false).length;
    }

    getInvalidSignaturesCount(): number {
        return this.batchOfflineCollectedSignatures.filter(s => s.isValid === false).length;
    }

    // ─── Batch update: selection helpers ─────────────────────────────────────

    /** Toggle a signer in the removal list and reset the offline QR. */
    toggleRemoveSigner(signer: string) {
        const idx = this.selectedToRemove.indexOf(signer);
        if (idx > -1) {
            this.selectedToRemove.splice(idx, 1);
        } else {
            this.selectedToRemove.push(signer);
        }
        this.resetOfflineQr();
    }

    addNewSignerInput() {
        this.newSignersToAdd.push('');
        this.resetOfflineQr();
    }

    removeNewSignerInput(index: number) {
        if (this.newSignersToAdd.length > 1) {
            this.newSignersToAdd.splice(index, 1);
            this.resetOfflineQr();
        }
    }

    onNewSignerChange() {
        // Invalidate cached QR when any address field changes
        this.resetOfflineQr();
    }

    /** Clears any pending offline QR so a fresh one is generated next time. */
    private resetOfflineQr() {
        this.showBatchOfflineQr = false;
        this.batchOfflineCollectedSignatures = [];
    }

    // ─── Template getters ─────────────────────────────────────────────────────

    get validNewSignersCount(): number {
        return this.newSignersToAdd.filter(s => s.trim() !== '').length;
    }

    get finalSignersCount(): number {
        return this.signers.length - this.selectedToRemove.length + this.validNewSignersCount;
    }

    // ─── Offline QR generation ────────────────────────────────────────────────

    async generateBatchOfflineQr() {
        const signersToAdd = this.newSignersToAdd.filter(s => s.trim() !== '');

        if (this.selectedToRemove.length === 0 && signersToAdd.length === 0) {
            this.toastService.warning(this.translate.instant('SIGNERS.WARNINGS.SELECT_OR_ADD'));
            return;
        }

        if (this.finalSignersCount < 5) {
            this.toastService.warning(this.translate.instant('SIGNERS.WARNINGS.MUST_HAVE_FIVE'));
            return;
        }

        try {
            const locker = this.contractService.getLockerContract();
            const chainId = this.contractService.chainId$.value;
            if (!chainId) throw new Error('Chain ID not available');
            const lockerAddress = await locker.getAddress();
            const nonce = await locker['batchUpdateSignersNonce']();

            const payload = {
                signersToRemove: this.selectedToRemove,
                signersToAdd,
                nonce: nonce.toString()
            };

            const request = this.opsService.createRequest(
                'BATCH_UPDATE_SIGNERS' as OfflineOpType,
                Number(chainId),
                lockerAddress,
                payload
            );

            this.batchOfflineRequestQr = this.opsService.serializeRequest(request);
            this.showBatchOfflineQr = true;
            this.batchOfflineCollectedSignatures = [];

            this.toastService.info(this.translate.instant('SIGNERS.INFO.SCAN_QR', { threshold: this.threshold }));
        } catch (e: any) {
            this.logger.error('Failed to generate batch offline QR', e);
            this.toastService.error(this.translate.instant('SIGNERS.ERRORS.QR_FAILED') + e.message);
        }
    }

    // ─── Signature collection ─────────────────────────────────────────────────

    async handleScannedBatchSignature(qrData: string) {
        try {
            let responses: OfflineResponse[] = [];

            // Support multi-signature QR blobs (multiple JSON objects concatenated)
            const jsonBlocks = qrData.match(/\{.*?"version"\s*:\s*"2\.0".*?\}/gs) || [];
            if (jsonBlocks.length > 0) {
                for (const block of jsonBlocks) {
                    try { responses.push(JSON.parse(block)); } catch { /* skip malformed */ }
                }
            } else {
                const parsed = JSON.parse(qrData);
                responses = Array.isArray(parsed) ? parsed : [parsed];
            }

            if (responses.length === 0) {
                throw new Error(this.translate.instant('SIGNERS.ERRORS.NO_SIGS_PROVIDED'));
            }

            let validCount = 0;
            let invalidCount = 0;

            for (const response of responses) {
                try {
                    this.logger.debug('Validating response:', response);

                    if (!this.opsService.isValidResponse(response)) {
                        this.logger.debug('Response fails isValidResponse check:', response);
                        invalidCount++;
                        continue;
                    }

                    // Accept both operation type names for backward compatibility
                    const validOps = [
                        OfflineOpType.APPROVE_BATCH_UPDATE_SIGNERS,
                        'BATCH_UPDATE_SIGNERS' as OfflineOpType
                    ];
                    if (!validOps.includes(response.operation)) {
                        this.logger.debug(`Invalid operation type: ${response.operation}`);
                        invalidCount++;
                        continue;
                    }

                    const isValidSigner = await this.verifyOfflineSignature(response);

                    this.logger.debug(`Is valid signer: ${isValidSigner} for ${response.signer}`);

                    if (!isValidSigner) {
                        const proceed = await this.confirmModalService.confirm(
                            this.translate.instant('SIGNERS.WARNINGS.UNAUTHORIZED_SIGNER', { signer: response.signer })
                        );
                        if (!proceed) {
                            invalidCount++;
                            continue;
                        }
                    }

                    const alreadySigned = this.batchOfflineCollectedSignatures.some(
                        s => s.signer.toLowerCase() === response.signer.toLowerCase()
                    );
                    if (alreadySigned) {
                        this.logger.debug(`Already signed: ${response.signer}`);
                        invalidCount++;
                        continue;
                    }

                    this.batchOfflineCollectedSignatures.push({ ...response, isValid: isValidSigner });
                    validCount++;
                } catch (err: any) {
                    this.logger.error('Error during response validation loop:', err);
                    invalidCount++;
                }
            }

            if (validCount > 0) {
                this.toastService.success(
                    this.translate.instant('SIGNERS.SUCCESS.SIGS_LOADED', {
                        count: validCount,
                        current: this.batchOfflineCollectedSignatures.length,
                        total: this.threshold
                    })
                );
            }
            if (invalidCount > 0) {
                this.toastService.warning(this.translate.instant('SIGNERS.WARNINGS.INVALID_SIGS', { count: invalidCount }));
            }

            this.scanningBatchSignature = false;
        } catch (e: any) {
            this.logger.error('Failed to process signature', e);
            this.toastService.error(this.translate.instant('SIGNERS.ERRORS.PROCESS_SIG_FAILED') + e.message);
            this.scanningBatchSignature = false;
        }
    }

    async handlePastedBatchSignature(data: string) {
        try {
            await this.handleScannedBatchSignature(data);
            this.showPasteBatchSignatureModal = false;
        } catch (e: any) {
            this.toastService.error(this.translate.instant('SIGNERS.ERRORS.PROCESS_PASTED_FAILED') + e.message);
        }
    }

    // ─── Signature verification ───────────────────────────────────────────────

    private async verifyOfflineSignature(response: OfflineResponse): Promise<boolean> {
        try {
            if (!this.signers || this.signers.length === 0) {
                await this.loadSigners();
            }

            const signerLower = response.signer.toLowerCase();

            const isCurrentSigner = this.signers.some(s => s.toLowerCase() === signerLower);
            if (isCurrentSigner) return true;

            // Also accept signers being added in this batch
            const isNewSigner = this.newSignersToAdd.some(a => a.trim().toLowerCase() === signerLower);
            return isNewSigner;
        } catch (e: any) {
            this.logger.error('Error during signature verification:', e);
            return false;
        }
    }

    // ─── Transaction execution ────────────────────────────────────────────────

    async executeBatchWithCollectedSignatures() {
        const validSignatures = this.batchOfflineCollectedSignatures.filter(s => s.isValid !== false);

        if (validSignatures.length < this.threshold) {
            this.toastService.warning(
                this.translate.instant('SIGNERS.WARNINGS.NEED_MORE_VALID_SIGS', {
                    threshold: this.threshold,
                    valid: validSignatures.length,
                    invalid: this.batchOfflineCollectedSignatures.length - validSignatures.length
                })
            );
            return;
        }

        this.executing = true;
        try {
            const locker = this.contractService.getLockerContract();
            const signersToAdd = this.newSignersToAdd.filter(s => s.trim() !== '');

            const signers = validSignatures.map(s => s.signer);
            const signatures = validSignatures.map(s => s.signature);

            await this.contractService.executeTransaction(
                'BATCH UPDATE SIGNERS WITH SIGNATURES',
                () => locker['batchUpdateSignersWithSignatures'](
                    this.selectedToRemove,
                    signersToAdd,
                    signers,
                    signatures
                ),
                {
                    signersToRemove: this.selectedToRemove.length,
                    signersToAdd: signersToAdd.length,
                    signatureCount: signatures.length
                }
            );

            this.toastService.success(this.translate.instant('SIGNERS.SUCCESS.EXECUTE_BATCH'));
            this.resetBatchUpdateState();
            this.showBatchOfflineQr = false;
            this.batchOfflineRequestQr = '';
            this.batchOfflineCollectedSignatures = [];
            this.showBatchUpdate = false;
            await this.loadSigners();
        } catch (e: any) {
            this.logger.error('Failed to execute batch update with offline signatures', e);
            this.toastService.error(this.translate.instant('SIGNERS.ERRORS.EXECUTE_OFFLINE_FAILED') + e.message);
        } finally {
            this.executing = false;
        }
    }

    // ─── State reset ──────────────────────────────────────────────────────────

    resetBatchUpdateState() {
        this.selectedToRemove = [];
        this.newSignersToAdd = [''];
    }

    // ─── Password modal callbacks ─────────────────────────────────────────────

    onPasswordSubmit(password: string) {
        this.showPasswordModal = false;
        if (this.pendingPasswordAction) {
            this.pendingPasswordAction(password);
            this.pendingPasswordAction = null;
        }
    }

    onPasswordCancel() {
        this.showPasswordModal = false;
        this.pendingPasswordAction = null;
    }

    // ─── Import addresses from wallet-air-grapped QR ─────────────────────────────

    handleImportedAddresses(qrData: string) {
        try {
            const parsed = JSON.parse(qrData);

            if (!Array.isArray(parsed)) {
                this.toastService.error(this.translate.instant('SIGNERS.ERRORS.INVALID_FORMAT_EXPECT_ARRAY'));
                return;
            }
            if (parsed.length === 0) {
                this.toastService.warning(this.translate.instant('SIGNERS.WARNINGS.NO_ADDRESS_IN_QR'));
                return;
            }

            // Extract valid Ethereum addresses from various input shapes
            const addresses: string[] = [];
            for (const item of parsed) {
                if (typeof item === 'object' && item !== null && item['address']) {
                    const addr = (item['address'] as string).trim();
                    if (addr.startsWith('0x') && addr.length === 42) addresses.push(addr);
                } else if (typeof item === 'string' && item.startsWith('0x') && item.length === 42) {
                    addresses.push(item.trim());
                }
            }

            if (addresses.length === 0) {
                this.toastService.error(this.translate.instant('SIGNERS.ERRORS.NO_VALID_ADDRESS_IN_QR'));
                return;
            }

            // Filter duplicates against current signers (not scheduled for removal) and already-added inputs
            const currentLower = this.signers.map(s => s.toLowerCase());
            const removingLower = this.selectedToRemove.map(s => s.toLowerCase());
            const addedLower = this.newSignersToAdd.filter(s => s.trim() !== '').map(s => s.toLowerCase());

            const duplicates: string[] = [];
            const valid: string[] = [];

            for (const addr of addresses) {
                const low = addr.toLowerCase();
                if (currentLower.includes(low) && !removingLower.includes(low)) {
                    duplicates.push(addr);
                } else if (addedLower.includes(low)) {
                    duplicates.push(addr);
                } else {
                    valid.push(addr);
                    addedLower.push(low); // prevent intra-import duplicates
                }
            }

            // Replace trailing empty slot, append valid addresses, restore empty slot
            if (this.newSignersToAdd.at(-1) === '') this.newSignersToAdd.pop();
            this.newSignersToAdd.push(...valid, '');

            if (valid.length > 0) {
                this.resetOfflineQr();
            }

            // Build and show result message
            let msg = '';
            if (valid.length > 0) {
                msg = this.translate.instant('SIGNERS.SUCCESS.IMPORTED_ADDRESSES', { count: valid.length });
            }
            if (duplicates.length > 0) {
                if (msg) msg += '\n';
                msg += this.translate.instant('SIGNERS.WARNINGS.DUPLICATES_SKIPPED', { count: duplicates.length });
            }

            if (valid.length === 0 && duplicates.length > 0) {
                this.toastService.warning(msg);
            } else if (valid.length > 0) {
                this.toastService.success(msg);
            }

            this.showImportAddressesModal = false;
        } catch (e: any) {
            this.logger.error('Failed to parse addresses', e);
            this.toastService.error(this.translate.instant('SIGNERS.ERRORS.INVALID_JSON_FORMAT') + ' ' + e.message);
        }
    }

    // ─── Utilities ────────────────────────────────────────────────────────────

    async copyToClipboard(text: string) {
        try {
            await navigator.clipboard.writeText(text);
            this.toastService.success(this.translate.instant('SIGNERS.SUCCESS.COPY'));
        } catch (e) {
            this.logger.error('Failed to copy', e);
            this.toastService.error(this.translate.instant('SIGNERS.ERRORS.COPY_FAILED'));
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[SignersComponent] destroyed');
    }
}
