import { Injectable } from '@angular/core';
import { CanActivate, Router } from '@angular/router';
import { ConfigService } from '@services/config.service';
import { ToastService } from '@services/toast.service';
import { APP_MODES } from '@core/constants';


@Injectable({
    providedIn: 'root'
})
export class TestModeGuard implements CanActivate {
    constructor(
        private configService: ConfigService,
        private router: Router,
        private toastService: ToastService
    ) { }

    canActivate(): boolean {
        if (this.configService.mode === APP_MODES.TEST) {
            return true;
        }

        // Redirect to dashboard in production mode
        this.toastService.warning('⚠️ Cette fonctionnalité n\'est disponible qu\'en mode TEST');
        this.router.navigate(['/dashboard']);
        return false;
    }
}
