import { TranslateModule } from '@ngx-translate/core';

import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { ConfigService } from '@services/config.service';
import { APP_MODES } from '@core/constants';
import { IconComponent } from '../../ui/icon/icon.component';
import { ContractService } from '@services/contract.service';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-sidebar',
    standalone: true,
    imports: [CommonModule, RouterLink, RouterLinkActive, IconComponent, TranslateModule],
    templateUrl: './sidebar.component.html',
    styleUrl: './sidebar.component.css'
})
export class SidebarComponent implements OnInit, OnDestroy {
    testMode = APP_MODES.TEST;
    contractAddress$: Observable<string | null>;
    shortAddress$: Observable<string | null>;

    constructor(public configService: ConfigService, private contractService: ContractService, private logger: LoggerService) {
        this.contractAddress$ = this.contractService.currentLocker$;
        this.shortAddress$ = this.contractAddress$.pipe(
            map(addr => addr ? `${addr.slice(0, 10)}...${addr.slice(-8)}` : null)
        );
    }

    get currentMode() {
        return this.configService.mode;
    }

    ngOnInit(): void {
        this.logger.debug('[SidebarComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[SidebarComponent] destroyed');
    }
}
