import { Component, ChangeDetectionStrategy, EventEmitter, Input, Output, OnInit, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { LockDetails, ContractService } from '@services/contract.service';
import { ethers } from 'ethers';
import { Subscription } from 'rxjs';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-add-tokens-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, ContactInputComponent],
    templateUrl: './add-tokens-modal.component.html',
    styleUrls: ['./add-tokens-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class AddTokensModalComponent implements OnInit, OnDestroy {
    @Input() lock!: LockDetails;
    @Input() executing = false;

    @Output() close = new EventEmitter<void>();
    @Output() confirmAdd = new EventEmitter<{ amount: string, fromAddress: string }>();

    addAmount = '';
    addFromAddress = '';
    userBalance = 0n;
    userBalanceFormatted = '0';

    get hasZeroBalance(): boolean {
        return this.userBalance === 0n;
    }

    private sub?: Subscription;

    constructor(private contractService: ContractService, private cdr: ChangeDetectorRef, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[AddTokensModalComponent] initialized');
        this.sub = this.contractService.account$.subscribe(acc => {
            if (acc && !this.addFromAddress) {
                this.addFromAddress = acc;
                this.onAddFromAddressChange();
            }
        });

        if (!this.addFromAddress && this.contractService.account$.value) {
            this.addFromAddress = this.contractService.account$.value;
            this.onAddFromAddressChange();
        }
    }

    ngOnDestroy() {
        this.logger.debug('[AddTokensModalComponent] destroyed');
        this.sub?.unsubscribe();
    }

    async onAddFromAddressChange() {
        if (!this.lock) return;
        const addressToCheck = this.addFromAddress;
        if (addressToCheck && ethers.isAddress(addressToCheck)) {
            try {
                // Use tokenAddress from lock details or directly from lock object if available
                const tokenAddress = (this.lock as any).tokenAddress || this.lock.lockData?.pricing?.token;
                if (!tokenAddress) throw new Error("Token address not found");
                const token = this.contractService.getERC20Contract(tokenAddress);
                this.userBalance = await token['balanceOf'](addressToCheck);
                this.userBalanceFormatted = ethers.formatUnits(this.userBalance, Number(this.lock.tokenInfo.decimals));
                this.cdr.markForCheck();
            } catch (e) {
                this.logger.error('Failed to load balance for address:', e);
                this.userBalance = 0n;
                this.userBalanceFormatted = '0';
                this.cdr.markForCheck();
            }
        } else {
            this.userBalance = 0n;
            this.userBalanceFormatted = '0';
            this.cdr.markForCheck();
        }
    }

    setAddFromAddressToMe() {
        const account = this.contractService.account$.value;
        if (account) {
            this.addFromAddress = account;
            this.onAddFromAddressChange();
        }
    }

    setMaxAdd() {
        this.addAmount = this.userBalanceFormatted;
    }

    setAddAmountPercentage(percentage: number) {
        if (!this.lock || !this.userBalance || this.userBalance === 0n) return;
        if (percentage === 100) {
            this.setMaxAdd();
            return;
        }
        const amountWei = (this.userBalance * BigInt(percentage)) / 100n;
        this.addAmount = ethers.formatUnits(amountWei, Number(this.lock.tokenInfo.decimals));
    }

    onExecuteAdd() {
        if (this.addAmount && !this.executing) {
            this.confirmAdd.emit({ amount: this.addAmount, fromAddress: this.addFromAddress });
        }
    }
}
