import { TranslateModule } from '@ngx-translate/core';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { TransactionPreviewService, TransactionPreviewData } from '@services/transaction-preview.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-transaction-preview-modal',
    standalone: true,
    imports: [CommonModule, IconComponent, TranslateModule],
    templateUrl: './transaction-preview-modal.component.html',
    styleUrls: ['./transaction-preview-modal.component.scss']
})
export class TransactionPreviewModalComponent implements OnInit, OnDestroy {
    isOpen = false;
    jsonData = '';
    isConfirming = false;
    private currentData: TransactionPreviewData | null = null;
    private subscription?: Subscription;

    constructor(private previewService: TransactionPreviewService, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[TransactionPreviewModalComponent] initialized');
        this.subscription = this.previewService.preview$.subscribe((data: TransactionPreviewData | null) => {
            if (data) {
                this.currentData = data;
                this.jsonData = JSON.stringify(data.data, null, 2);
                this.isOpen = true;
                this.isConfirming = false;
            } else {
                this.isOpen = false;
                this.currentData = null;
                this.isConfirming = false;
            }
        });
    }

    ngOnDestroy() {
        this.logger.debug('[TransactionPreviewModalComponent] destroyed');
        this.subscription?.unsubscribe();
    }

    async confirm() {
        if (!this.currentData || this.isConfirming) return;

        this.isConfirming = true;
        try {
            const result = this.currentData.onConfirm();
            // Si c'est une Promise, on attend
            if (result instanceof Promise) {
                await result;
            }
            this.previewService.close();
        } catch (e) {
            this.logger.error('Error confirming transaction:', e);
            this.isConfirming = false;
            // Fermer la modale pour éviter d'être bloqué sur l'écran "Sending..."
            this.previewService.close();
        }
    }

    cancel() {
        if (this.isConfirming) return;

        if (this.currentData?.onCancel) {
            this.currentData.onCancel();
        }
        this.previewService.close();
    }

    onBackdropClick(event: Event) {
        // Fermer si on clique sur le backdrop (pas sur le contenu de la modal)
        if (event.target === event.currentTarget) {
            this.cancel();
        }
    }
}
