import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { WalletSignatureService, StoredWallet } from '@services/wallet-signature.service';
import { ToastService } from '@services/toast.service';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-wallet-selector',
    standalone: true,
    imports: [CommonModule],
    templateUrl: './wallet-selector.component.html',
    styleUrls: ['./wallet-selector.component.scss']
})
export class WalletSelectorComponent implements OnInit, OnChanges, OnDestroy {
    @Input() multiSelect = false;
    @Input() maxSelection?: number;
    @Input() validSigners: string[] = [];
    @Output() selectionChange = new EventEmitter<StoredWallet[]>();

    wallets: StoredWallet[] = [];
    selectedWallets: StoredWallet[] = [];

    constructor(
        private walletSigService: WalletSignatureService,
        private toastService: ToastService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[WalletSelectorComponent] initialized');
        this.loadWallets();
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes['validSigners']) {
            this.loadWallets();
        }
    }

    loadWallets() {
        const allWallets = this.walletSigService.getWallets();

        // Filter to show only valid signers if validSigners is provided
        if (this.validSigners && this.validSigners.length > 0) {
            this.wallets = allWallets.filter(w =>
                this.validSigners.some(s => s.toLowerCase() === w.address.toLowerCase())
            );
        } else {
            this.wallets = allWallets;
        }
    }

    isSelected(wallet: StoredWallet): boolean {
        return this.selectedWallets.some(w => w.address === wallet.address);
    }

    isDisabled(wallet: StoredWallet): boolean {
        if (!this.multiSelect) return false;
        if (!this.maxSelection) return false;
        return this.selectedWallets.length >= this.maxSelection && !this.isSelected(wallet);
    }

    isValidSigner(wallet: StoredWallet): boolean {
        if (this.validSigners.length === 0) return true;
        return this.validSigners.some(s => s.toLowerCase() === wallet.address.toLowerCase());
    }

    toggleSelection(wallet: StoredWallet) {
        if (this.isDisabled(wallet)) return;
        if (!this.isValidSigner(wallet)) {
            this.toastService.warning('Ce wallet n\'est pas un signer valide');
            return;
        }

        if (this.isSelected(wallet)) {
            this.selectedWallets = this.selectedWallets.filter(w => w.address !== wallet.address);
        } else {
            if (this.multiSelect) {
                this.selectedWallets.push(wallet);
            } else {
                this.selectedWallets = [wallet];
            }
        }

        this.selectionChange.emit(this.selectedWallets);
    }

    formatAddress(address: string): string {
        return this.walletSigService.formatAddress(address);
    }

    clearSelection() {
        this.selectedWallets = [];
        this.selectionChange.emit(this.selectedWallets);
    }

    ngOnDestroy(): void {
        this.logger.debug('[WalletSelectorComponent] destroyed');
    }
}
