import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { ContractService } from '@services/contract.service';
import { PriceService } from '@services/price.service';
import { ConfigService } from '@services/config.service';
import { OpsService, OfflineRequest, OfflineOpType, OfflineResponse } from '@services/ops.service';

import { ToastService } from '@services/toast.service';
import { ConfirmModalService } from '@services/confirm-modal.service';
import { TransactionInterceptorService } from '@services/transaction-interceptor.service';
import { ActivityTrackerService } from '@core/services/activity-tracker.service';
import { QrCodeComponent } from '@components/ui/qr-code/qr-code.component';
import { QrScannerComponent } from '@components/ui/qr-scanner/qr-scanner.component';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { getTokens, getPairs, getEthUsdPairs, TokenConfig, PairConfig } from '@core/token-config';
import { ethers } from 'ethers';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { LockService } from '@services/lock.service';
import { LoggerService } from "@services/logger.service";

@Component({
  selector: 'app-create-lock',
  standalone: true,
  imports: [CommonModule, FormsModule, QrCodeComponent, QrScannerComponent, IconComponent, ContactInputComponent, TranslateModule],
  templateUrl: './create-lock.component.html'
})
export class CreateLockComponent implements OnInit, OnDestroy {
  // Form Data
  fromAddress = ''; // Address to transfer tokens from (default: connected wallet)
  tokenAddress = '';
  amount = '';
  durationSeconds = 2592000; // 30 days default

  enablePriceTarget = false;
  pairAddress = '';
  ethUsdPair = ''; // 0x0...
  stablecoinPos = 0;
  isEthPair = true;
  targetPrice = '';
  priceDirection = 0; // 0 = UPSIDE (default), 1 = DOWNSIDE

  // Vesting configuration
  enableVesting = false;
  vestingUSDPerPeriod = '100';  // USD amount per period
  vestingPeriodSeconds = '604800';  // Period duration in seconds (default: 7 days)
  vestingIsStablecoin = false;  // Is token a stablecoin

  // Computed: Must use stablecoin if vesting without price lock
  get mustUseStablecoinForVesting(): boolean {
    return this.enableVesting && !this.enablePriceTarget;
  }

  // State
  tokenInfo: any = null;
  balance: bigint = 0n;
  formattedBalance = '0';
  loading = false;
  currentPriceFormatted = '-';
  currentPriceRaw: bigint = 0n;
  shouldApprove = false;
  errorMessage = '';
  warningMessage = '';

  // Dynamic configs based on mode
  availableTokens: TokenConfig[] = [];
  availablePairs: PairConfig[] = [];
  availableEthUsdPairs: PairConfig[] = [];

  // CREATE_LOCK_WITH_SIG workflow
  lockMode: 'REGULAR' | 'WITH_SIGNATURE' = 'REGULAR';
  selectedMode: 'DIRECT' | 'OFFLINE' | null = null;
  showSignatureQr = false;
  sigLockRequest: OfflineRequest | null = null; // Store original request parameters
  sigLockRequestQr: string | null = null;
  scanningLockSignature = false;
  scannedSignature: OfflineResponse | null = null;
  signatureInputMode: 'SCAN' | 'PASTE' = 'SCAN';
  pastedSignatureJson = '';
  executing = false;
  qrViewMode: 'QR' | 'JSON' = 'QR'; // Tab selector

  constructor(
    private contractService: ContractService,
    private priceService: PriceService,
    private configService: ConfigService,
    private router: Router,

    private opsService: OpsService,
    private toastService: ToastService,
    private confirmModalService: ConfirmModalService,
    private txInterceptor: TransactionInterceptorService,
    private activityTracker: ActivityTrackerService,
    private translate: TranslateService,
    private lockService: LockService, private logger: LoggerService
  ) { }

  ngOnInit() {
    this.logger.debug('[CreateLockComponent] initialized');
    // Set default from address to connected wallet
    this.contractService.account$.subscribe(account => {
      if (account && !this.fromAddress) {
        this.fromAddress = account;
      }
    });

    // Load tokens and pairs based on current mode
    this.loadConfigs();

    // Subscribe to mode changes
    this.configService.mode$.subscribe(() => {
      this.loadConfigs();
    });
  }

  loadConfigs() {
    const mode = this.configService.mode;
    this.availableTokens = getTokens(mode);
    this.availablePairs = getPairs(mode);
    this.availableEthUsdPairs = getEthUsdPairs(mode);
  }

  ngDoCheck() {
    // Auto-enforce stablecoin when vesting enabled without price lock
    if (this.mustUseStablecoinForVesting && !this.vestingIsStablecoin) {
      this.vestingIsStablecoin = true;
    }
  }

  async loadTokenInfo() {
    if (!this.tokenAddress || this.tokenAddress.length < 40) return;
    this.tokenInfo = await this.contractService.getTokenInfo(this.tokenAddress);

    // If the address is not a valid ERC20, getTokenInfo returns symbol '???' — skip balance fetch
    if (this.tokenInfo.symbol === '???') {
      this.balance = 0n;
      this.formattedBalance = '0';
      return;
    }

    // Load Balance from the specified 'from' address
    const contract = this.contractService.getERC20Contract(this.tokenAddress);
    const addressToCheck = this.fromAddress || this.contractService.account$.value;
    if (addressToCheck && ethers.isAddress(addressToCheck)) {
      try {
        this.balance = await contract['balanceOf'](addressToCheck);
        this.formattedBalance = ethers.formatUnits(this.balance, this.tokenInfo.decimals);
      } catch (e) {
        this.logger.warn('Could not fetch balance for token', this.tokenAddress, e);
        this.balance = 0n;
        this.formattedBalance = '0';
      }
    }
  }

  /**
   * Handle from address change - reload token info to update balance
   */
  onFromAddressChange() {
    if (this.tokenInfo) {
      this.loadTokenInfo();
    }
  }

  /**
   * Set from address to currently connected wallet
   */
  setFromAddressToMe() {
    const account = this.contractService.account$.value;
    if (account) {
      this.fromAddress = account;
      if (this.tokenInfo) {
        this.loadTokenInfo();
      }
    }
  }

  selectToken(e: any) {
    this.tokenAddress = e.target.value;
    this.loadTokenInfo();
  }

  useMaxBalance() {
    // Remove trailing zeros and decimal point if not needed
    this.amount = parseFloat(this.formattedBalance).toString();
  }

  /**
   * Set amount to a percentage of balance
   */
  setAmountPercentage(percentage: number) {
    if (!this.balance || !this.tokenInfo) return;

    const percentageAmount = (this.balance * BigInt(percentage)) / 100n;
    const formatted = ethers.formatUnits(percentageAmount, this.tokenInfo.decimals);
    // Remove trailing zeros
    this.amount = parseFloat(formatted).toString();
  }

  setDuration(days: number) {
    this.durationSeconds = days * 86400;  // Convert days to seconds
  }

  /**
   * Quick set vesting period in seconds
   */
  setVestingPeriod(seconds: number) {
    this.vestingPeriodSeconds = seconds.toString();
  }

  /**
   * Get Etherscan link for token contract
   */
  getEtherscanLink(address: string): string {
    const isMainnet = this.configService.chainId === 1;
    const baseUrl = isMainnet ? 'https://etherscan.io' : 'https://sepolia.etherscan.io';
    return `${baseUrl}/token/${address}`;
  }

  getUnlockDate() {
    return new Date(Date.now() + this.durationSeconds * 1000);
  }

  async updatePrice() {
    if (!this.enablePriceTarget || !this.pairAddress || !this.tokenAddress) return;

    try {
      const data = await this.priceService.getTokenPrice(
        this.tokenAddress,
        this.pairAddress,
        this.ethUsdPair || null,
        this.stablecoinPos
      );

      this.currentPriceRaw = data.priceInUSD;
      this.currentPriceFormatted = "$" + data.formattedUSD;
    } catch (e) {
      this.logger.error(e);
      this.currentPriceFormatted = "Error";
    }
  }

  selectPair(e: any) {
    const address = e.target.value;
    if (!address) return;

    this.pairAddress = address;

    // Auto-fill token and stablecoin position from config
    const pair = this.availablePairs.find(p => p.address === address);
    if (pair) {
      if (!this.tokenAddress) {
        this.tokenAddress = pair.tokenAddress;
        this.loadTokenInfo();
      }
      this.stablecoinPos = pair.stablecoinPosition;
      this.isEthPair = pair.stablecoinPosition === 0;

      // Auto-select first ETH/USD pair if it's an ETH pair and none is selected
      if (this.isEthPair && !this.ethUsdPair && this.availableEthUsdPairs.length > 0) {
        this.ethUsdPair = this.availableEthUsdPairs[0].address;
      } else if (!this.isEthPair) {
        this.ethUsdPair = ''; // Clear it if not an ETH pair
      }

      this.updatePrice();
    }
  }

  selectEthUsdPair(e: any) {
    const address = e.target.value;
    if (!address) {
      this.ethUsdPair = '';
      return;
    }

    this.ethUsdPair = address;
    this.updatePrice();
  }

  setTargetPercent(percent: number) {
    if (!this.currentPriceRaw) return;
    const target = this.currentPriceRaw * BigInt(100 + percent) / 100n;
    this.targetPrice = ethers.formatUnits(target, 18);
  }

  async createLock() {
    // Clear previous messages
    this.errorMessage = '';
    this.warningMessage = '';

    if (!this.tokenAddress || !this.amount) {
      this.errorMessage = `<strong>Error:</strong> ${this.translate.instant('CREATE_LOCK.ERRORS.TOKEN_AMOUNT')}`;
      return;
    }

    // VALIDATION: Durée ne peut pas être 0
    if (!this.durationSeconds || this.durationSeconds <= 0) {
      this.errorMessage = this.translate.instant('CREATE_LOCK.ERRORS.DURATION_ZERO');
      return;
    }

    // VALIDATION: Si mode prix activé, prix cible ne peut pas être 0
    if (this.enablePriceTarget) {
      const targetPriceVal = parseFloat(this.targetPrice || '0');

      if (!targetPriceVal || targetPriceVal === 0 || isNaN(targetPriceVal)) {
        this.errorMessage = this.translate.instant('CREATE_LOCK.ERRORS.TARGET_PRICE_REQ');
        return;
      }

      // Warning si le prix cible est inférieur au prix actuel
      if (this.currentPriceRaw > 0n) {
        const targetPriceWei = ethers.parseUnits(this.targetPrice, 18);
        if (targetPriceWei < this.currentPriceRaw) {
          this.warningMessage = this.translate.instant('CREATE_LOCK.WARNINGS.TARGET_PRICE_LOWER', {
            current: this.currentPriceFormatted,
            target: this.targetPrice
          });
          return;
        }
      }
    }

    this.loading = true;

    // BEFORE doing anything, ask the user if they want to do this via Direct or Offline Wallet
    // Wait, let's ask for the mode upfront so we can batch an approval if requested!
    const mode = await this.txInterceptor.askUserForMode({
      txRequest: { to: '', metadata: { operation: 'Create Lock (Batched if Offline)' } }
    });

    if (!mode) {
      this.loading = false;
      return; // User cancelled
    }

    if (this.lockMode === 'WITH_SIGNATURE') {
      this.loading = false;
      this.startSignatureLockWorkflow(mode);
      return;
    }



    this.logger.debug('🔵 [CREATE LOCK] Starting lock creation process...');

    try {
      const params = {
        tokenAddress: this.tokenAddress,
        tokenSymbol: this.tokenInfo.symbol,
        tokenDecimals: Number(this.tokenInfo.decimals),
        amount: this.amount,
        durationSeconds: this.durationSeconds,
        enablePriceTarget: this.enablePriceTarget,
        pairAddr: this.pairAddress || ethers.ZeroAddress,
        ethPairAddr: this.ethUsdPair || ethers.ZeroAddress,
        targetPriceWei: this.targetPrice ? ethers.parseUnits(this.targetPrice, 18).toString() : '0',
        targetPriceFormatted: this.targetPrice,
        isEthPair: this.isEthPair,
        stablecoinPos: this.stablecoinPos,
        priceDirection: this.priceDirection,
        enableVesting: this.enableVesting,
        vestingUSDPerPeriod: this.vestingUSDPerPeriod,
        vestingPeriodSeconds: this.vestingPeriodSeconds,
        vestingIsStablecoin: this.vestingIsStablecoin,
        mustUseStablecoinForVesting: this.mustUseStablecoinForVesting,
        currentPriceFormatted: this.currentPriceFormatted,
        fromAddress: this.fromAddress
      };

      await this.lockService.createLock(
        params,
        () => {
          this.shouldApprove = true;
          this.logger.debug('⚠️ [APPROVAL] Need to approve tokens first');
        },
        () => {
          this.shouldApprove = false;
        },
        mode
      );
    } catch (e: any) {
      this.logger.error('❌ [CREATE LOCK] Error in lock creation process:', e);
      if (e.message !== 'Offline signing required' && e.message !== 'User cancelled transaction' && e.message !== 'User cancelled approval') {
        // e.message could be an object if 'could not coalesce error' has nested payload. We should handle it safely.
        let msg = e.shortMessage || e.message;
        
        let finalMsg = typeof msg === 'string' ? msg : JSON.stringify(msg);
        if (finalMsg.includes('-32002') || (e.error && e.error.code === -32002)) {
             finalMsg = "RPC Rate Limit Exceeded: The network is busy. Please try again in 30 seconds or switch your network RPC endpoint.";
        }

        this.toastService.error("Error: " + finalMsg);
      }
      // Do not re-throw, as this method is bound directly to a button click
    } finally {
      this.logger.debug('🔵 [CREATE LOCK] Process completed, setting loading to false');
      this.loading = false;
    }
  }

  // CREATE_LOCK_WITH_SIG workflow methods
  async startSignatureLockWorkflow(mode: 'DIRECT' | 'OFFLINE' | null = null) {
    try {
      this.selectedMode = mode;
      
      if (!this.tokenAddress || !ethers.isAddress(this.tokenAddress)) {
        this.toastService.warning('Please enter a valid token address');
        return;
      }
      if (!this.amount || parseFloat(this.amount) <= 0) {
        this.toastService.warning('Please enter a valid amount');
        return;
      }

      const chainId = this.contractService.chainId$.value;
      if (!chainId) throw new Error('Chain ID not available');

      const lockerAddress = this.configService.contracts.LockerContract;

      const locker = this.contractService.getLockerContract();
      const currentNonce = await locker['createLockNonce']();

      const amountWei = ethers.parseUnits(this.amount, this.tokenInfo.decimals);

      const createLockRequest: OfflineRequest = {
        version: "2.0",
        type: 'REQUEST',
        operation: OfflineOpType.CREATE_LOCK_WITH_SIG,
        chainId: Number(chainId),  // Use the actual network chainId
        contractAddress: lockerAddress,
        data: {
          token: this.tokenAddress,
          amount: amountWei.toString(),
          lockDuration: this.durationSeconds,
          pair: this.enablePriceTarget ? (this.pairAddress || ethers.ZeroAddress) : ethers.ZeroAddress,
          ethUsdPair: this.enablePriceTarget ? (this.ethUsdPair || ethers.ZeroAddress) : ethers.ZeroAddress,
          targetPriceUSD1e18: this.enablePriceTarget && this.targetPrice ? ethers.parseUnits(this.targetPrice, 18).toString() : '0',
          isEthPair: this.enablePriceTarget ? this.isEthPair : false,  // Only send true if Price Target is enabled
          stablecoinPosition: this.enablePriceTarget ? this.stablecoinPos : 0,  // Only send stablecoin position if Price Target is enabled
          priceDirection: this.enablePriceTarget ? this.priceDirection : 0,  // priceDirection (UPSIDE=0, DOWNSIDE=1)
          vestingUSDPerPeriod: this.enableVesting ? ethers.parseEther(this.vestingUSDPerPeriod).toString() : '0',
          vestingPeriodSeconds: this.enableVesting ? parseInt(this.vestingPeriodSeconds) : 0,
          vestingIsStablecoin: this.enableVesting ? (this.mustUseStablecoinForVesting || this.vestingIsStablecoin) : false,
          nonce: currentNonce.toString()
        },
        timestamp: Date.now()
      };

      // Store the ORIGINAL createLockRequest to use for transaction submission
      this.sigLockRequest = createLockRequest;
      // The QR code contains the single create lock request
      this.sigLockRequestQr = this.opsService.serializeRequest(createLockRequest);
      this.showSignatureQr = true;
      // IMPORTANT: Reset scanned signature when generating new QR
      // to prevent using old signature with new parameters
      this.scannedSignature = null;

      this.logger.debug('✅ QR generated with params:', {
        chainId: createLockRequest.chainId,
        contractAddress: lockerAddress,
        token: createLockRequest.data.token,
        amount: createLockRequest.data.amount,
        isEthPair: createLockRequest.data.isEthPair,
        lockDuration: createLockRequest.data.lockDuration
      });
    } catch (e: any) {
      this.logger.error('Failed to generate signature request', e);
      this.toastService.error('Error: ' + e.message);
    }
  }

  scanLockSignature() {
    this.scanningLockSignature = true;
  }

  async handleScannedLockSignature(qrData: string) {
    try {
      // Use the flexible parser to handle both single response and batch array formats
      const response = this.opsService.parseResponseFlexible(qrData);

      if (!this.opsService.isValidResponse(response)) {
        throw new Error('Invalid response format');
      }

      if (response.operation === OfflineOpType.BATCHED_REQUESTS) {
        throw new Error('Batched offline approvals are no longer supported. Please regenerate the QR code.');
      }

      if (response.operation !== OfflineOpType.CREATE_LOCK_WITH_SIG) {
        throw new Error(`Unexpected operation type: ${response.operation}`);
      }

      // Verify signature and check if signer is authorized
      const isValidSigner = await this.verifyOfflineSignature(response);

      if (!isValidSigner) {
        const confirmProceed = await this.confirmModalService.confirm(
          '⚠️ WARNING: The wallet that signed is not part of the authorized signers!\n\n' +
          `Signer: ${response.signer}\n\n` +
          'The transaction may fail. Do you still want to use this signature?'
        );

        if (!confirmProceed) {
          this.scanningLockSignature = false;
          return;
        }

        this.logger.warn('⚠️ User chose to proceed with unauthorized signer:', response.signer);
      } else {
        this.logger.debug('✅ Signature verification passed - signer is authorized:', response.signer);
        // Show success alert
        this.toastService.success(`✅ Signature successfully validated!\n\nAuthorized signer: ${response.signer.substring(0, 10)}...\n\nReady to create lock.`);
      }

      this.scannedSignature = response;
      this.scanningLockSignature = false;
    } catch (e: any) {
      this.logger.error('Failed to scan signature', e);
      this.toastService.error('Error: ' + e.message);
      this.scanningLockSignature = false;
    }
  }

  private async verifyOfflineSignature(response: OfflineResponse): Promise<boolean> {
    try {
      this.logger.debug('🔍 Verifying offline signature...', {
        signer: response.signer,
        signature: response.signature.substring(0, 20) + '...'
      });

      // Get current signers and threshold from the contract
      const locker = this.contractService.getLockerContract();
      const [signersList, threshold] = await Promise.all([
        locker['getSigners'](),
        this.contractService.getThreshold()
      ]);

      this.logger.debug('📊 Contract Status:', {
        threshold: Number(threshold),
        signersCount: signersList.length,
        authorizedSigners: signersList
      });

      const signerLowerCase = response.signer.toLowerCase();
      const isAuthorized = signersList.some(
        (signer: string) => signer.toLowerCase() === signerLowerCase
      );

      if (!isAuthorized) {
        this.logger.error('❌ Signer not in authorized list:', {
          signer: response.signer
        });
        return false;
      }

      if (Number(threshold) > 1) {
        this.warningMessage = `<strong>⚠️ Threshold Warning</strong><br><br>` +
          `The contract requires <strong>${threshold}</strong> signatures to be valid.<br>` +
          `The current <code>createLockWithSignatures</code> function only accepts one signature per transaction.<br><br>` +
          `You must first send this signature via <code>approveOperation</code> or reduce the threshold to 1.`;
        this.logger.warn('⚠️ Threshold > 1 detected for createLockWithSignatures');
      }

      this.logger.debug('✅ Signer is authorized');
      return true;
    } catch (e: any) {
      this.logger.error('❌ Error during signature verification:', e);
      return false;
    }
  }

  async submitCreateLockWithSignature() {
    if (!this.scannedSignature) {
      this.toastService.warning('No signature available');
      return;
    }

    if (!this.sigLockRequest) {
      this.toastService.warning('Original request not found. Please regenerate the QR code.');
      return;
    }

    // Store in local variable to avoid TypeScript null check issues
    const signature = this.scannedSignature;
    const requestData = this.sigLockRequest.data;

    this.logger.debug('🔵 [CREATE LOCK WITH SIG] Starting lock creation with signature...');
    this.executing = true;
    try {
      const locker = this.contractService.getLockerContract();
      // Use amount from the original request, not from form
      const amountWei = BigInt(requestData.amount);

      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Parameters:', {
        tokenAddress: requestData.token,
        amountWei: amountWei.toString(),
        durationSeconds: requestData.lockDuration,
        signer: signature.signer,
      });

      // Prepare params with detailed logging
      const lockerAddress = await locker.getAddress();

      // Use the nonce that was actually signed in the offline payload!
      // Fetching the current nonce from chain can cause mismatches if other locks were created.
      const signedNonce = BigInt(requestData.nonce);
      this.logger.debug('🔒 [CREATE LOCK WITH SIG] Nonce used in signature:', signedNonce.toString());

      const lockParamsArray = [
        requestData.token,
        amountWei,
        requestData.lockDuration,
        requestData.pair || ethers.ZeroAddress,
        requestData.ethUsdPair || ethers.ZeroAddress,
        BigInt(requestData.targetPriceUSD1e18 || '0'),
        requestData.isEthPair || false,
        requestData.stablecoinPosition || 0,
        requestData.priceDirection || 0,  // priceDirection (UPSIDE=0, DOWNSIDE=1)
        BigInt(requestData.vestingUSDPerPeriod || '0'),  // vestingUSDPerPeriod
        requestData.vestingPeriodSeconds || 0,  // vestingPeriodSeconds
        requestData.vestingIsStablecoin || false  // vestingIsStablecoin
      ];

      const sigParamsArray = [
        signature.signer,
        signature.signature
      ];

      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Lock params:', lockParamsArray);
      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Sig params:', sigParamsArray);
      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Signer address type:', typeof signature.signer, signature.signer);
      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Signature type:', typeof signature.signature, signature.signature);

      // Calculate opKey with NONCE (must match smart contract exactly)
      const opKeyForDebug = ethers.solidityPackedKeccak256(
        [
          'string', 'address', 'uint256', 'uint256', 'address', 'address', 'uint256', 'bool', 'uint8', 'uint8',
          'uint256', 'uint256', 'bool', 'uint256', 'address'
        ],
        [
          'CREATE_LOCK',
          requestData.token,
          amountWei,
          requestData.lockDuration,
          requestData.pair || ethers.ZeroAddress,
          requestData.ethUsdPair || ethers.ZeroAddress,
          BigInt(requestData.targetPriceUSD1e18 || '0'),
          requestData.isEthPair !== undefined ? requestData.isEthPair : false,
          requestData.stablecoinPosition || 0,
          requestData.priceDirection || 0,
          BigInt(requestData.vestingUSDPerPeriod || '0'),
          requestData.vestingPeriodSeconds || 0,
          requestData.vestingIsStablecoin || false,
          signedNonce,  // 🔒 NONCE (CRITICAL FOR REPLAY PROTECTION)
          signature.signer
        ]
      );
      this.logger.debug('🔍 [WALLET opKey DEBUG] Calculated opKey with nonce:', opKeyForDebug);
      this.logger.debug('🔍 [WALLET opKey DEBUG] Nonce used:', signedNonce.toString());
      this.logger.debug('🔍 [WALLET opKey DEBUG] Params used:', {
        string: 'CREATE_LOCK',
        token: requestData.token,
        amount: amountWei.toString(),
        duration: requestData.lockDuration,
        pair: requestData.pair || ethers.ZeroAddress,
        ethUsdPair: requestData.ethUsdPair || ethers.ZeroAddress,
        targetPrice: (requestData.targetPriceUSD1e18 || '0').toString(),
        isEthPair: requestData.isEthPair !== undefined ? requestData.isEthPair : false,
        stablecoinPosition: requestData.stablecoinPosition || 0,
        signer: signature.signer
      });

      // Check and handle token approval (relayer must approve since they provide tokens)
      const token = this.contractService.getERC20Contract(requestData.token);
      const account = this.fromAddress || this.contractService.account$.value;
      if (!account) {
        throw new Error('No account connected or fromAddress missing');
      }

      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Checking allowance for relayer...');
      const allowance = await token['allowance'](account, lockerAddress);
      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Current relayer allowance:', allowance.toString());

      const txRequests: any[] = [];

      if (allowance < amountWei) {
        this.logger.debug('🔵 [CREATE LOCK WITH SIG] Insufficient allowance, adding approval to batch...');
        const data = token.interface.encodeFunctionData('approve', [lockerAddress, amountWei]);

        txRequests.push({
          to: requestData.token,
          data: data,
          suggestedOfflineSender: account,
          metadata: {
            operation: 'Approve Token',
            contract: this.tokenInfo.symbol,
            function: 'approve',
            args: {
              spender: lockerAddress,
              amount: requestData.amount
            }
          }
        });
      } else {
        this.logger.debug('✅ [CREATE LOCK WITH SIG] Sufficient allowance already granted');
      }

      this.logger.debug('🔵 [CREATE LOCK WITH SIG] Adding create lock to batch...');
      const lockData = locker.interface.encodeFunctionData('createLockWithSignatures', [lockParamsArray, sigParamsArray]);

      txRequests.push({
        to: await locker.getAddress(),
        data: lockData,
        suggestedOfflineSender: account,
        metadata: {
          operation: 'Create Lock',
          contract: 'Locker',
          function: 'createLockWithSignatures',
          args: {
            token: requestData.token,
            amount: requestData.amount,
            durationSeconds: requestData.lockDuration
          }
        }
      });

      // We wrap it in executeTransaction so the user's selected broadcast mode is respected!
      const signerComponent = locker.runner as ethers.Signer;
      // Note: We inject the forceMode into the first request so the interceptor respects it
      if (txRequests.length > 0) {
        txRequests[0].forceMode = this.selectedMode as any;
      }

      const receipt = await this.txInterceptor.executeTransaction(txRequests, signerComponent);

      if (receipt) {
        if (typeof receipt.wait === 'function') {
           await receipt.wait();
        }
        await this.activityTracker.trackTransaction(
          'CREATE_LOCK',
          account!,
          {
            token: requestData.token,
            tokenSymbol: this.tokenInfo.symbol,
            amount: this.amount,
            durationSeconds: requestData.lockDuration,
            targetPrice: requestData.targetPriceUSD1e18 || undefined,
            pairAddress: requestData.pair !== ethers.ZeroAddress ? requestData.pair : undefined
          },
          Promise.resolve(receipt),
          locker
        );

        this.toastService.success('✅ Lock created successfully with offline signature!');

        // Reset form
        this.scannedSignature = null;
        this.showSignatureQr = false;
        this.sigLockRequest = null;
        this.sigLockRequestQr = null;
        this.lockMode = 'REGULAR';
        this.amount = '';

        // Navigate to locks list
        this.router.navigate(['/locks']);
      } else {
        this.toastService.info('Lock transaction sent for offline signing. Scan and broadcast it to complete the lock.');
        this.executing = false;
        return;
      }

      this.executing = false;
    } catch (e: any) {
      this.logger.error('Failed to create lock with signature', e);
      this.executing = false;
      if (e.message !== 'User cancelled transaction' && e.message !== 'Offline signing required') {
        let msg = e.shortMessage || e.message;
        let finalMsg = typeof msg === 'string' ? msg : JSON.stringify(msg);
        
        if (finalMsg.includes('-32002') || (e.error && e.error.code === -32002)) {
             finalMsg = "RPC Rate Limit Exceeded: The network is busy. Please try again in 30 seconds or switch your network RPC endpoint.";
        }

        this.toastService.error('Error: ' + finalMsg);
      }
      // Do not re-throw here to prevent unhandled promise rejections crashing the application UI
    }
  }

  cancelSignatureWorkflow() {
    this.showSignatureQr = false;
    this.sigLockRequestQr = null;
    this.scanningLockSignature = false;
    this.scannedSignature = null;
  }

  async copyToClipboard(text: string) {
    try {
      await navigator.clipboard.writeText(text);
      this.toastService.success('✅ Copied to clipboard!');
    } catch (e) {
      this.logger.error('Failed to copy', e);
      this.toastService.error('❌ Failed to copy');
    }
  }

  cancel() {
    this.router.navigate(['/locks']);
  }

  ngOnDestroy(): void {
    this.logger.debug('[CreateLockComponent] destroyed');
  }
}

