import { Component, EventEmitter, Input, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-password-modal',
    standalone: true,
    imports: [CommonModule, FormsModule],
    templateUrl: './password-modal.component.html',
    styleUrls: ['./password-modal.component.scss']
})
export class PasswordModalComponent implements OnInit, OnDestroy {
    @Input() isOpen = false;
    @Input() title = 'Enter Password';
    @Input() subtitle = '';
    @Input() hint = 'Password must be at least 6 characters';
    @Input() confirmMode = false; // For password change: shows current + new + confirm
    @Input() setMode = false; // For initial password set: shows new + confirm only
    @Input() confirmButtonText = 'Confirm';

    @Output() confirm = new EventEmitter<{ password: string, currentPassword?: string }>();
    @Output() submitPassword = new EventEmitter<string>(); // Simple password-only event
    @Output() cancel = new EventEmitter<void>();

    password = '';
    currentPassword = '';
    confirmPassword = '';
    showPassword = false;
    showCurrentPassword = false;
    showConfirmPassword = false;
    errorMessage = '';

    isValid(): boolean {
        if (this.confirmMode) {
            return (
                this.currentPassword.length >= 6 &&
                this.password.length >= 6 &&
                this.password === this.confirmPassword
            );
        }
        if (this.setMode) {
            return (
                this.password.length >= 6 &&
                this.password === this.confirmPassword
            );
        }
        return this.password.length >= 6;
    }

    onConfirm(): void {
        if (!this.isValid()) {
            if ((this.confirmMode || this.setMode) && this.password !== this.confirmPassword) {
                this.errorMessage = 'Passwords do not match';
            } else {
                this.errorMessage = 'Password must be at least 6 characters';
            }
            return;
        }

        this.errorMessage = '';

        if (this.confirmMode) {
            this.confirm.emit({
                password: this.password,
                currentPassword: this.currentPassword
            });
        } else {
            this.confirm.emit({ password: this.password });
            this.submitPassword.emit(this.password); // Also emit simple string for convenience
        }

        this.reset();
    }

    onCancel(): void {
        this.cancel.emit();
        this.reset();
    }

    private reset(): void {
        this.password = '';
        this.currentPassword = '';
        this.confirmPassword = '';
        this.showPassword = false;
        this.showCurrentPassword = false;
        this.showConfirmPassword = false;
        this.errorMessage = '';
    }

    constructor(private logger: LoggerService) {
    }

    ngOnInit(): void {
        this.logger.debug('[PasswordModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[PasswordModalComponent] destroyed');
    }
}
