import { Component, EventEmitter, OnInit, OnDestroy, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ContractService } from '@services/contract.service';
import { ConfigService } from '@services/config.service';
import { BlockchainConfigService, ChainConfig } from '@services/blockchain-config.service';
import { ToastService } from '@services/toast.service';
import { APP_MODES } from '@core/constants';
import { IconComponent } from '../../components/ui/icon/icon.component';
import { TranslateModule } from '@ngx-translate/core';
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-network-selector-modal',
    standalone: true,
    imports: [CommonModule, IconComponent, TranslateModule],
    templateUrl: './network-selector-modal.component.html',
    styleUrls: ['./network-selector-modal.component.scss']
})
export class NetworkSelectorModalComponent implements OnInit, OnDestroy {
    @Output() close = new EventEmitter<void>();

    availableNetworks: ChainConfig[] = [];
    currentChainId: number | null = null;
    isWalletConnected = false;
    private subscriptions = new Subscription();

    constructor(
        private contractService: ContractService,
        private configService: ConfigService,
        private blockchainConfigService: BlockchainConfigService,
        private toastService: ToastService
    ) { }

    async ngOnInit() {
        await this.blockchainConfigService.loadConfig();
        this.availableNetworks = this.blockchainConfigService.getAllChains();

        this.subscriptions.add(
            this.contractService.account$.subscribe(account => {
                this.isWalletConnected = !!account;
            })
        );
        this.subscriptions.add(
            this.contractService.chainId$.subscribe(chainId => {
                this.currentChainId = chainId ? Number(chainId) : null;
            })
        );
    }

    ngOnDestroy() {
        this.subscriptions.unsubscribe();
    }

    closeModal() {
        this.close.emit();
    }

    getNetworkIconTarget(chainId: number): string {
        const mapping: Record<number, string> = {
            1: 'eth.svg',
            56: 'bnb.svg',
            137: 'matic.svg',
            42161: 'arb.svg',
            10: 'op.svg',
            8453: 'base.svg',
            43114: 'avax.svg',
            59144: 'linea.svg',
            324: 'zksync.svg',
            31337: 'eth.svg',
            1337: 'eth.svg'
        };
        const fileName = mapping[chainId] || 'eth.svg';
        return `assets/logo/${fileName}`;
    }

    async selectNetwork(network: ChainConfig) {
        if (network.chainId === this.currentChainId) {
            this.closeModal();
            return;
        }

        const modeToSet = (network.chainId === 1337 || network.chainId === 31337) ? APP_MODES.TEST : APP_MODES.PROD;

        if (this.isWalletConnected) {
            // Request MetaMask network change
            const networkSwitched = await this.contractService.switchNetwork(network.chainId);

            if (!networkSwitched) {
                this.toastService.error('Failed to switch network. Please switch manually in MetaMask.');
                return;
            }
        }

        this.configService.setMode(modeToSet);

        this.closeModal();

        // Reload page to reinitialize contracts properly
        setTimeout(() => {
            window.location.reload();
        }, 100);
    }
}
