import { ethers } from 'ethers';

/**
 * Formate une adresse Ethereum (tronquée)
 */
export function formatAddress(address: string, start: number = 6, end: number = 4): string {
    if (!address) return '';
    if (address.length <= start + end) return address;
    return `${address.slice(0, start)}...${address.slice(-end)}`;
}

/**
 * Formate un montant de tokens
 * @param amount - Montant en wei (BigInt ou string)
 * @param decimals - Nombre de décimales du token (défaut: 18)
 * @param precision - Nombre de décimales à afficher (défaut: decimals)
 * @param exact - Si true, affiche toutes les décimales sans arrondi
 */
export function formatTokenAmount(
    amount: bigint | string | number,
    decimals: number = 18,
    precision: number | null = null,
    exact: boolean = false
): string {
    if (!amount) return '0';
    try {
        const formatted = ethers.formatUnits(amount, decimals);

        if (exact) {
            // Afficher toutes les décimales sans arrondi
            return formatted.replace(/\.?0+$/, '');
        }

        // Si precision n'est pas spécifié, utiliser decimals
        const finalPrecision = precision !== null ? precision : decimals;

        const num = parseFloat(formatted);
        const fixed = num.toFixed(finalPrecision);
        // Retirer les zéros de fin
        return fixed.replace(/\.?0+$/, '');
    } catch (error) {
        return amount.toString();
    }
}

/**
 * Obtient le montant exact en format string (sans arrondi)
 */
export function getExactTokenAmount(amount: bigint | string | number, decimals: number = 18): string {
    if (!amount) return '0';
    try {
        return ethers.formatUnits(amount, decimals).replace(/\.?0+$/, '');
    } catch (error) {
        return amount.toString();
    }
}

/**
 * Formate un montant en ETH
 */
export function formatETH(amount: bigint | string | number, precision: number = 6): string {
    return formatTokenAmount(amount, 18, precision);
}

/**
 * Formate un prix en USD (format 1e18)
 */
export function formatPriceUSD(price: bigint | string | number, precision: number = 8): string {
    return formatTokenAmount(price, 18, precision);
}

/**
 * Convertit un timestamp BigInt en number de manière sécurisée
 * Gère à la fois ethers v5 BigNumber (.toNumber()) et ethers v6 BigInt natif
 */
export function timestampToNumber(timestamp: any): number {
    if (!timestamp) return 0;

    // ethers v6: BigInt natif
    if (typeof timestamp === 'bigint') {
        return Number(timestamp);
    }

    // ethers v5: BigNumber avec méthode toNumber()
    if (typeof timestamp === 'object' && 'toNumber' in timestamp) {
        return timestamp.toNumber();
    }

    // Déjà un number ou string convertible
    return Number(timestamp);
}

/**
 * Formate un timestamp en date lisible
 * Compatible avec ethers v5 BigNumber et ethers v6 BigInt
 */
export function formatDate(timestamp: any): string {
    if (!timestamp) return 'N/A';
    try {
        const ts = timestampToNumber(timestamp);
        if (ts === 0) return 'Non défini';

        const date = new Date(ts * 1000);
        return date.toLocaleString('fr-FR', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit'
        });
    } catch (error) {
        console.error('Error formatting date:', error);
        return 'Erreur de date';
    }
}

/**
 * Formate une durée en secondes en texte lisible
 */
export function formatDuration(seconds: number): string {
    if (!seconds || seconds === 0) return '0s';

    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    const parts: string[] = [];
    if (days > 0) parts.push(`${days}j`);
    if (hours > 0) parts.push(`${hours}h`);
    if (minutes > 0 || days > 0 || hours > 0) parts.push(`${minutes}min`);
    if (secs > 0 && parts.length === 0) parts.push(`${secs}s`);

    return parts.join(' ') || '0s';
}

/**
 * Formate un pourcentage
 */
export function formatPercent(value: any, precision: number = 2): string {
    if (value === null || value === undefined) return '0';

    let num: number;
    if (typeof value === 'bigint') {
        num = Number(value);
    } else if (typeof value === 'object' && '_isBigNumber' in value) {
        // ethers v5 BigNumber
        num = parseFloat(value.toString());
    } else if (typeof value === 'string') {
        num = parseFloat(value);
    } else {
        num = value;
    }

    if (isNaN(num)) return '0';
    return num.toFixed(precision);
}

/**
 * Formate un montant (alias pour formatTokenAmount)
 */
export function formatAmount(
    amount: bigint | string | number,
    decimals: number = 18,
    precision: number = 6
): string {
    return formatTokenAmount(amount, decimals, precision);
}
