import { Injectable } from '@angular/core';
import { ethers } from 'ethers';

import { ConfigService } from './config.service';
import { LoggerService } from "@services/logger.service";

const PAIR_V2_ABI = [
    "function getReserves() view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast)",
    "function token0() view returns (address)",
    "function token1() view returns (address)"
];

const PAIR_V3_ABI = [
    "function slot0() view returns (uint160 sqrtPriceX96, int24 tick, uint16 observationIndex, uint16 observationCardinality, uint16 observationCardinalityNext, uint8 feeProtocol, bool unlocked)",
    "function liquidity() view returns (uint128)",
    "function token0() view returns (address)",
    "function token1() view returns (address)"
];

const ERC20_ABI = [
    "function decimals() view returns (uint8)"
];

const PRICE_CALCULATOR_ABI = [
    "function getPriceUSD(address tokenPair, address token, address usdPair, bool isEthPair, uint8 stablecoinPosition) external view returns (uint256)"
];

@Injectable({
    providedIn: 'root'
})
export class PriceService {

    constructor(

        private configService: ConfigService, private logger: LoggerService
    ) { }

    private getProvider() {
        // We do not need the injected (MetaMask) provider for read-only price checks.
        // Using a direct JsonRpcProvider avoids MetaMask local cache desync issues.
        return new ethers.JsonRpcProvider(this.configService.rpcUrl);
    }

    async getPairReserves(pairAddress: string): Promise<any> {
        // Early validation - check if address looks valid
        if (!pairAddress || pairAddress === ethers.ZeroAddress) {
            throw new Error('Invalid pair address');
        }

        // Try V3 first, then V2 (simplified strategy)
        try {
            return await this.getPairReservesV3(pairAddress);
        } catch (e) {
            // Silent fallback to V2 - don't log if it's just a method not found
            try {
                return await this.getPairReservesV2(pairAddress);
            } catch (e2) {
                // Both V3 and V2 failed - pair likely doesn't exist or is invalid
                throw new Error(`Failed to fetch reserves for pair ${pairAddress}: Not a valid V2 or V3 pair`);
            }
        }
    }

    async getPairReservesV3(pairAddress: string) {
        const provider = this.getProvider();
        if (!provider) throw new Error("No provider");

        const pairV3 = new ethers.Contract(pairAddress, PAIR_V3_ABI, provider);

        const [token0, token1, slot0, liquidity] = await Promise.all([
            pairV3['token0'](),
            pairV3['token1'](),
            pairV3['slot0'](),
            pairV3['liquidity']()
        ]);

        const [decimals0, decimals1] = await this.getDecimals(token0, token1, provider);

        return {
            version: 'V3',
            reserve0: BigInt(0), // Calculated from sqrtPrice if needed, but we use sqrtPriceX96 usually
            reserve1: BigInt(0),
            token0,
            token1,
            decimals0,
            decimals1,
            sqrtPriceX96: slot0.sqrtPriceX96,
            liquidity
        };
    }

    async getPairReservesV2(pairAddress: string) {
        const provider = this.getProvider();
        if (!provider) throw new Error("No provider");

        const pairV2 = new ethers.Contract(pairAddress, PAIR_V2_ABI, provider);

        const [reserves, token0, token1] = await Promise.all([
            pairV2['getReserves'](),
            pairV2['token0'](),
            pairV2['token1']()
        ]);

        const [decimals0, decimals1] = await this.getDecimals(token0, token1, provider);

        return {
            version: 'V2',
            reserve0: reserves.reserve0,
            reserve1: reserves.reserve1,
            token0,
            token1,
            decimals0,
            decimals1
        };
    }

    private async getDecimals(token0: string, token1: string, provider: any) {
        const t0 = new ethers.Contract(token0, ERC20_ABI, provider);
        const t1 = new ethers.Contract(token1, ERC20_ABI, provider);
        return await Promise.all([t0['decimals'](), t1['decimals']()]);
    }

    // Adapted from JS implementation
    async getTokenPrice(tokenAddress: string, pairAddress: string, ethUsdPairAddress: string | null = null, stablecoinPosition: number = 0) {
        try {
            const reserves = await this.getPairReserves(pairAddress);


            // AUTO-DETECT stablecoinPosition if not provided (for direct pairs)
            let finalStablecoinPos = stablecoinPosition;
            if (!ethUsdPairAddress || ethUsdPairAddress === ethers.ZeroAddress) {
                // Direct pair - auto-detect stablecoinPosition if zero
                if (finalStablecoinPos === 0) {
                    // Check token decimals to guess stablecoin
                    if (reserves.decimals0 === 6 || reserves.decimals0 === 18 && reserves.decimals1 < 18) {
                        finalStablecoinPos = 1; // token0 likely stablecoin
                    } else if (reserves.decimals1 === 6 || reserves.decimals1 === 18 && reserves.decimals0 < 18) {
                        finalStablecoinPos = 2; // token1 likely stablecoin
                    }
                    this.logger.debug('[AUTO-DETECT] Stablecoin position:', finalStablecoinPos, 'decimals:', reserves.decimals0, reserves.decimals1);
                }
            }

            let priceInToken1: bigint; // Relative price (Token/Other)

            if (reserves.version === 'V3' && reserves.sqrtPriceX96) {
                priceInToken1 = this.calculateV3Price(reserves.sqrtPriceX96, tokenAddress, reserves.token0, reserves.decimals0, reserves.decimals1);
            } else {
                priceInToken1 = this.calculateV2Price(reserves.reserve0, reserves.reserve1, tokenAddress, reserves.token0, reserves.decimals0, reserves.decimals1);
            }

            let priceInUSD = priceInToken1; // Default if direct

            // ETH Conversion logic
            if (ethUsdPairAddress && ethUsdPairAddress.toLowerCase() !== pairAddress.toLowerCase()) {
                try {
                    // Fetch ETH price
                    const ethReserves = await this.getPairReserves(ethUsdPairAddress);

                    // Identify WETH in the ETH/USD pair (usually the one with 18 decimals)
                    let wethTokenAddr = ethReserves.token0;
                    if (ethReserves.decimals0 < 18) {
                        wethTokenAddr = ethReserves.token1;
                    } else if (ethReserves.decimals1 < 18) {
                        wethTokenAddr = ethReserves.token0;
                    }

                    const ethPriceUSD = this.calculateV2Price(ethReserves.reserve0, ethReserves.reserve1, wethTokenAddr, ethReserves.token0, ethReserves.decimals0, ethReserves.decimals1);

                    // If the user requested the price of WETH explicitly, do NOT double multiply!
                    // Note: If MetaMask desyncs on localhost, tokenAddress (`0x5Fb...`) might not match 
                    // the on-chain WETH address (`0x506...`). We aggressively assume it's WETH if it's 
                    // queried from an ETH pair and wasn't found in the altcoin's reserves, 
                    // or if the pair is a direct USD/ETH pair. 
                    let isTargetTokenWeth = false;

                    if (tokenAddress.toLowerCase() === ethReserves.token0.toLowerCase() ||
                        tokenAddress.toLowerCase() === ethReserves.token1.toLowerCase() ||
                        tokenAddress.toLowerCase() === wethTokenAddr.toLowerCase() ||
                        // Heuristic: If we are evaluating a USD-to-WETH direct pool, the price of the 'asset' 
                        // IS the price of WETH. 
                        pairAddress.toLowerCase() === ethUsdPairAddress.toLowerCase() ||
                        // If we are evaluating a V3 pool like USD1/WETH and asking for WETH 
                        priceInToken1 === ethers.parseUnits("1", 18) // WETH/WETH = 1
                    ) {
                        isTargetTokenWeth = true;
                    }

                    // A stronger heuristic for the MetaMask local network desync issue:
                    // If the user's pair is explicitly an ETH pair (meaning we are executing this block),
                    // and the price of the token in the pair is exactly ~1.0 WETH (because it IS Weth),
                    // or if the UI's selected token address doesn't match the on-chain reserves but 
                    // we know they selected the WETH side of a WETH/Stable pool.

                    // Actually, the simplest fix: If we are calculating from USD1/WETH and evaluating WETH (Stablecoin Pos 0),
                    // the "priceInToken1" isn't 1, it's the ratio. Wait.
                    // If UI requested WETH, `priceInToken1` is how many token1s per WETH. 
                    // If the pair is USD1/WETH, `priceInToken1` = ~2030 USD1 per WETH. 
                    // So `priceInToken1` is ALREADY the price in USD!
                    // If they requested WETH from USD1/WETH, `priceInToken1 ≈ 2030e18`.
                    // If we blindly multiply by `ethPriceUSD` (2035), we get 4 million.

                    // The core issue: is the `pairAddress` itself already a USD-pegged pairing for the token?
                    // If yes, `priceInToken1` is already in USD.
                    if (finalStablecoinPos !== 0) {
                        // If it's a stablecoin pair, priceInToken1 is already in USD.
                        priceInUSD = priceInToken1;
                    } else if (priceInToken1 > ethers.parseUnits("100", 18)) {
                        // Extreme heuristic for testnet UI desyncs: 
                        // If the "price in ETH" is > 100 ETH, it's actually the price in USD.
                        // (Because WETH evaluates to ~2000 USD1, whereas a normal token like UNI evaluates to 0.002 WETH).
                        // This prevents multiplying 2000 * 2000 = 4,000,000.
                        isTargetTokenWeth = true;
                    }

                    if (isTargetTokenWeth) {
                        // They requested WETH, or the "token" is already priced in a stablecoin natively.
                        // Wait, if it's already priced in stablecoin natively, priceInToken1 is the correct USD price.
                        // But wait, if they requested USD1 from USD1/WETH, priceInToken1 is ~0.0004.
                        // Then it falls to `priceInUSD = 0.0004 * 2035 = 1.00`. This works!
                        priceInUSD = priceInToken1;
                    } else {
                        // Price = PriceInETH * EthPriceInUSD / 1e18
                        priceInUSD = (priceInToken1 * ethPriceUSD) / ethers.parseUnits("1", 18);
                    }
                } catch (e) {
                    // If ETH price fetch fails, use direct price
                    this.logger.warn('Failed to fetch ETH/USD price, using direct pair price');
                }
            }

            const jsCalculatedPrice = priceInUSD;

            // On-chain validation - PRIORITIZE contract price
            try {
                const provider = this.getProvider();
                if (this.configService.contracts.PriceCalculator && provider) {
                    const calculator = new ethers.Contract(this.configService.contracts.PriceCalculator, PRICE_CALCULATOR_ABI, provider);
                    const usdPairToUse = ethUsdPairAddress || ethers.ZeroAddress;
                    // Properly derive isEthPair from stablecoinPosition rather than presence of usdPairToUse
                    const isEthPair = finalStablecoinPos === 0;

                    // If it's an ETH pair but no USD pair is provided, the contract will revert.
                    // So we skip on-chain validation safely and just use the JS calculated price.
                    if (isEthPair && usdPairToUse === ethers.ZeroAddress) {
                        this.logger.warn('[VALIDATION] Skipping contract validation: ETH pair requires an ETH/USD pair config');
                        return {
                            priceInUSD: jsCalculatedPrice,
                            priceInToken1: priceInToken1,
                            formattedUSD: ethers.formatUnits(jsCalculatedPrice, 18)
                        };
                    }

                    this.logger.debug('[VALIDATION] Calling PriceCalculator.getPriceUSD:', {
                        pairAddress,
                        tokenAddress,
                        usdPairToUse,
                        isEthPair,
                        stablecoinPosition: finalStablecoinPos
                    });

                    const contractPrice = await calculator['getPriceUSD'](
                        pairAddress,
                        tokenAddress,
                        usdPairToUse,
                        isEthPair,
                        finalStablecoinPos
                    );

                    this.logger.debug('[VALIDATION] Contract price:', ethers.formatUnits(contractPrice, 18));

                    // Compare JS calculated price vs Contract price
                    const jsPriceBN = jsCalculatedPrice;
                    const contractPriceBN = contractPrice;

                    // Calculate difference in percentage
                    let diffPercent = 0;
                    if (jsPriceBN > 0n && contractPriceBN > 0n) {
                        const diff = jsPriceBN > contractPriceBN
                            ? jsPriceBN - contractPriceBN
                            : contractPriceBN - jsPriceBN;
                        // Difference in basis points (1 bp = 0.01%)
                        diffPercent = Number((diff * 10000n) / jsPriceBN) / 100;
                    }

                    const priceComparison = {
                        jsPrice: jsPriceBN.toString(),
                        contractPrice: contractPriceBN.toString(),
                        jsPriceFormatted: ethers.formatUnits(jsPriceBN, 18),
                        contractPriceFormatted: ethers.formatUnits(contractPriceBN, 18),
                        diffPercent: diffPercent,
                        match: diffPercent < 0.1 // < 0.1% difference
                    };

                    this.logger.debug('[VALIDATION] Comparaison JS vs Contract:', priceComparison);

                    if (!priceComparison.match) {
                        this.logger.warn('⚠️  DIVERGENCE DÉTECTÉE entre calcul JS et contrat!');
                        this.logger.warn('   Prix JS:       $' + priceComparison.jsPriceFormatted);
                        this.logger.warn('   Prix Contract: $' + priceComparison.contractPriceFormatted);
                        this.logger.warn('   Différence:    ' + priceComparison.diffPercent.toFixed(2) + '%');
                    } else {
                        this.logger.debug('✅ Prix JS et Contract correspondent (< 0.1% différence)');
                    }

                    // Use contract price as authoritative
                    priceInUSD = contractPrice;
                } else {
                    this.logger.warn('[VALIDATION] PriceCalculator not configured');
                }
            } catch (e: any) {
                // Validation failed - use calculated price with warning
                this.logger.warn('[VALIDATION] Contract call failed:', e.message, '- using JS calculated price');
                priceInUSD = jsCalculatedPrice;
            }

            return {
                priceInUSD,
                priceInToken1,
                formattedUSD: ethers.formatUnits(priceInUSD, 18)
            };
        } catch (e: any) {
            // Return zero price on any error to prevent crashes
            this.logger.warn(`Failed to fetch price for ${tokenAddress}:`, e.message);
            return {
                priceInUSD: BigInt(0),
                priceInToken1: BigInt(0),
                formattedUSD: '0'
            };
        }
    }

    private calculateV2Price(r0: bigint, r1: bigint, targetToken: string, t0: string, d0: bigint, d1: bigint) {
        const oneE18 = ethers.parseUnits("1", 18);

        if (t0.toLowerCase() === targetToken.toLowerCase()) {
            // Price = r1 / r0
            // Adjust decimals: r1 * 10^(d0-d1) / r0
            const diff = d0 - d1;
            if (diff > 0n) {
                return (r1 * (10n ** diff) * oneE18) / r0;
            } else {
                return (r1 * oneE18) / (r0 * (10n ** (-diff)));
            }
        } else {
            // Price = r0 / r1
            const diff = d1 - d0;
            if (diff > 0n) {
                return (r0 * (10n ** diff) * oneE18) / r1;
            } else {
                return (r0 * oneE18) / (r1 * (10n ** (-diff)));
            }
        }
    }

    private calculateV3Price(sqrtPriceX96: bigint, targetToken: string, t0: string, d0: bigint, d1: bigint) {
        // Simplified V3 math (from JS service)
        const oneE18 = ethers.parseUnits("1", 18);


        // price = (sqrtPrice / 2^96) ^ 2
        // We use full math style to avoid precision loss

        // P = (sqrtPriceX96 * 10^9 / 2^96)^2 is approx
        // Better: priceX96 = sqrtPriceX96^2
        // Then adjust for decimals

        const priceX96 = sqrtPriceX96 * sqrtPriceX96;
        const Q192 = 2n ** 192n;

        if (t0.toLowerCase() === targetToken.toLowerCase()) {
            // Price = token1/token0
            if (d0 === d1) return (priceX96 * oneE18) / Q192;
            // Adjust... 
            // Completing logic similar to JS...
            const factor = 10n ** (d0 > d1 ? d0 - d1 : d1 - d0);
            return d0 > d1 ? (priceX96 * factor * oneE18) / Q192 : (priceX96 * oneE18) / (Q192 * factor);
        } else {
            // Invert
            if (d0 === d1) return (oneE18 * Q192) / priceX96;
            const factor = 10n ** (d1 > d0 ? d1 - d0 : d0 - d1);
            return d1 > d0 ? (factor * oneE18 * Q192) / priceX96 : (oneE18 * Q192) / (priceX96 * factor);
        }
    }
}
