import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
    name: 'currencyFormat',
    standalone: true
})
export class CurrencyFormatPipe implements PipeTransform {
    transform(value: string | number, showCents: boolean = true): string {
        if (value === 'N/A' || value === null || value === undefined) {
            return 'N/A';
        }

        // Remove $ sign if present
        let numValue: number;
        let originalPrecision: number | undefined;

        if (typeof value === 'string') {
            numValue = parseFloat(value.replace(/[$,]/g, ''));
            // Detect existing decimal places in the string
            const match = value.match(/\.(\d+)/);
            if (match) {
                originalPrecision = match[1].length;
            }
        } else {
            numValue = value;
        }

        if (isNaN(numValue)) {
            return 'N/A';
        }

        // Use original precision if available (from pre-formatted strings), otherwise use showCents flag
        const fractionDigits = originalPrecision !== undefined
            ? { minimumFractionDigits: originalPrecision, maximumFractionDigits: originalPrecision }
            : { minimumFractionDigits: showCents ? 2 : 0, maximumFractionDigits: showCents ? 2 : 0 };

        // Format with thousands separator
        const formatted = new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            ...fractionDigits
        }).format(numValue);

        return formatted;
    }
}
