import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { TransactionInterceptorService } from '@services/transaction-interceptor.service';
import { SenderAddressModalComponent } from '../sender-address-modal/sender-address-modal.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-tx-sender-modal',
    standalone: true,
    imports: [CommonModule, SenderAddressModalComponent],
    templateUrl: './tx-sender-modal.component.html'
})
export class TxSenderModalComponent implements OnInit, OnDestroy {
    showModal = false;
    suggestedAddress: string | null = null;

    private subscription: Subscription | null = null;

    constructor(private txInterceptor: TransactionInterceptorService, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[TxSenderModalComponent] initialized');
        this.subscription = this.txInterceptor.senderRequest$.subscribe(request => {
            if (request) {
                this.suggestedAddress = request.suggestedAddress || null;
                this.showModal = true;
            } else {
                this.showModal = false;
                this.suggestedAddress = null;
            }
        });
    }

    ngOnDestroy() {
        this.logger.debug('[TxSenderModalComponent] destroyed');
        this.subscription?.unsubscribe();
    }

    onSenderConfirmed(event: { address: string; nonce: number }) {
        // Send the selected address back to the service
        this.txInterceptor.selectSender(event.address);
        this.close();
    }

    onSenderCancelled() {
        // User cancelled - send null
        this.txInterceptor.selectSender(null);
        this.close();
    }

    private close() {
        this.showModal = false;
    }
}
