import { Component, ChangeDetectionStrategy, ChangeDetectorRef, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { Title, Meta } from '@angular/platform-browser';
import { IconComponent } from '@components/ui/icon/icon.component';
import { AddLockerModalComponent } from '@modals/add-locker-modal/add-locker-modal.component';
import { ContractService } from '@services/contract.service';

@Component({
  selector: 'app-welcome',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslateModule, IconComponent, AddLockerModalComponent],
  templateUrl: './welcome.component.html',
  styleUrl: './welcome.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WelcomeComponent implements OnInit {
  isAddModalOpen = false;

  supportedNetworks = [
    { name: 'Ethereum', icon: 'assets/logo/eth.svg' },
    { name: 'Arbitrum', icon: 'assets/logo/arb.svg' },
    { name: 'Avalanche', icon: 'assets/logo/avax.svg' },
    { name: 'Base', icon: 'assets/logo/base.svg' },
    { name: 'BNB Chain', icon: 'assets/logo/bnb.svg' },
    { name: 'Linea', icon: 'assets/logo/linea.svg' },
    { name: 'Polygon', icon: 'assets/logo/matic.svg' },
    { name: 'Optimism', icon: 'assets/logo/op.svg' },
    { name: 'zkSync', icon: 'assets/logo/zksync.svg' }
  ];

  openFaqIndex: number | null = null;
  faqItems = Array.from({length: 20}, (_, i) => i + 1);

  constructor(
    private router: Router,
    private contractService: ContractService,
    private cdr: ChangeDetectorRef,
    private titleService: Title,
    private metaService: Meta,
    private translate: TranslateService
  ) {}

  ngOnInit(): void {
    // Set SEO Meta Tags when French or English translations load
    this.translate.get(['WELCOME.TITLE', 'WELCOME.SUBTITLE']).subscribe(translations => {
      const title = translations['WELCOME.TITLE'] + ' | Locker Ecosystem';
      const description = translations['WELCOME.SUBTITLE'];

      this.titleService.setTitle(title);
      
      this.metaService.updateTag({ name: 'description', content: description });
      
      // Open Graph
      this.metaService.updateTag({ property: 'og:title', content: title });
      this.metaService.updateTag({ property: 'og:description', content: description });
      this.metaService.updateTag({ property: 'og:type', content: 'website' });
      this.metaService.updateTag({ property: 'og:url', content: window.location.href });
      // In a real app we would link to the actual domain's image
      this.metaService.updateTag({ property: 'og:image', content: `${window.location.origin}/assets/icons/icon-512x512.png` });

      // Twitter Cards
      this.metaService.updateTag({ name: 'twitter:card', content: 'summary_large_image' });
      this.metaService.updateTag({ name: 'twitter:title', content: title });
      this.metaService.updateTag({ name: 'twitter:description', content: description });
      this.metaService.updateTag({ name: 'twitter:image', content: `${window.location.origin}/assets/icons/icon-512x512.png` });
    });
  }

  toggleFaq(index: number): void {
    this.openFaqIndex = this.openFaqIndex === index ? null : index;
  }

  async onAddLocker(data: { address: string; name: string }) {
    this.isAddModalOpen = false;
    
    // Add the new Locker to IndexedDB/localStorage
    const customLockersStr = localStorage.getItem('customLockers');
    let customLockers = customLockersStr ? JSON.parse(customLockersStr) : [];
    const chainId = Number(this.contractService.chainId$.value) || 0;

    customLockers.push({
      address: data.address,
      name: data.name,
      network: 'Custom',
      chainId: chainId,
      isActive: true
    });

    localStorage.setItem('customLockers', JSON.stringify(customLockers));
    
    // Switch to the newly added locker
    await this.contractService.switchLocker(data.address, false);
    
    // Redirect to dashboard (which redirects back to welcome if strictly user mode, but this establishes the locker)
    // Actually, in user mode with a locker, they shouldn't be blocked.
    // For now, redirect to dashboard.
    this.router.navigate(['/']);
    this.cdr.markForCheck();
  }
}
