
import { Component, OnInit, OnDestroy, DestroyRef, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { filter } from 'rxjs/operators';
import { CommonModule } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { RouterLink } from '@angular/router';
import { ethers } from 'ethers';
import { ContractService, LockDetails } from '@services/contract.service';
import { ConfigService } from '@services/config.service';
import { ActivityService } from '@core/services/activity.service';
import { Activity, ACTIVITY_LABELS } from '@core/models/activity.model';
import { IconComponent } from '@components/ui/icon/icon.component';
import { LockCardComponent } from '@components/ui/lock-card/lock-card.component';
import { ToastService } from '@services/toast.service';
import { formatTokenAmount, timestampToNumber } from '@utils/formatters';
import { LoggerService } from "@services/logger.service";

interface ContractInfo {
    name: string;
    address: string;
    category: 'core' | 'token' | 'pair-v2' | 'pair-v3';
}

@Component({
    selector: 'app-dashboard',
    standalone: true,
    imports: [CommonModule, RouterLink, IconComponent, LockCardComponent, TranslateModule],
    templateUrl: './dashboard.component.html',
    styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit, OnDestroy {
    private destroyRef = inject(DestroyRef);
    activityLabels = ACTIVITY_LABELS;


    activeLocksCount = 0;
    signersCount = 0;
    threshold = 0;
    ownerAddress: string | null = null;
    chainId: bigint | null = null;
    isLoading = true;

    // Recent activities
    recentActivities: Activity[] = [];
    loadingActivities = false;

    // Recent Locks
    recentLocks: any[] = [];
    loadingLocks = false;

    coreContracts: ContractInfo[] = [];
    tokenContracts: ContractInfo[] = [];
    pairContractsV2: ContractInfo[] = [];
    pairContractsV3: ContractInfo[] = [];

    showPairsV2 = false;
    showPairsV3 = false;

    constructor(
        private contractService: ContractService,
        public configService: ConfigService,
        private activityService: ActivityService,
        private translate: TranslateService,
        private toastService: ToastService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[DashboardComponent] initialized');

        // Subscribe to locker changes to load data initially and when switched
        this.contractService.currentLocker$
            .pipe(
                filter(address => !!address),
                takeUntilDestroyed(this.destroyRef)
            )
            .subscribe((lockerAddress) => {
                this.logger.debug('[DashboardComponent] locker changed or loaded:', lockerAddress);
                this.loadContracts();
                this.loadStats();
                this.loadRecentActivities();
                this.loadRecentLocks();
            });

        // Subscribe to chainId changes
        this.contractService.chainId$
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe(chainId => {
                this.chainId = chainId;
            });

        // Listen for account changes and reload data
        let previousAccount: string | null = null;
        this.contractService.account$
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe(address => {
                if (address) {
                    const normalizedAddress = address.toLowerCase();
                    if (previousAccount && previousAccount.toLowerCase() !== normalizedAddress) {
                        this.logger.debug('🔄 Dashboard: Account changed, reloading data...');
                        this.loadContracts();
                        this.loadStats();
                        this.loadRecentLocks();
                    }
                    previousAccount = address;
                }
            });

        // Listen for contract context hydration (happens after locker switch)
        this.configService.activeContracts$
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe(contracts => {
                if (contracts) {
                    this.logger.debug('🔄 Dashboard: Contract context updated, reloading data...');
                    this.loadContracts();
                    this.loadStats();
                    this.loadRecentLocks();
                }
            });
    }

    loadContracts() {
        const contracts = this.configService.contracts as any;

        // Core contracts
        this.coreContracts = [
            { name: 'LockerContract', address: contracts.LockerContract, category: 'core' },
            { name: 'PriceCalculator', address: contracts.PriceCalculator, category: 'core' },
            { name: 'ValidationHandler', address: contracts.ValidationHandler, category: 'core' },
            { name: 'LockManager', address: contracts.LockManager, category: 'core' },
            { name: 'SignerManager', address: contracts.SignerManager, category: 'core' }
        ];

        // Token contracts (only in test mode)
        if (!this.configService.isProd) {
            this.tokenContracts = [
                { name: 'TestToken', address: contracts.TestToken, category: 'token' },
                { name: 'WETH', address: contracts.WETH, category: 'token' },
                { name: 'USDC', address: contracts.USDC, category: 'token' },
                { name: 'USDT', address: contracts.USDT, category: 'token' },
                { name: 'DAI', address: contracts.DAI, category: 'token' },
                { name: 'TestToken2', address: contracts.TestToken2, category: 'token' },
                { name: 'TestToken3', address: contracts.TestToken3, category: 'token' }
            ];

            // V2 Pairs
            this.pairContractsV2 = [
                { name: 'WETH/USDC Pair', address: contracts.WETHUSDCPair, category: 'pair-v2' },
                { name: 'TestToken/WETH Pair', address: contracts.TestTokenWETHPairV2, category: 'pair-v2' },
                { name: 'TestToken/USDC Pair', address: contracts.TestTokenUSDCPairV2, category: 'pair-v2' },
                { name: 'TestToken2/WETH Pair', address: contracts.TestToken2WETHPairV2, category: 'pair-v2' },
                { name: 'TestToken2/USDC Pair', address: contracts.TestToken2USDCPairV2, category: 'pair-v2' },
                { name: 'TestToken3/WETH Pair', address: contracts.TestToken3WETHPairV2, category: 'pair-v2' },
                { name: 'TestToken3/USDC Pair', address: contracts.TestToken3USDCPairV2, category: 'pair-v2' }
            ];

            // V3 Pairs
            this.pairContractsV3 = [
                { name: 'TestToken/WETH Pair', address: contracts.TestTokenWETHPairV3, category: 'pair-v3' },
                { name: 'TestToken/USDC Pair', address: contracts.TestTokenUSDCPairV3, category: 'pair-v3' },
                { name: 'TestToken2/WETH Pair', address: contracts.TestToken2WETHPairV3, category: 'pair-v3' },
                { name: 'TestToken2/USDC Pair', address: contracts.TestToken2USDCPairV3, category: 'pair-v3' },
                { name: 'TestToken3/WETH Pair', address: contracts.TestToken3WETHPairV3, category: 'pair-v3' },
                { name: 'TestToken3/USDC Pair', address: contracts.TestToken3USDCPairV3, category: 'pair-v3' }
            ];
        }
    }

    async loadStats() {
        try {
            this.isLoading = true;

            this.logger.debug('📊 [Dashboard] Fetching stats...');
            const [tokens, signers, owner] = await Promise.all([
                this.contractService.getLockedTokens(),
                this.contractService.getSigners(),
                this.contractService.getOwner()
            ]);

            this.logger.debug('📊 [Dashboard] Stats received:', {
                tokens,
                tokensLength: tokens.length,
                signers,
                signersLength: signers.length,
                owner
            });

            this.activeLocksCount = tokens.length;
            this.signersCount = signers.length;
            this.ownerAddress = owner;

            // Load threshold separately (may not be set yet if no signers)
            try {
                const locker = this.contractService.getLockerContract();
                this.threshold = Number(await locker['approvalsThreshold']());
            } catch {
                this.threshold = 0;
            }

            this.logger.debug('📊 [Dashboard] Final counts:', {
                activeLocksCount: this.activeLocksCount,
                signersCount: this.signersCount,
                ownerAddress: this.ownerAddress
            });

            this.isLoading = false;

        } catch (e) {
            this.logger.error("❌ [Dashboard] Error loading dashboard stats", e);
            this.isLoading = false;
        }
    }

    async loadRecentActivities() {
        try {
            this.loadingActivities = true;
            this.recentActivities = await this.activityService.getLatestActivities(5);
            this.loadingActivities = false;
        } catch (e) {
            this.logger.error("Error loading recent activities", e);
            this.loadingActivities = false;
        }
    }

    async loadRecentLocks() {
        this.loadingLocks = true;
        try {
            // Get all lock IDs
            const lockIds = await this.contractService.getAllLocks();

            if (lockIds.length === 0) {
                this.recentLocks = [];
                this.loadingLocks = false;
                return;
            }

            // Take only the last 3 locks
            const recentLockIds = lockIds.slice(-3).reverse();

            // Fetch details for recent locks
            const detailsPromises = recentLockIds.map(lockId => this.contractService.getLockDetails(lockId));
            const details = await Promise.all(detailsPromises);
            const validDetails = details.filter((l): l is LockDetails => l !== null);

            // Map the data to UI format
            this.recentLocks = validDetails.map((detail, index) => {
                return this.mapLockData(detail, recentLockIds[index]);
            });

            // Enrich with current prices
            await this.enrichWithCurrentPrices(validDetails);
        } catch (e) {
            this.logger.error('❌ [Dashboard] Failed to load recent locks:', e);
        } finally {
            this.loadingLocks = false;
        }
    }

    /**
     * Fetch current token prices from PriceCalculator and update valueUSD
     */
    async enrichWithCurrentPrices(validDetails: LockDetails[]) {
        for (let i = 0; i < validDetails.length; i++) {
            const detail = validDetails[i];
            const lock: any = this.recentLocks[i];

            // Check if this lock has pricing info
            const pricing = detail.lockData.pricing;
            if (!pricing) continue;

            const pairAddress = pricing.pairAddress || pricing[0];
            if (!pairAddress || pairAddress === '0x0000000000000000000000000000000000000000') continue;

            try {
                const ethUsdPairAddress = pricing.ethUsdPairAddress || pricing[1];
                const isEthPair = pricing.isEthPair ?? pricing[2];
                const stablecoinPosition = pricing.stablecoinPosition ?? pricing[3];

                const currentPriceUSD1e18 = await this.contractService.getTokenPriceUSD(
                    detail.tokenAddress,
                    pairAddress,
                    ethUsdPairAddress || null,
                    isEthPair,
                    stablecoinPosition
                );

                if (currentPriceUSD1e18 > 0n) {
                    const currentPriceUSD = Number(ethers.formatUnits(currentPriceUSD1e18, 18));
                    const numAmount = parseFloat(lock.amount.replace(/,/g, ''));
                    lock.valueUSD = numAmount * currentPriceUSD;
                    lock.currentPriceUSD = currentPriceUSD; // Add current price info to lock
                }
            } catch (e) {
                this.logger.warn(`Failed to fetch current price for ${lock.tokenSymbol}:`, e);
            }
        }
    }

    mapLockData(detail: LockDetails, lockId: number): any {
        const basic = detail.lockData.basic;
        const totalAmount = basic?.totalAmount;
        const unlockTime = basic?.unlockTime || basic?.[3];
        const lockStartTime = basic?.lockStartTime || basic?.[4];
        const targetPriceUSD1e18 = detail.lockData.pricing?.targetPriceUSD1e18;

        if (totalAmount === null || totalAmount === undefined || unlockTime === null || unlockTime === undefined) {
            return {
                lockId: lockId,
                tokenSymbol: detail.tokenInfo.symbol,
                tokenAddress: detail.tokenAddress,
                amount: '0',
                unlockDate: new Date(),
                timeProgressPercent: 0,
                priceProgressPercent: 0,
                hasPrice: false,
                timeOk: false,
                priceOk: false,
                status: 'Invalid'
            };
        }

        const unlockTimestamp = timestampToNumber(unlockTime);
        const unlockDate = new Date(unlockTimestamp * 1000);

        const now = Date.now();
        const creationTimestamp = lockStartTime ? timestampToNumber(lockStartTime) * 1000 : 0;
        const unlockTimeMs = unlockTimestamp * 1000;

        let timeProgressPercent = 0;
        if (creationTimestamp > 0) {
            const totalDuration = unlockTimeMs - creationTimestamp;
            const elapsed = now - creationTimestamp;
            timeProgressPercent = totalDuration > 0 ? Math.min(Math.max((elapsed / totalDuration) * 100, 0), 100) : 0;
        } else {
            timeProgressPercent = now >= unlockTimeMs ? 100 : 0;
        }

        const timeOk = now >= unlockTimeMs;
        const status = detail.status || { timeOk: false, priceOk: false, timeProgressPercent: 0, priceProgressPercent: 0 };
        const priceProgressPercent = Number(status.priceProgressPercent || 0);
        const hasPrice = targetPriceUSD1e18 && targetPriceUSD1e18 > 0n;
        const priceOk = hasPrice ? (status.priceOk || false) : false;
        const isUnlockable = hasPrice ? (timeOk || priceOk) : timeOk;

        const tokenSymbol = detail.tokenInfo.symbol.toUpperCase();
        const isUSDToken = tokenSymbol.includes('USD') || tokenSymbol === 'DAI' || tokenSymbol === 'USDT' || tokenSymbol === 'USDC';
        const formattedAmount = formatTokenAmount(totalAmount, Number(detail.tokenInfo.decimals));
        const numAmount = parseFloat(formattedAmount.replace(/,/g, ''));

        let valueUSD: number | null = null;
        if (isUSDToken) {
            valueUSD = numAmount;
        } else if (hasPrice && targetPriceUSD1e18) {
            const targetPriceUSD = Number(ethers.formatUnits(targetPriceUSD1e18, 18));
            valueUSD = numAmount * targetPriceUSD;
        }

        return {
            lockId: lockId,
            tokenSymbol: detail.tokenInfo.symbol,
            tokenAddress: detail.tokenAddress,
            amount: formattedAmount,
            valueUSD: valueUSD,
            unlockDate: unlockDate,
            timeProgressPercent: timeProgressPercent,
            priceProgressPercent: priceProgressPercent,
            hasPrice: hasPrice,
            timeOk: timeOk,
            priceOk: priceOk,
            status: isUnlockable ? 'Unlockable' : 'Locked',
            pricing: hasPrice ? detail.lockData.pricing : null
        };
    }

    getExplorerUrl(address: string): string {
        // Always return Etherscan link, even for test mode
        // In test mode, the contract won't exist on Etherscan, but the link format is correct
        return `https://etherscan.io/address/${address}`;
    }

    truncateAddress(address: string): string {
        if (!address) return '';
        return `${address.substring(0, 6)}...${address.substring(address.length - 4)}`;
    }

    togglePairsV2() {
        this.showPairsV2 = !this.showPairsV2;
    }

    togglePairsV3() {
        this.showPairsV3 = !this.showPairsV3;
    }

    copyAddress(address: string, event: Event) {
        event.preventDefault();
        event.stopPropagation();
        navigator.clipboard.writeText(address);
        this.toastService.success(this.translate.instant('DASHBOARD.SUCCESS.COPY'));
    }

    getChainName(): string {
        if (this.chainId === null) return 'DASHBOARD.NETWORK';
        if (this.chainId === BigInt(1)) return 'DASHBOARD.ETHEREUM_MAINNET';
        if (this.chainId === BigInt(1337)) return 'DASHBOARD.LOCAL_TESTNET';
        return 'DASHBOARD.NETWORK';
    }

    ngOnDestroy(): void {
        this.logger.debug('[DashboardComponent] destroyed');
    }
}
