import { Component, ChangeDetectionStrategy, EventEmitter, Input, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { OfflineWorkflowComponent } from '@components/ui/offline-workflow/offline-workflow.component';
import { LockDetails, ContractService } from '@services/contract.service';
import { ethers } from 'ethers';
import { LoggerService } from "@services/logger.service";

export interface CollectedSignature {
    signer: string;
    signature: string;
    timestamp: Date;
}

@Component({
    selector: 'app-unlock-tokens-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, ContactInputComponent, OfflineWorkflowComponent],
    templateUrl: './unlock-tokens-modal.component.html',
    styleUrls: ['./unlock-tokens-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class UnlockTokensModalComponent implements OnInit, OnDestroy {
    @Input() lock!: LockDetails;
    @Input() showTabletBatchQr = false;
    @Input() tabletBatchRequestQr: string | null = null;
    @Input() progressiveThreshold = 3;
    @Input() tabletBatchSignatures: CollectedSignature[] = [];
    @Input() lastBatchValidation: any = null;
    @Input() executing = false;

    @Input() unlockAmount = '';
    @Output() unlockAmountChange = new EventEmitter<string>();

    @Input() recipient = '';
    @Output() recipientChange = new EventEmitter<string>();

    @Input() fromAddress = '';
    @Output() fromAddressChange = new EventEmitter<string>();

    @Output() close = new EventEmitter<void>();
    @Output() startTabletBatchUnlock = new EventEmitter<void>();
    @Output() cancelTabletBatchUnlock = new EventEmitter<void>();
    @Output() handleBatchSignatureScan = new EventEmitter<string>();
    @Output() removeCollectedSignature = new EventEmitter<number>();
    @Output() executeTabletBatchUnlock = new EventEmitter<void>();

    constructor(private contractService: ContractService, private logger: LoggerService) { }

    setMaxUnlock() {
        if (!this.lock || !this.lock.lockData.basic?.availableAmount) return;
        const amount = ethers.formatUnits(this.lock.lockData.basic.availableAmount, Number(this.lock.tokenInfo.decimals));
        this.unlockAmount = amount;
        this.unlockAmountChange.emit(this.unlockAmount);
    }

    setPercentageUnlock(percentage: number) {
        if (!this.lock || !this.lock.lockData.basic?.availableAmount) return;

        const availableAmount = BigInt(this.lock.lockData.basic.availableAmount.toString());
        const percentAmount = (availableAmount * BigInt(percentage)) / BigInt(100);

        const amountStr = ethers.formatUnits(percentAmount, Number(this.lock.tokenInfo.decimals));
        // Remove trailing zeros and unnecessary decimal point for aesthetics if needed, but ethers formatting is usually clean enough
        this.unlockAmount = amountStr;
        this.unlockAmountChange.emit(this.unlockAmount);
    }

    setRecipientToMe() {
        const acc = this.contractService.account$.value;
        if (acc) {
            this.recipient = acc;
            this.recipientChange.emit(this.recipient);
        }
    }

    setFromAddressToMe() {
        const acc = this.contractService.account$.value;
        if (acc) {
            this.fromAddress = acc;
            this.fromAddressChange.emit(this.fromAddress);
        }
    }

    onUnlockAmountChange(val: string) {
        this.unlockAmount = val;
        this.unlockAmountChange.emit(this.unlockAmount);
    }

    onRecipientChange(val: string) {
        this.recipient = val;
        this.recipientChange.emit(this.recipient);
    }

    onFromAddressChange() {
        this.fromAddressChange.emit(this.fromAddress);
    }

    ngOnInit(): void {
        this.logger.debug('[UnlockTokensModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[UnlockTokensModalComponent] destroyed');
    }
}
