import { TranslateModule } from '@ngx-translate/core';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { TransactionInterceptorService, TransactionMode, ModeSelectionRequest } from '@services/transaction-interceptor.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-tx-mode-modal',
    standalone: true,
    imports: [CommonModule, IconComponent, TranslateModule],
    templateUrl: './tx-mode-modal.component.html',
    styleUrls: ['./tx-mode-modal.component.css']
})
export class TxModeModalComponent implements OnInit, OnDestroy {
    showModal = false;
    request: ModeSelectionRequest | null = null;

    private subscription: Subscription | null = null;

    constructor(private txInterceptor: TransactionInterceptorService, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[TxModeModalComponent] initialized');
        this.subscription = this.txInterceptor.modeSelection$.subscribe(request => {
            this.request = request;
            this.showModal = request !== null;
        });
    }

    ngOnDestroy() {
        this.logger.debug('[TxModeModalComponent] destroyed');
        this.subscription?.unsubscribe();
    }

    selectDirect() {
        this.txInterceptor.selectMode(TransactionMode.DIRECT);
        this.close();
    }

    selectOffline() {
        this.txInterceptor.selectMode(TransactionMode.OFFLINE);
        this.close();
    }

    cancel() {
        this.txInterceptor.selectMode(null);
        this.close();
    }

    private close() {
        this.showModal = false;
        this.request = null;
    }

    formatValue(value: string): string {
        if (!value || value === '0') return '0 ETH';
        try {
            const eth = parseFloat(value) / 1e18;
            return `${eth.toFixed(6)} ETH`;
        } catch {
            return '0 ETH';
        }
    }
}
