import { Component, ChangeDetectionStrategy, EventEmitter, Input, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { OfflineWorkflowComponent, OfflineWorkflowVerification } from '@components/ui/offline-workflow/offline-workflow.component';
import { LockDetails, ContractService } from '@services/contract.service';
import { NumberFormatPipe } from '@utils/number-format.pipe';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-vesting-unlock-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, ContactInputComponent, OfflineWorkflowComponent, NumberFormatPipe],
    templateUrl: './vesting-unlock-modal.component.html',
    styleUrls: ['./vesting-unlock-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class VestingUnlockModalComponent implements OnInit, OnDestroy {
    @Input() lock!: LockDetails;
    @Input() loadingVesting = false;
    @Input() vestingConfig: any = null;
    @Input() vestedAmountAvailable = '0';
    @Input() vestingRequestQr: string | null = null;
    @Input() executing = false;
    @Input() vestingSignerVerification: OfflineWorkflowVerification | null = null;

    @Input() vestingRecipient = '';
    @Output() vestingRecipientChange = new EventEmitter<string>();

    @Input() fromAddress = '';
    @Output() fromAddressChange = new EventEmitter<string>();

    @Output() close = new EventEmitter<void>();
    @Output() startVestingUnlockWorkflow = new EventEmitter<void>();
    @Output() cancelVestingUnlock = new EventEmitter<void>();
    @Output() handleVestingSignaturePasted = new EventEmitter<string>();
    @Output() submitVerifiedVestingUnlock = new EventEmitter<void>();
    @Output() resetVestingVerification = new EventEmitter<void>();

    constructor(private contractService: ContractService, private logger: LoggerService) { }

    setVestingRecipientToMe() {
        const acc = this.contractService.account$.value;
        if (acc) {
            this.vestingRecipient = acc;
            this.vestingRecipientChange.emit(this.vestingRecipient);
        }
    }

    setFromAddressToMe() {
        const acc = this.contractService.account$.value;
        if (acc) {
            this.fromAddress = acc;
            this.fromAddressChange.emit(this.fromAddress);
        }
    }

    onRecipientChange(val: string) {
        this.vestingRecipient = val;
        this.vestingRecipientChange.emit(this.vestingRecipient);
    }

    onFromAddressChange() {
        this.fromAddressChange.emit(this.fromAddress);
    }

    ngOnInit(): void {
        this.logger.debug('[VestingUnlockModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[VestingUnlockModalComponent] destroyed');
    }
}
