import { Injectable } from '@angular/core';
import { ethers } from 'ethers';
import { WalletManagerService } from './wallet-manager.service';
import { LoggerService } from "@services/logger.service";

export interface StoredWallet {
    address: string;
    mnemonic: string;
    label: string;
    addedAt: number;
}

@Injectable({
    providedIn: 'root'
})
export class WalletSignatureService {
    constructor(private walletManager: WalletManagerService, private logger: LoggerService) { }

    /**
     * Get all wallets stored in WalletManager
     */
    getWallets(): StoredWallet[] {
        try {
            const wallets = this.walletManager.getAllWallets();
            // Convert WalletManagerService format to StoredWallet format
            return wallets.map(w => ({
                address: w.address,
                mnemonic: '', // Always empty - we don't expose encrypted mnemonics
                label: w.name,
                addedAt: Date.now() // We don't have this in WalletManagerService
            }));
        } catch (e) {
            this.logger.error('Failed to load wallets', e);
            return [];
        }
    }

    /**
     * Check if a wallet address is a valid signer
     */
    async isValidSigner(address: string, signersList: string[]): Promise<boolean> {
        return signersList.some(s => s.toLowerCase() === address.toLowerCase());
    }

    /**
     * Generate an EIP-712 signature for an unlock operation
     * @param password - Master password to decrypt wallet
     */
    async generateUnlockSignature(
        wallet: StoredWallet,
        password: string,
        lockId: number,
        to: string,
        amount: bigint,
        unlockNonce: bigint,
        lockerAddress: string,
        chainId: number
    ): Promise<string> {
        try {
            // 1. Calculate opKey (same as contract) - MUST use solidityPackedKeccak256 to match abi.encodePacked
            const opKey = ethers.solidityPackedKeccak256(
                ['string', 'uint256', 'address', 'uint256', 'uint256'],
                ['UNLOCK', lockId, to, amount, unlockNonce]
            );

            // 2. EIP-712 domain
            const domain = {
                name: 'LockerContract',
                version: '1',
                chainId: chainId,
                verifyingContract: lockerAddress
            };

            // 3. EIP-712 types
            const types = {
                ApproveOperation: [
                    { name: 'opKey', type: 'bytes32' },
                ]
            };

            // 4. Value
            const value = {
                opKey,
            };

            // 5. Sign using WalletManagerService (with password)
            const signature = await this.walletManager.signTypedData(wallet.address, password, domain, types, value);

            this.logger.debug('Generated signature', {
                wallet: wallet.address,
                opKey,
                signature: signature.substring(0, 20) + '...'
            });

            return signature;
        } catch (e: any) {
            this.logger.error('Failed to generate signature', e);
            throw new Error(`Signature generation failed: ${e.message}`);
        }
    }

    /**
     * Generate an EIP-712 signature for add signer operation
     * @param password - Master password to decrypt wallet
     */
    async generateAddSignerSignature(
        wallet: StoredWallet,
        password: string,
        newSigner: string,
        lockerAddress: string,
        chainId: number
    ): Promise<string> {
        try {
            // Calculate opKey - MUST use solidityPackedKeccak256 to match abi.encodePacked
            const opKey = ethers.solidityPackedKeccak256(
                ['string', 'address'],
                ['ADD_SIGNER', newSigner]
            );

            const domain = {
                name: 'LockerContract',
                version: '1',
                chainId: chainId,
                verifyingContract: lockerAddress
            };

            const types = {
                ApproveOperation: [
                    { name: 'opKey', type: 'bytes32' },
                ]
            };

            const value = {
                opKey,
            };

            return await this.walletManager.signTypedData(wallet.address, password, domain, types, value);
        } catch (e: any) {
            throw new Error(`Signature generation failed: ${e.message}`);
        }
    }

    /**
     * Format address for display
     */
    formatAddress(address: string): string {
        if (!address) return '';
        return `${address.substring(0, 6)}...${address.substring(address.length - 4)}`;
    }
}
