import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { IconComponent } from '../icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-language-selector',
    standalone: true,
    imports: [CommonModule, TranslateModule, IconComponent],
    templateUrl: './language-selector.component.html'
})
export class LanguageSelectorComponent implements OnInit, OnDestroy {
    isOpen = false;
    currentLang = 'en';

    languages = [
        { code: 'en', name: 'English', flag: '🇬🇧' },
        { code: 'fr', name: 'Français', flag: '🇫🇷' }
    ];

    constructor(private translate: TranslateService, private logger: LoggerService) { }

    ngOnInit() {
        this.logger.debug('[LanguageSelectorComponent] initialized');
        // Initialize language from translation service (which should read from localStorage)
        this.currentLang = this.translate.currentLang || this.translate.getDefaultLang() || 'en';
    }

    toggleModal() {
        this.isOpen = !this.isOpen;
    }

    closeModal() {
        this.isOpen = false;
    }

    selectLanguage(langCode: string) {
        this.translate.use(langCode);
        this.currentLang = langCode;
        localStorage.setItem('language', langCode);
        this.closeModal();
    }

    ngOnDestroy(): void {
        this.logger.debug('[LanguageSelectorComponent] destroyed');
    }
}
